/// Bound one scanner tick's terminal worker/coordinator/archive cleanup transaction.
const MAX_TERMINAL_FAMILY_COMPACTIONS_PER_TICK: usize = 32;

fn take_terminal_family_compaction_batch<T>(
    candidates: impl IntoIterator<Item = T>,
    remaining: &mut usize,
) -> Vec<T> {
    let batch = candidates.into_iter().take(*remaining).collect::<Vec<_>>();
    *remaining -= batch.len();
    batch
}

