    #[test]
    fn consolidation_completion_time_is_exactly_caller_supplied() {
        let private_clock_ms = 1_777_777_777_321_u64;
        assert_eq!(validate_consensus_now(private_clock_ms).unwrap(), private_clock_ms / 1_000);
        assert_eq!(
            validate_consensus_now(private_clock_ms + 5_000).unwrap(),
            private_clock_ms / 1_000 + 5
        );
        assert!(matches!(validate_consensus_now(0), Err(DepositServiceError::InvalidTime)));
    }

    #[test]
    fn empty_import_work_preserves_authenticated_finality() {
        assert_eq!(DepositService::state_import_work_census(None).unwrap(), (false, vec![]));
        let finalized = DepositStateImportTransportRecovery::Finalized {
            installed_certificate_digest: [1; 32],
            pending_certificate_deliveries: vec![],
        };
        assert_eq!(
            DepositService::state_import_work_census(Some(finalized)).unwrap(),
            (true, vec![]),
            "an authenticated final import must not be confused with an unstarted import",
        );
    }

    fn test_identity(party: PartyId, epoch: u64, salt: u8) -> Identity {
        let mut signing = [salt; 32];
        signing[0..2].copy_from_slice(&party.0.to_le_bytes());
        let mut encryption = [salt.wrapping_add(1); 32];
        encryption[0..8].copy_from_slice(&epoch.to_le_bytes());
        encryption[8..10].copy_from_slice(&party.0.to_le_bytes());
        Identity::from_test_secrets(party, epoch, &signing, encryption).unwrap()
    }

    fn test_committee(epoch: u64, salt: u8) -> (Committee, BTreeMap<PartyId, Identity>) {
        let identities = (1_u16..=4)
            .map(|number| {
                let party = PartyId(number);
                (party, test_identity(party, epoch, salt.wrapping_add(number as u8)))
            })
            .collect::<BTreeMap<_, _>>();
        let members = identities
            .values()
            .map(|identity| Member {
                id: identity.party(),
                signing_key: identity.signing_public_key(),
                encryption_key: identity.encryption_public_key(),
            })
            .collect();
        (Committee { epoch, threshold: 2, members }, identities)
    }

    fn test_deriver_with_root(root_scalar: u64) -> DepositAddressDeriver {
        let root = (ED25519_BASEPOINT_POINT * Scalar::from(root_scalar)).compress().to_bytes();
        DepositAddressDeriver::new(
            NetworkKind::Regtest,
            root,
            &Zeroizing::new(Scalar::from(17_u64).to_bytes()),
        )
        .unwrap()
    }

    fn test_deriver() -> DepositAddressDeriver {
        test_deriver_with_root(42)
    }

    fn test_registry(
        deriver: &DepositAddressDeriver,
        salt: u8,
    ) -> (CompactEpochRegistry, BTreeMap<PartyId, Identity>, DepositIndexHead) {
        let first_index = DepositSubaddressIndex::new(0, 1).unwrap();
        let portable = DepositIndexHead::empty_portable(deriver.wallet_id(), first_index).unwrap();
        let (committee, identities) = test_committee(0, salt);
        let target = VerifiedRegistryHandoffTarget::for_test(
            committee,
            1,
            [salt.wrapping_add(1); 32],
            [salt.wrapping_add(2); 32],
            deriver.wallet_id(),
            [salt.wrapping_add(3); 32],
            deriver.root_spend_key(),
        )
        .unwrap();
        let pending =
            prepare_compact_registry_genesis(&target, first_index, portable.digest()).unwrap();
        (pending.proposed_head().registry().clone(), identities, portable)
    }

    fn protocol_fixture()
    -> (DepositProtocolState, DepositAddressDeriver, BTreeMap<PartyId, Identity>, LedgerStatement)
    {
        let deriver = test_deriver();
        let (registry, identities, portable) = test_registry(&deriver, 0x20);
        let logical = PortableDepositIndexHead::from_head(&portable).unwrap();
        let ledger = CompactLedgerCursor::genesis(&registry, &logical).unwrap();
        let fixture_binding = RequestBinding([0x32; 32]);
        let allocation = LedgerStatement::allocation(
            &registry,
            ledger.next_sequence(),
            ledger.head(),
            deposit_request_id_for_binding(fixture_binding),
            fixture_binding,
            deriver.derive(ledger.next_index()),
            ChainPoint::new(10, [0x33; 32]).unwrap(),
            1_700_000_000,
        )
        .unwrap();
        let protocol = DepositProtocolState::genesis(PartyId(1), registry, ledger).unwrap();
        (protocol, deriver, identities, allocation)
    }

    fn client_request_authority(
        protocol: &DepositProtocolState,
        identities: &BTreeMap<PartyId, Identity>,
        origin: PartyId,
        request: DepositAddressRequest,
    ) -> DepositClientRequestWire {
        DepositClientRequestWire::new(&protocol.registry, request, identities.get(&origin).unwrap())
            .unwrap()
    }

    #[test]
    fn expired_allocation_fallback_refreshes_without_rewriting_its_admission() {
        let network = [0x55; 32];
        let (mut protocol, deriver, identities, statement) = protocol_fixture();
        let LedgerPayload::Allocation(allocation) = &statement.payload else { unreachable!() };
        let worker = DepositWorkerState::new(
            &deriver,
            allocation.recognition_anchor,
            DepositWorkerConfig::default(),
        )
        .unwrap();
        let identity = &identities[&PartyId(1)];
        let authority = client_request_authority(
            &protocol,
            &identities,
            PartyId(1),
            DepositAddressRequest { request: allocation.request, binding: allocation.binding },
        );
        let value =
            DepositConsensusValue::allocation(statement.clone(), authority.clone()).unwrap();
        let purpose = DepositConsensusPurpose::NextLedgerSlot { sequence: statement.sequence };
        let admitted_at = allocation.created_at - ALLOCATION_ISSUANCE_LEAD_SECONDS;
        let admission = validate_deposit_consensus_value(
            &protocol,
            &deriver,
            Some(&worker),
            &value,
            admitted_at,
            purpose,
            DepositConsensusAdmissionProvenance::Fresh,
            Some(network),
        )
        .unwrap();
        let context = deposit_consensus_context(&protocol, deriver.wallet_id(), network).unwrap();
        let mut reducer = DepositConsensus::new(context, PartyId(1)).unwrap();
        reducer.start(identity, value.clone()).unwrap();
        let mut lane = DurableDepositConsensusLane::new(
            purpose,
            reducer,
            admitted_at,
            admitted_at * 1_000 + 60_000,
        )
        .unwrap();
        install_consensus_admission(&mut lane, admission.clone()).unwrap();
        protocol.consensus_lane = Some(lane);
        assert!(
            !refresh_expired_allocation_candidate(
                &mut protocol,
                &deriver,
                &worker,
                identity,
                admitted_at
            )
            .unwrap()
        );
        let now = allocation.created_at + 120;
        assert!(
            refresh_expired_allocation_candidate(&mut protocol, &deriver, &worker, identity, now)
                .unwrap()
        );
        let lane = protocol.consensus_lane.as_ref().unwrap();
        assert_eq!(lane.reducer.view(), 0);
        assert_eq!(lane.admitted_values.get(&value.digest()), Some(&admission.admitted));
        let replacement = lane.reducer.candidate().unwrap();
        let decoded = DepositConsensusValue::decode(replacement).unwrap();
        assert_eq!(decoded.request_authority, Some(authority));
        assert_ne!(replacement, &value);
        validate_deposit_consensus_value(
            &protocol,
            &deriver,
            Some(&worker),
            replacement,
            now,
            purpose,
            DepositConsensusAdmissionProvenance::Fresh,
            Some(network),
        )
        .unwrap();
        let restarted = DepositLocalState::decode(
            &protocol.encode_local(&deriver).unwrap(),
            protocol.registry.clone(),
            protocol.ledger.clone(),
            &deriver,
            protocol.local_party,
            network,
        )
        .unwrap();
        assert_eq!(
            restarted.consensus_lane.as_ref().unwrap().reducer.candidate(),
            Some(replacement)
        );
        assert!(
            !refresh_expired_allocation_candidate(&mut protocol, &deriver, &worker, identity, now)
                .unwrap()
        );
    }

    #[test]
    fn certified_ledger_retires_only_an_uncommitted_lane_and_its_outbox() {
        let network = [0x55; 32];
        let (mut protocol, deriver, identities, statement) = protocol_fixture();
        let LedgerPayload::Allocation(allocation) = &statement.payload else { unreachable!() };
        let request =
            DepositAddressRequest { request: allocation.request, binding: allocation.binding };
        let authority = client_request_authority(&protocol, &identities, PartyId(1), request);
        let value =
            DepositConsensusValue::allocation(statement.clone(), authority.clone()).unwrap();
        let purpose = DepositConsensusPurpose::NextLedgerSlot { sequence: statement.sequence };
        let admitted_at = allocation.created_at - MIN_ALLOCATION_CERTIFICATION_LEAD_SECONDS;
        let admission = validate_deposit_consensus_value(
            &protocol,
            &deriver,
            None,
            &value,
            admitted_at,
            purpose,
            DepositConsensusAdmissionProvenance::Fresh,
            Some(network),
        )
        .unwrap();
        let context = deposit_consensus_context(&protocol, deriver.wallet_id(), network).unwrap();
        let mut reducer = DepositConsensus::new(context.clone(), PartyId(1)).unwrap();
        let initial = reducer.start(&identities[&PartyId(1)], value.clone()).unwrap();
        assert!(initial.commit.is_none());
        let mut lane = DurableDepositConsensusLane::new(
            purpose,
            reducer,
            admitted_at,
            admitted_at * 1_000 + 60_000,
        )
        .unwrap();
        install_consensus_admission(&mut lane, admission).unwrap();
        protocol.consensus_lane = Some(lane);
        protocol.validate(&deriver).unwrap();

        let payload = statement.attestation_payload().unwrap();
        let attestations = identities
            .values()
            .take(3)
            .map(|identity| {
                identity
                    .sign_envelope(
                        protocol.registry.active().committee(),
                        statement.slot_session(),
                        None,
                        statement.sequence,
                        payload.clone(),
                    )
                    .unwrap()
            })
            .collect::<Vec<_>>();
        let entry = CertifiedLedgerEntry { statement: statement.clone(), attestations };
        entry.verify_active(&protocol.registry, None).unwrap();

        let dominated =
            DepositConsensusOutboxScope { sequence: purpose.sequence(), context: context.digest() };
        let retained = protocol.retain_certified_pending(&entry, None).unwrap();
        assert_eq!(retained.dominated_consensus, Some(dominated));
        assert!(protocol.consensus_lane.is_none());
        assert!(protocol.has_certified_ledger_slot(statement.sequence));
        protocol.validate(&deriver).unwrap();

        let replayed = protocol.clone();
        assert_eq!(
            protocol.retain_certified_pending(&entry, None).unwrap().dominated_consensus,
            None,
        );
        assert_eq!(protocol, replayed, "an exact certificate replay is a no-op");

        // Model the same atomic reducer/outbox CAS used by QUIC certificate ingress. Only the
        // obsolete BA scope is retired; unrelated durable delivery survives restart.
        let (mut runtime, _, _) = byzantine_authority_fixture();
        runtime.snapshot.outbox.clear();
        runtime.snapshot.outbox_bodies.clear();
        let vote = sign_consensus_message(
            &context,
            &identities[&PartyId(2)],
            ConsensusMessageBody::Prevote(Vote { view: 0, value: value.digest() }),
        )
        .unwrap();
        let consensus_body =
            postcard::to_allocvec(&DepositConsensusWire::envelope(context.clone(), purpose, vote))
                .unwrap();
        let unrelated_binding = RequestBinding([0x9a; 32]);
        let unrelated_request = DepositAddressRequest {
            request: deposit_request_id_for_binding(unrelated_binding),
            binding: unrelated_binding,
        };
        let unrelated = DepositClientRequestWire::new(
            &protocol.registry,
            unrelated_request,
            &identities[&PartyId(1)],
        )
        .unwrap();
        runtime
            .snapshot
            .enqueue_many([
                (
                    statement.sequence,
                    PartyId(2),
                    DepositOperation::ConsensusMessage,
                    consensus_body,
                ),
                (
                    statement.sequence,
                    PartyId(2),
                    DepositOperation::ClientRequest,
                    postcard::to_allocvec(&unrelated).unwrap(),
                ),
            ])
            .unwrap();
        runtime
            .snapshot
            .replace_reducer_prune_consensus_and_enqueue(
                protocol.encode_local(&deriver).unwrap(),
                [dominated],
                [],
            )
            .unwrap();
        assert_eq!(runtime.snapshot.outbox.len(), 1);
        assert!(
            runtime
                .snapshot
                .outbox
                .keys()
                .all(|id| id.operation == DepositOperation::ClientRequest),
        );
        let restarted =
            DepositServiceSnapshot::from_bytes(&runtime.snapshot.to_bytes().unwrap()).unwrap();
        let restored = DepositLocalState::decode(
            &restarted.reducer,
            protocol.registry.clone(),
            protocol.ledger.clone(),
            &deriver,
            PartyId(1),
            network,
        )
        .unwrap();
        assert!(restored.consensus_lane.is_none());
        assert!(restored.has_certified_ledger_slot(statement.sequence));
        assert_eq!(restarted.outbox.len(), 1);

        // A locally committed conflicting value remains immutable. The external certificate may
        // dominate only an undecided reducer.
        let mut committed = DepositProtocolState::genesis(
            PartyId(1),
            protocol.registry.clone(),
            protocol.ledger.clone(),
        )
        .unwrap();
        let conflicting_binding = RequestBinding([0x9b; 32]);
        let conflicting_statement = LedgerStatement::allocation(
            &committed.registry,
            committed.ledger.next_sequence(),
            committed.ledger.head(),
            deposit_request_id_for_binding(conflicting_binding),
            conflicting_binding,
            deriver.derive(committed.ledger.next_index()),
            allocation.recognition_anchor,
            allocation.created_at,
        )
        .unwrap();
        let conflicting_request = DepositAddressRequest {
            request: deposit_request_id_for_binding(conflicting_binding),
            binding: conflicting_binding,
        };
        let conflicting_authority =
            client_request_authority(&committed, &identities, PartyId(1), conflicting_request);
        let conflicting_value =
            DepositConsensusValue::allocation(conflicting_statement.clone(), conflicting_authority)
                .unwrap();
        let conflicting_admission = validate_deposit_consensus_value(
            &committed,
            &deriver,
            None,
            &conflicting_value,
            admitted_at,
            purpose,
            DepositConsensusAdmissionProvenance::Fresh,
            Some(network),
        )
        .unwrap();
        let commit_witnesses = identities
            .values()
            .take(context.quorum())
            .map(|identity| {
                sign_consensus_message(
                    &context,
                    identity,
                    ConsensusMessageBody::Precommit(Vote {
                        view: 0,
                        value: conflicting_value.digest(),
                    }),
                )
                .unwrap()
            })
            .collect();
        let certificate =
            CommitCertificate::from_witnesses(&context, 0, conflicting_value, commit_witnesses)
                .unwrap();
        let mut conflicting_reducer = DepositConsensus::new(context, PartyId(1)).unwrap();
        conflicting_reducer
            .handle_commit_certificate_with_validator(certificate, |_| true)
            .unwrap();
        let mut conflicting_lane = DurableDepositConsensusLane::new(
            purpose,
            conflicting_reducer,
            admitted_at,
            admitted_at * 1_000 + 60_000,
        )
        .unwrap();
        install_consensus_admission(&mut conflicting_lane, conflicting_admission).unwrap();
        committed.consensus_lane = Some(conflicting_lane);
        committed.pending.insert(
            conflicting_statement.sequence,
            PendingLedgerSlot { statement: conflicting_statement, attestations: BTreeMap::new() },
        );
        committed.validate(&deriver).unwrap();
        let before = committed.clone();
        assert!(matches!(
            committed.retain_certified_pending(&entry, None),
            Err(DepositServiceError::SlotConflict(sequence)) if sequence == statement.sequence,
        ));
        assert_eq!(committed, before);
    }

    #[tokio::test]
    async fn idle_consensus_commit_does_not_revalidate_unchanged_runtime() {
        let state = tempfile::tempdir().unwrap();
        let identity = compaction_identity();
        let service = DepositService::new(
            PartyId(1),
            compaction_scenario(&identity),
            state.path(),
            &[0x6a; 32],
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            Arc::new(CompactionChain::default()),
        )
        .unwrap();
        let prepared =
            service.prepare_genesis(&compaction_epoch_public(&identity), [0x6b; 32]).await.unwrap();
        service.install_prepared_genesis(prepared, None, None).await.unwrap();
        let mut guard = service.runtime.lock().await;
        let runtime = guard.as_mut().unwrap();
        let snapshot = runtime.snapshot.clone();
        CONSENSUS_COMMIT_VALIDATIONS.set(0);
        service
            .commit_consensus_protocol(
                runtime,
                runtime.protocol.clone(),
                DepositConsensusHostEffects::default(),
                &identity,
            )
            .await
            .unwrap();
        assert_eq!(CONSENSUS_COMMIT_VALIDATIONS.get(), 0);
        assert_eq!(runtime.snapshot, snapshot);
    }

    #[tokio::test]
    async fn post_prepare_candidate_failure_fences_and_authentically_reopens_the_index() {
        let state = tempfile::tempdir().unwrap();
        let identity_seed = [0x6a; 32];
        let identity = compaction_identity();
        let scenario = compaction_scenario(&identity);
        let epoch_public = compaction_epoch_public(&identity);
        let service = DepositService::new(
            PartyId(1),
            scenario.clone(),
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            Arc::new(CompactionChain::default()),
        )
        .unwrap();
        let prepared = service.prepare_genesis(&epoch_public, [0x6b; 32]).await.unwrap();
        service.install_prepared_genesis(prepared, None, None).await.unwrap();

        let (wallet, error) = {
            let mut runtime_guard = service.runtime.lock().await;
            let runtime = runtime_guard.as_mut().unwrap();
            let statement = LedgerStatement::allocation(
                &runtime.protocol.registry,
                runtime.protocol.ledger.next_sequence(),
                runtime.protocol.ledger.head(),
                LedgerRequestId([0x6c; 32]),
                RequestBinding([0x6d; 32]),
                runtime.deriver.derive(runtime.protocol.ledger.next_index()),
                runtime.snapshot.worker().unwrap().reorg_checkpoint(),
                1_700_000_000,
            )
            .unwrap();
            let protocol = runtime.protocol.clone();
            let wallet = runtime.deriver.wallet_id();
            // `prepare_snapshot` succeeds first. Snapshot candidate construction then fails at its
            // revision increment, exactly modelling the pre-CAS error which formerly dropped the
            // prepared token while leaving `prepared_digest` live forever.
            runtime.snapshot.revision = u64::MAX;
            let error = service
                .commit_reserved_ledger_lock(runtime, protocol, &statement, false)
                .await
                .unwrap_err();
            (wallet, error)
        };
        assert!(matches!(error, DepositServiceError::RevisionExhausted));
        assert!(
            service.index_snapshot_recovery_required.load(Ordering::Acquire),
            "a post-prepare error must close public readiness until authenticated reopen"
        );
        assert!(service.deposit_index.lock().await.is_none());
        assert!(!service.local_runtime_ready());

        let spools = DepositSyncSpoolManager::new(
            state.path(),
            PartyId(1),
            &identity_seed,
            scenario.quic_network_id().unwrap(),
        )
        .unwrap();
        // Pause store reopening after recovery has inspected the runtime. Ordinary runtime
        // writers must not publish against that old snapshot while recovery replaces its stores.
        let index_guard = service.deposit_index.lock().await;
        let recovery = service.reconcile_live_deposit_sync_import(&spools);
        tokio::pin!(recovery);
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(100), &mut recovery)
                .await
                .is_err()
        );
        assert!(
            service.runtime.try_lock().is_err(),
            "live recovery released the runtime fence before publishing its replacement"
        );
        drop(index_guard);
        recovery.await.unwrap();
        assert!(service.local_runtime_ready());
        assert!(!service.index_snapshot_recovery_required.load(Ordering::Acquire));
        let durable = service.repository.load(wallet).await.unwrap();
        let runtime_guard = service.runtime.lock().await;
        let runtime = runtime_guard.as_ref().unwrap();
        assert_eq!(runtime.snapshot, durable);
        let mut index_guard = service.deposit_index.lock().await;
        let index = index_guard.as_mut().unwrap();
        assert_eq!(index.checkpoint(), durable.deposit_index_checkpoint());
        index.reset_bounded_cache().unwrap();
        drop(index_guard);
        drop(runtime_guard);

        // Readiness may be closed for a handoff rather than a damaged store. Pause recovery
        // at the registry and ensure it has not removed the already authenticated index.
        FULL_SNAPSHOT_RESTORATIONS.set(0);
        service.fence_local_runtime_for_test();
        let registry_guard = service.compact_registry.lock().await;
        let recovery = service.reconcile_live_deposit_sync_import(&spools);
        tokio::pin!(recovery);
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(100), &mut recovery)
                .await
                .is_err()
        );
        assert!(
            service.deposit_index.lock().await.is_some(),
            "recovery tore down an unchanged authenticated index"
        );
        drop(registry_guard);
        recovery.await.unwrap();
        assert!(service.local_runtime_ready());
        assert_eq!(
            FULL_SNAPSHOT_RESTORATIONS.get(),
            0,
            "an unchanged authenticated runtime was fully reconstructed again"
        );
    }

    const COMPACTION_CHAIN_TIP: u64 = 62;
    const COMPACTION_SIGNING_NOW: u64 = 1_700_000_000;

    fn compaction_chain_hash(height: u64) -> [u8; 32] {
        let mut hash = [0x90; 32];
        hash[..8].copy_from_slice(&height.to_le_bytes());
        hash
    }

    fn compaction_chain_point(height: u64) -> ChainPoint {
        ChainPoint::new(height, compaction_chain_hash(height)).unwrap()
    }

    fn compaction_root_output(transaction: [u8; 32]) -> PersistedRootOutput {
        let offset = Scalar::from(29_u64);
        let output_key = ED25519_BASEPOINT_POINT * (Scalar::from(42_u64) + offset);
        let commitment = Commitment::new(WalletScalar::from(Scalar::from(78_u64)), 9_000_000);
        let mut bytes = Vec::new();
        bytes.extend_from_slice(&transaction);
        bytes.extend_from_slice(&0_u64.to_le_bytes());
        bytes.extend_from_slice(&700_u64.to_le_bytes());
        bytes.extend_from_slice(&output_key.compress().to_bytes());
        bytes.extend_from_slice(&offset.to_bytes());
        commitment.write(&mut bytes).unwrap();
        Timelock::None.write(&mut bytes).unwrap();
        bytes.extend_from_slice(&[0, 0, 0]);
        let mut reader = Cursor::new(bytes.as_slice());
        let output = WalletOutput::read(&mut reader).unwrap();
        assert_eq!(usize::try_from(reader.position()).unwrap(), bytes.len());
        PersistedRootOutput::from_scanner(&output).unwrap()
    }

    struct CompactionChain {
        terminal: RwLock<Option<(SignedSweepTransaction, bool)>>,
        tip: RwLock<u64>,
    }

    impl Default for CompactionChain {
        fn default() -> Self {
            Self { terminal: RwLock::new(None), tip: RwLock::new(0) }
        }
    }

    impl CompactionChain {
        fn install(&self, transaction: SignedSweepTransaction, include_root: bool) {
            *self.terminal.write().unwrap() = Some((transaction, include_root));
        }

        fn set_tip(&self, tip: u64) {
            assert!(tip <= COMPACTION_CHAIN_TIP);
            *self.tip.write().unwrap() = tip;
        }
    }

    impl DepositChainSource for CompactionChain {
        fn latest_height(&self) -> ChainFuture<'_, u64> {
            Box::pin(async { Ok(*self.tip.read().unwrap()) })
        }

        fn block_hash(&self, height: u64) -> ChainFuture<'_, [u8; 32]> {
            Box::pin(async move {
                if height > *self.tip.read().unwrap() {
                    return Err(ChainSourceError::Invalid("height beyond test tip".to_owned()));
                }
                Ok(compaction_chain_hash(height))
            })
        }

        fn scanned_block_evidence<'a>(
            &'a self,
            height: u64,
            _deriver: &'a DepositAddressDeriver,
            _output_index: &'a dyn DepositOutputIndexBackend,
            _portable_snapshot: [u8; 32],
            resume: Option<crate::deposit_worker::DepositBlockScanCursor>,
        ) -> ChainFuture<'a, DepositBlockScanResult> {
            Box::pin(async move {
                if height == 0 || height > *self.tip.read().unwrap() || resume.is_some() {
                    return Err(ChainSourceError::Invalid("invalid test scan request".to_owned()));
                }
                let terminal = self.terminal.read().unwrap().clone();
                let included = terminal
                    .as_ref()
                    .filter(|(_, include_root)| height == 1 && *include_root)
                    .map(|(transaction, _)| transaction.clone());
                let root_outputs = included
                    .as_ref()
                    .map(|transaction| vec![compaction_root_output(transaction.transaction_id())])
                    .unwrap_or_default();
                let transaction_key_images = included
                    .as_ref()
                    .map(|transaction| {
                        canonical_sweep_transaction_key_images(transaction)
                            .map(|key_images| {
                                vec![CanonicalTransactionKeyImages {
                                    transaction: transaction.transaction_id(),
                                    key_images,
                                }]
                            })
                            .map_err(|error| ChainSourceError::Invalid(error.to_string()))
                    })
                    .transpose()?
                    .unwrap_or_default();
                Ok(DepositBlockScanResult::Complete(FetchedDepositBlockEvidence {
                    block: FetchedDepositBlock {
                        block: ScannedBlock {
                            point: compaction_chain_point(height),
                            parent_hash: compaction_chain_hash(height - 1),
                        },
                        timestamp: COMPACTION_SIGNING_NOW + height,
                        hardfork_version: 1,
                        outputs: Vec::new(),
                        root_outputs,
                    },
                    transactions: included.into_iter().collect(),
                    transaction_key_images,
                    transaction_key_images_complete: true,
                }))
            })
        }
    }

    struct BlockingLatestHeightChain {
        block_next: AtomicBool,
        entered: tokio::sync::Notify,
        release: tokio::sync::Notify,
    }

    impl BlockingLatestHeightChain {
        fn new() -> Self {
            Self {
                block_next: AtomicBool::new(false),
                entered: tokio::sync::Notify::new(),
                release: tokio::sync::Notify::new(),
            }
        }

        fn block_next_call(&self) {
            self.block_next.store(true, Ordering::Release);
        }
    }

    impl DepositChainSource for BlockingLatestHeightChain {
        fn latest_height(&self) -> ChainFuture<'_, u64> {
            Box::pin(async move {
                if self.block_next.swap(false, Ordering::AcqRel) {
                    self.entered.notify_one();
                    self.release.notified().await;
                }
                Ok(0)
            })
        }

        fn block_hash(&self, height: u64) -> ChainFuture<'_, [u8; 32]> {
            Box::pin(async move {
                if height != 0 {
                    return Err(ChainSourceError::Invalid(
                        "blocking fixture exposes only its birth anchor".to_owned(),
                    ));
                }
                Ok(compaction_chain_hash(0))
            })
        }

        fn scanned_block_evidence<'a>(
            &'a self,
            _height: u64,
            _deriver: &'a DepositAddressDeriver,
            _output_index: &'a dyn DepositOutputIndexBackend,
            _portable_snapshot: [u8; 32],
            _resume: Option<crate::deposit_worker::DepositBlockScanCursor>,
        ) -> ChainFuture<'a, DepositBlockScanResult> {
            Box::pin(async {
                Err(ChainSourceError::Invalid(
                    "blocking fixture must not scan beyond its birth anchor".to_owned(),
                ))
            })
        }
    }

    fn prepared_sweep_wallet_output() -> PersistedWalletOutput {
        let offset = Scalar::from(9_u64);
        let output_key = ED25519_BASEPOINT_POINT * (Scalar::from(42_u64) + offset);
        let commitment = Commitment::new(WalletScalar::from(Scalar::from(77_u64)), 10_000_000);
        let mut bytes = Vec::new();
        bytes.extend_from_slice(&[0xe1; 32]);
        bytes.extend_from_slice(&0_u64.to_le_bytes());
        bytes.extend_from_slice(&6_u64.to_le_bytes());
        bytes.extend_from_slice(&output_key.compress().to_bytes());
        bytes.extend_from_slice(&offset.to_bytes());
        commitment.write(&mut bytes).unwrap();
        Timelock::None.write(&mut bytes).unwrap();
        bytes.push(1);
        bytes.extend_from_slice(&0_u32.to_le_bytes());
        bytes.extend_from_slice(&1_u32.to_le_bytes());
        bytes.extend_from_slice(&[0, 0]);
        let mut reader = Cursor::new(bytes.as_slice());
        let output = WalletOutput::read(&mut reader).unwrap();
        assert_eq!(usize::try_from(reader.position()).unwrap(), bytes.len());
        PersistedWalletOutput::from_scanner(&output).unwrap()
    }

    struct PreparedSweepChain {
        tip: std::sync::atomic::AtomicU64,
        output: PersistedWalletOutput,
    }

    impl PreparedSweepChain {
        fn new() -> Self {
            Self {
                tip: std::sync::atomic::AtomicU64::new(0),
                output: prepared_sweep_wallet_output(),
            }
        }

        fn set_tip(&self, tip: u64) {
            self.tip.store(tip, Ordering::Release);
        }
    }

    impl DepositChainSource for PreparedSweepChain {
        fn latest_height(&self) -> ChainFuture<'_, u64> {
            Box::pin(async { Ok(self.tip.load(Ordering::Acquire)) })
        }

        fn block_hash(&self, height: u64) -> ChainFuture<'_, [u8; 32]> {
            Box::pin(async move {
                if height > self.tip.load(Ordering::Acquire) {
                    return Err(ChainSourceError::Invalid(
                        "height exceeds prepared-sweep fixture tip".to_owned(),
                    ));
                }
                Ok(compaction_chain_hash(height))
            })
        }

        fn scanned_block_evidence<'a>(
            &'a self,
            height: u64,
            _deriver: &'a DepositAddressDeriver,
            _output_index: &'a dyn DepositOutputIndexBackend,
            _portable_snapshot: [u8; 32],
            resume: Option<crate::deposit_worker::DepositBlockScanCursor>,
        ) -> ChainFuture<'a, DepositBlockScanResult> {
            Box::pin(async move {
                if height == 0 || height > self.tip.load(Ordering::Acquire) || resume.is_some() {
                    return Err(ChainSourceError::Invalid(
                        "invalid prepared-sweep scan request".to_owned(),
                    ));
                }
                Ok(DepositBlockScanResult::Complete(FetchedDepositBlockEvidence {
                    block: FetchedDepositBlock {
                        block: ScannedBlock {
                            point: compaction_chain_point(height),
                            parent_hash: compaction_chain_hash(height - 1),
                        },
                        timestamp: COMPACTION_SIGNING_NOW + height,
                        hardfork_version: 1,
                        outputs: (height == 1).then(|| self.output.clone()).into_iter().collect(),
                        root_outputs: Vec::new(),
                    },
                    transactions: Vec::new(),
                    transaction_key_images: Vec::new(),
                    transaction_key_images_complete: true,
                }))
            })
        }
    }

    struct PreparedSweepOutputIndex {
        wallet: DepositWalletId,
        portable_snapshot: [u8; 32],
        subaddress: DepositSubaddressIndex,
    }

    impl DepositOutputIndexBackend for PreparedSweepOutputIndex {
        fn portable_snapshot(&self, wallet: DepositWalletId) -> ChainFuture<'_, [u8; 32]> {
            Box::pin(async move {
                if wallet != self.wallet {
                    return Err(ChainSourceError::Invalid("wrong fixture wallet".to_owned()));
                }
                Ok(self.portable_snapshot)
            })
        }

        fn preload_subaddress_spend_keys<'a>(
            &'a self,
            wallet: DepositWalletId,
            portable_snapshot: [u8; 32],
            spend_keys: &'a [[u8; 32]],
        ) -> ChainFuture<'a, Vec<Option<DepositSubaddressIndex>>> {
            Box::pin(async move {
                if wallet != self.wallet || portable_snapshot != self.portable_snapshot {
                    return Err(ChainSourceError::Invalid(
                        "fixture portable snapshot changed".to_owned(),
                    ));
                }
                Ok(vec![Some(self.subaddress); spend_keys.len()])
            })
        }

        fn bind_outputs<'a>(
            &'a self,
            wallet: DepositWalletId,
            portable_snapshot: [u8; 32],
            bindings: &'a [DepositOutputBinding],
        ) -> ChainFuture<'a, ()> {
            Box::pin(async move {
                if wallet != self.wallet
                    || portable_snapshot != self.portable_snapshot
                    || bindings.iter().any(|binding| binding.subaddress != Some(self.subaddress))
                {
                    return Err(ChainSourceError::Invalid(
                        "fixture output binding differs".to_owned(),
                    ));
                }
                Ok(())
            })
        }

        fn classify_portable_output_bindings<'a>(
            &'a self,
            wallet: DepositWalletId,
            portable_snapshot: [u8; 32],
            bindings: &'a [DepositOutputBinding],
        ) -> ChainFuture<'a, Vec<PortableOutputBindingStatus>> {
            Box::pin(async move {
                if wallet != self.wallet || portable_snapshot != self.portable_snapshot {
                    return Err(ChainSourceError::Invalid(
                        "fixture portable snapshot changed".to_owned(),
                    ));
                }
                Ok(vec![PortableOutputBindingStatus::UnseenUnclaimed; bindings.len()])
            })
        }
    }

    struct BlockingValidationBackend {
        prepared: std::sync::Mutex<Option<PreparedFrostlassSweep>>,
        block_validation: AtomicBool,
        entered: tokio::sync::Semaphore,
        release: tokio::sync::Semaphore,
    }

    impl BlockingValidationBackend {
        fn new() -> Self {
            Self {
                prepared: std::sync::Mutex::new(None),
                block_validation: AtomicBool::new(false),
                entered: tokio::sync::Semaphore::new(0),
                release: tokio::sync::Semaphore::new(0),
            }
        }

        fn install_prepared(&self, prepared: PreparedFrostlassSweep) {
            let previous = self.prepared.lock().unwrap().replace(prepared);
            assert!(previous.is_none(), "fixture prepared sweep was already installed");
        }
    }

    impl DepositConsolidationBackend for BlockingValidationBackend {
        fn prepare_sweep<'a>(
            &'a self,
            _state: &'a DepositWorkerState,
            _deriver: &'a DepositAddressDeriver,
            _plan: &'a SweepPlan,
        ) -> ChainFuture<'a, PreparedFrostlassSweep> {
            Box::pin(async move {
                let prepared = {
                    let mut guard = self.prepared.lock().unwrap();
                    guard.take()
                };
                prepared.ok_or_else(|| {
                    ChainSourceError::Invalid("fixture prepared sweep was already consumed".into())
                })
            })
        }

        fn validate_prepared_sweep<'a>(
            &'a self,
            _state: &'a DepositWorkerState,
            _prepared: &'a PreparedFrostlassSweep,
        ) -> ChainFuture<'a, ()> {
            Box::pin(async move {
                if self.block_validation.load(Ordering::Acquire) {
                    self.entered.add_permits(1);
                    self.release
                        .acquire()
                        .await
                        .map_err(|_| {
                            ChainSourceError::Invalid(
                                "fixture validation release closed".to_owned(),
                            )
                        })?
                        .forget();
                }
                Ok(())
            })
        }

        fn publish_sweep<'a>(
            &'a self,
            _transaction: &'a monero_oxide::transaction::Transaction,
        ) -> ChainFuture<'a, ()> {
            Box::pin(async {
                Err(ChainSourceError::Invalid("fixture does not publish transactions".to_owned()))
            })
        }
    }

    #[test]
    fn scanner_daemon_stall_does_not_hold_the_deposit_runtime() {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .unwrap();
        runtime.block_on(async {
            tokio::spawn(async {
                let state = tempfile::tempdir().unwrap();
                let identity_seed = [0xd1; 32];
                let identity = compaction_identity();
                let scenario = compaction_scenario(&identity);
                let epoch_public = compaction_epoch_public(&identity);
                let source = Arc::new(BlockingLatestHeightChain::new());
                let service = DepositService::new(
                    PartyId(1),
                    scenario,
                    state.path(),
                    &identity_seed,
                    Zeroizing::new(Scalar::from(17_u64).to_bytes()),
                    DepositWorkerConfig::default(),
                    source.clone(),
                )
                .unwrap();
                let prepared = service.prepare_genesis(&epoch_public, [0xd2; 32]).await.unwrap();
                service.install_prepared_genesis(prepared, None, None).await.unwrap();

                source.block_next_call();
                let scanner = {
                    let service = service.clone();
                    tokio::spawn(async move { service.tick_worker().await })
                };
                tokio::time::timeout(Duration::from_secs(1), source.entered.notified())
                    .await
                    .expect("scanner must enter the blocked source");

                let epoch =
                    tokio::time::timeout(Duration::from_millis(100), service.active_epoch())
                        .await
                        .expect("runtime reads must not wait for a scanner RPC")
                        .unwrap();
                assert_eq!(epoch, 0);

                source.release.notify_one();
                tokio::time::timeout(Duration::from_secs(1), scanner)
                    .await
                    .expect("released scanner must finish")
                    .unwrap()
                    .unwrap();
            })
            .await
            .unwrap();
        });
    }

    #[test]
    fn blocked_index_preflight_cannot_install_an_expired_fresh_consensus_admission() {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .unwrap();
        runtime.block_on(async {
            tokio::spawn(async {
                const ENTRY_TIME: u64 = 1_700_000_000;

                let state = tempfile::tempdir().unwrap();
                let clock_path = state.path().join("deposit-clock");
                let identity_seed = [0xe2; 32];
                let identity = compaction_identity();
                let scenario = compaction_scenario(&identity);
                let epoch_public = compaction_epoch_public(&identity);
                let source = Arc::new(CompactionChain::default());
                let mut clock_writer = RegtestClockWriter::new(&scenario, &clock_path).unwrap();
                clock_writer.set_unix_seconds(ENTRY_TIME).unwrap();
                let deposit_clock = Arc::new(
                    DepositClock::configured(&scenario, true, Some(clock_path))
                        .expect("private Regtest clock"),
                );
                let service = DepositService::new_inner(
                    PartyId(1),
                    scenario.clone(),
                    state.path(),
                    &identity_seed,
                    Zeroizing::new(Scalar::from(17_u64).to_bytes()),
                    None,
                    DepositWorkerConfig::default(),
                    source,
                    None,
                    Arc::clone(&deposit_clock),
                )
                .unwrap();
                assert!(Arc::ptr_eq(&service.deposit_clock, &deposit_clock));
                let prepared = service.prepare_genesis(&epoch_public, [0xe3; 32]).await.unwrap();
                service.install_prepared_genesis(prepared, None, None).await.unwrap();

                let binding = RequestBinding([0xe4; 32]);
                let request = DepositAddressRequest {
                    request: deposit_request_id_for_binding(binding),
                    binding,
                };
                let (wire, wallet, before) = {
                    let mut guard = service.runtime.lock().await;
                    let runtime = guard.as_mut().unwrap();
                    let mut protocol = runtime.protocol.clone();
                    let authority =
                        DepositClientRequestWire::new(&protocol.registry, request, &identity)
                            .unwrap();
                    assert!(protocol.retain_client_request(&authority).unwrap());
                    service.commit_protocol(runtime, protocol).await.unwrap();

                    let recognition_anchor = runtime.snapshot.worker().unwrap().reorg_checkpoint();
                    runtime
                        .snapshot
                        .worker()
                        .unwrap()
                        .scan_state()
                        .verify_recognition_anchor(recognition_anchor)
                        .unwrap();
                    let statement = LedgerStatement::allocation(
                        &runtime.protocol.registry,
                        runtime.protocol.ledger.next_sequence(),
                        runtime.protocol.ledger.head(),
                        request.request,
                        request.binding,
                        runtime.deriver.derive(runtime.protocol.ledger.next_index()),
                        recognition_anchor,
                        ENTRY_TIME + ALLOCATION_ISSUANCE_LEAD_SECONDS,
                    )
                    .unwrap();
                    let purpose = DepositConsensusPurpose::NextLedgerSlot {
                        sequence: runtime.protocol.ledger.next_sequence(),
                    };
                    let value = DepositConsensusValue::allocation(statement, authority).unwrap();
                    let context = deposit_consensus_context(
                        &runtime.protocol,
                        runtime.deriver.wallet_id(),
                        scenario.quic_network_id().unwrap(),
                    )
                    .unwrap();
                    assert_eq!(context.leader(0), PartyId(1));
                    let proposal = sign_consensus_message(
                        &context,
                        &identity,
                        ConsensusMessageBody::Proposal(Proposal {
                            view: 0,
                            value,
                            proof_of_lock: None,
                            view_change: None,
                        }),
                    )
                    .unwrap();
                    (
                        DepositConsensusWire::envelope(context, purpose, proposal),
                        runtime.deriver.wallet_id(),
                        runtime.snapshot.clone(),
                    )
                };
                assert_eq!(service.deposit_clock_sample().unwrap().unix_seconds, ENTRY_TIME);

                // Holding the authenticated index makes the dependency preflight cross an await while the
                // handler retains the runtime lock. Advancing the same reader's backing generation during
                // that wait models the exact stale-entry-sample race.
                let index_guard = service.deposit_index.lock().await;
                assert!(index_guard.is_some());
                let delivery = {
                    let service = Arc::clone(&service);
                    tokio::spawn(async move {
                        let identity = compaction_identity();
                        service
                            .handle_consensus(
                                PartyId(1),
                                DepositOperation::ConsensusProposal,
                                wire,
                                ENTRY_TIME * 1_000,
                                &identity,
                            )
                            .await
                    })
                };
                tokio::time::timeout(Duration::from_secs(1), async {
                    loop {
                        if service.runtime.try_lock().is_err() {
                            break;
                        }
                        tokio::task::yield_now().await;
                    }
                })
                .await
                .expect("proposal handler did not reach the blocked index preflight");
                assert!(!delivery.is_finished());

                clock_writer
                    .set_unix_seconds(
                        ENTRY_TIME + ALLOCATION_ISSUANCE_LEAD_SECONDS
                            - MIN_ALLOCATION_CERTIFICATION_LEAD_SECONDS
                            + 1,
                    )
                    .unwrap();
                drop(index_guard);
                let result = tokio::time::timeout(Duration::from_secs(2), delivery)
                    .await
                    .expect("proposal handler did not resume after releasing the index")
                    .expect("proposal handler task panicked");
                assert!(
                    matches!(result, Err(DepositServiceError::AllocationExpired)),
                    "{result:?}"
                );

                let after = {
                    let guard = service.runtime.lock().await;
                    let runtime = guard.as_ref().unwrap();
                    assert!(runtime.protocol.consensus_lane.is_none());
                    runtime.snapshot.clone()
                };
                assert_eq!(after, before, "expired proposal changed the in-memory snapshot");
                assert_eq!(
                    service.repository.load(wallet).await.unwrap(),
                    before,
                    "expired proposal changed durable state",
                );
            })
            .await
            .unwrap();
        });
    }

    #[tokio::test]
    async fn plain_consensus_same_revision_conflict_restores_durable_runtime() {
        let state = tempfile::tempdir().unwrap();
        let identity_seed = [0xd3; 32];
        let identity = compaction_identity();
        let scenario = compaction_scenario(&identity);
        let epoch_public = compaction_epoch_public(&identity);
        let source = Arc::new(BlockingLatestHeightChain::new());
        let service = DepositService::new(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source,
        )
        .unwrap();
        let prepared = service.prepare_genesis(&epoch_public, [0xd4; 32]).await.unwrap();
        service.install_prepared_genesis(prepared, None, None).await.unwrap();

        let mut guard = service.runtime.lock().await;
        let runtime = guard.as_mut().unwrap();
        let stale_snapshot = runtime.snapshot.clone();

        let binding_a = RequestBinding([0xa1; 32]);
        let request_a = DepositAddressRequest {
            request: deposit_request_id_for_binding(binding_a),
            binding: binding_a,
        };
        let mut durable_protocol = runtime.protocol.clone();
        let authority_a =
            DepositClientRequestWire::new(&durable_protocol.registry, request_a, &identity)
                .unwrap();
        assert!(durable_protocol.retain_client_request(&authority_a).unwrap());
        let mut durable_candidate = stale_snapshot.clone();
        durable_candidate
            .replace_reducer_and_enqueue(
                durable_protocol.encode_local(&runtime.deriver).unwrap(),
                std::iter::empty(),
            )
            .unwrap();
        assert!(durable_candidate.is_plain_consensus_successor_of(&stale_snapshot));
        let durable = service.repository.persist_and_read_back(&durable_candidate).await.unwrap();
        let durable_consolidation = durable.consolidation().unwrap();

        // Simulate a cancelled request which crossed the wallet CAS but never published its
        // protocol/snapshot tuple. A different reducer successor from the stale runtime must lose
        // the same-revision CAS, authenticate and publish the durable winner, then ask its caller
        // to retry.
        let binding_b = RequestBinding([0xb1; 32]);
        let request_b = DepositAddressRequest {
            request: deposit_request_id_for_binding(binding_b),
            binding: binding_b,
        };
        let mut conflicting_protocol = runtime.protocol.clone();
        let authority_b =
            DepositClientRequestWire::new(&conflicting_protocol.registry, request_b, &identity)
                .unwrap();
        assert!(conflicting_protocol.retain_client_request(&authority_b).unwrap());
        let error = service
            .commit_consensus_protocol(
                runtime,
                conflicting_protocol,
                DepositConsensusHostEffects::default(),
                &identity,
            )
            .await
            .unwrap_err();
        assert!(matches!(error, DepositServiceError::StorageRevisionMismatch));
        assert_eq!(runtime.snapshot, durable);
        assert_eq!(runtime.protocol, durable_protocol);
        assert_eq!(runtime.consolidation, durable_consolidation);
        assert_eq!(
            service.repository.load(runtime.deriver.wallet_id()).await.unwrap(),
            runtime.snapshot,
        );

        // Recovery is not a terminal fence: the healed runtime can immediately commit its next
        // reducer-only successor.
        let healed_revision = runtime.snapshot.revision;
        let mut successor = runtime.protocol.clone();
        assert_eq!(successor.clear_client_requests_for_handoff(), 1);
        service
            .commit_consensus_protocol(
                runtime,
                successor.clone(),
                DepositConsensusHostEffects::default(),
                &identity,
            )
            .await
            .unwrap();
        assert_eq!(runtime.snapshot.revision, healed_revision + 1);
        assert_eq!(runtime.protocol, successor);
        assert_eq!(
            service.repository.load(runtime.deriver.wallet_id()).await.unwrap(),
            runtime.snapshot,
        );
    }

    #[test]
    fn committed_ledger_lock_crash_regossips_exact_commit_once_after_restart() {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .unwrap();
        runtime.block_on(async {
            tokio::spawn(async {
                let state = tempfile::tempdir().unwrap();
        let identity_seed = [0xda; 32];
        let activation_root = [0xdb; 32];
        let (scenario, epoch_public, identities) = committed_tail_recovery_fixture();
        let identity = &identities[&PartyId(1)];
        let source = Arc::new(CompactionChain::default());
        let service = DepositService::new(
            PartyId(1),
            scenario.clone(),
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source.clone(),
        )
        .unwrap();
        let prepared = service.prepare_genesis(&epoch_public, activation_root).await.unwrap();
        service.install_prepared_genesis(prepared, None, None).await.unwrap();

        let now = COMPACTION_SIGNING_NOW;
        let network = scenario.quic_network_id().unwrap();
        let (statement, value, purpose, context) = {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            let recognition_anchor = runtime.snapshot.worker().unwrap().reorg_checkpoint();
            let binding = RequestBinding([0xdd; 32]);
            let request =
                DepositAddressRequest { request: deposit_request_id_for_binding(binding), binding };
            let mut candidate = runtime.protocol.clone();
            let authority =
                DepositClientRequestWire::new(&candidate.registry, request, identity).unwrap();
            assert!(candidate.retain_client_request(&authority).unwrap());
            let statement = LedgerStatement::allocation(
                &candidate.registry,
                candidate.ledger.next_sequence(),
                candidate.ledger.head(),
                request.request,
                request.binding,
                runtime.deriver.derive(candidate.ledger.next_index()),
                recognition_anchor,
                now.checked_add(ALLOCATION_ISSUANCE_LEAD_SECONDS).unwrap(),
            )
            .unwrap();
            let purpose = DepositConsensusPurpose::NextLedgerSlot { sequence: statement.sequence };
            let value = DepositConsensusValue::allocation(statement.clone(), authority).unwrap();
            let admission = validate_deposit_consensus_value(
                &candidate,
                &runtime.deriver,
                Some(runtime.snapshot.worker().unwrap()),
                &value,
                now,
                purpose,
                DepositConsensusAdmissionProvenance::Fresh,
                Some(network),
            )
            .unwrap();
            let context =
                deposit_consensus_context(&candidate, runtime.deriver.wallet_id(), network)
                    .unwrap();
            let mut reducer = DepositConsensus::new(context.clone(), PartyId(1)).unwrap();
            let start = reducer.start(identity, value.clone()).unwrap();
            let deadline_unix_ms = service
                .consensus_deadline(now.checked_mul(1_000).unwrap(), reducer.view())
                .unwrap();
            let mut lane =
                DurableDepositConsensusLane::new(purpose, reducer, now, deadline_unix_ms).unwrap();
            install_consensus_admission(&mut lane, admission).unwrap();
            candidate.consensus_lane = Some(lane);
            let effects = service
                .consensus_step_effects(
                    &mut candidate,
                    &runtime.deriver,
                    identity,
                    now.checked_mul(1_000).unwrap(),
                    start,
                )
                .unwrap();
            assert!(
                effects.messages.iter().any(|(_, _, operation, _)| matches!(
                    operation,
                    DepositOperation::ConsensusProposal | DepositOperation::ConsensusMessage
                )),
                "the crash fixture must retain pre-decision BA traffic",
            );
            service.commit_consensus_protocol(runtime, candidate, effects, identity).await.unwrap();
            (statement, value, purpose, context)
        };

        let precommits = [PartyId(2), PartyId(3), PartyId(4), PartyId(5)]
            .into_iter()
            .map(|party| {
                sign_consensus_message(
                    &context,
                    &identities[&party],
                    ConsensusMessageBody::Precommit(Vote { view: 0, value: value.digest() }),
                )
                .unwrap()
            })
            .collect();
        let commit =
            CommitCertificate::from_witnesses(&context, 0, value.clone(), precommits).unwrap();
        let (wallet, crash_cut) = {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            let mut candidate = runtime.protocol.clone();
            let learned = candidate
                .consensus_lane
                .as_mut()
                .unwrap()
                .reducer
                .handle_commit_certificate_with_validator(commit.clone(), |candidate| {
                    candidate == &value
                })
                .unwrap();
            assert_eq!(learned.relay_commit_certificate, Some(commit.clone()));
            assert_eq!(learned.commit, Some(commit.clone()));

            let preflight = service.verified_index_preflight(&statement).await.unwrap();
            let LedgerPayload::Allocation(allocation) = &statement.payload else {
                panic!("fixture statement is an allocation");
            };
            let recognition = runtime
                .snapshot
                .worker()
                .unwrap()
                .scan_state()
                .verify_recognition_anchor(allocation.recognition_anchor)
                .unwrap();
            candidate
                .reserve(
                    statement.clone(),
                    now,
                    &runtime.deriver,
                    Some(&recognition),
                    None,
                    None,
                    &preflight,
                )
                .unwrap();

            // Persist only the first ledger-safety CAS and discard `learned`, exactly as if the
            // process stopped before the reducer/outbox tail was constructed.
            service
                .commit_reserved_ledger_lock(runtime, candidate, &statement, false)
                .await
                .unwrap();
            let slot = runtime.protocol.pending.get(&statement.sequence).unwrap();
            assert!(!slot.attestations.contains_key(&PartyId(1)));
            assert_eq!(
                runtime.protocol.consensus_lane.as_ref().unwrap().reducer.commit(),
                Some(&commit),
            );
            assert!(runtime.snapshot.outbox.keys().any(|id| matches!(
                id.operation,
                DepositOperation::ConsensusProposal | DepositOperation::ConsensusMessage
            )),);
            assert!(
                runtime
                    .snapshot
                    .outbox
                    .keys()
                    .all(|id| id.operation != DepositOperation::ConsensusCertificate),
            );
            assert_eq!(
                service.repository.load(runtime.deriver.wallet_id()).await.unwrap(),
                runtime.snapshot,
            );
            (runtime.deriver.wallet_id(), runtime.snapshot.clone())
        };
        drop(service);

        let restarted = DepositService::new(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source,
        )
        .unwrap();
        let prepared = restarted.prepare_genesis(&epoch_public, activation_root).await.unwrap();
        assert_eq!(restarted.install_prepared_genesis(prepared, None, None).await.unwrap(), wallet,);
        assert_eq!(restarted.runtime.lock().await.as_ref().unwrap().snapshot, crash_cut,);

        let recovery = restarted.recover_peer_messages(identity, now);
        assert!(
            std::mem::size_of_val(&recovery) <= 2 * std::mem::size_of::<usize>(),
            "initialization callers must retain only the boxed recovery future"
        );
        recovery.await.unwrap();
        let recovered = {
            let guard = restarted.runtime.lock().await;
            let runtime = guard.as_ref().unwrap();
            let slot = runtime.protocol.pending.get(&statement.sequence).unwrap();
            assert!(slot.attestations.contains_key(&PartyId(1)));
            assert!(
                runtime.snapshot.outbox.keys().all(|id| !matches!(
                    id.operation,
                    DepositOperation::ConsensusProposal | DepositOperation::ConsensusMessage
                )),
                "recovery must prune pre-decision traffic before re-gossiping the terminal proof",
            );
            let certificates = runtime
                .snapshot
                .outbox
                .iter()
                .filter(|(id, _)| id.operation == DepositOperation::ConsensusCertificate)
                .collect::<Vec<_>>();
            assert_eq!(certificates.len(), 4);
            assert_eq!(
                certificates.iter().map(|(id, _)| id.recipient).collect::<BTreeSet<_>>(),
                BTreeSet::from([PartyId(2), PartyId(3), PartyId(4), PartyId(5)]),
            );
            let expected_wire =
                DepositConsensusWire::commit_certificate(context, purpose, commit.clone());
            for (_, message) in certificates {
                assert_eq!(message.causal_lane, DepositCausalLane::Ledger);
                assert_eq!(
                    postcard::from_bytes::<DepositConsensusWire>(
                        &runtime.snapshot.outbox_bodies[&message.body_digest],
                    )
                    .unwrap(),
                    expected_wire,
                );
            }
            let attestations = runtime
                .snapshot
                .outbox
                .keys()
                .filter(|id| id.operation == DepositOperation::Attest)
                .collect::<Vec<_>>();
            assert_eq!(attestations.len(), 4);
            assert_eq!(
                attestations.iter().map(|id| id.recipient).collect::<BTreeSet<_>>(),
                BTreeSet::from([PartyId(2), PartyId(3), PartyId(4), PartyId(5)]),
            );
            assert_eq!(restarted.repository.load(wallet).await.unwrap(), runtime.snapshot,);
            runtime.snapshot.clone()
        };

        restarted.recover_peer_messages(identity, now).await.unwrap();
        let guard = restarted.runtime.lock().await;
        assert_eq!(
            guard.as_ref().unwrap().snapshot,
            recovered,
            "the durable local attestation must prevent a re-gossip loop",
        );
                assert_eq!(restarted.repository.load(wallet).await.unwrap(), recovered);
            })
            .await
            .unwrap();
        });
    }

