    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn deposit_sync_materialization_does_not_hold_the_deposit_runtime() {
        let state = tempfile::tempdir().unwrap();
        let identity_seed = [0xd4; 32];
        let identity = compaction_identity();
        let scenario = compaction_scenario(&identity);
        let epoch_public = compaction_epoch_public(&identity);
        let source = Arc::new(CompactionChain::default());
        let service = DepositService::new(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source,
        )
        .unwrap();
        let prepared = service.prepare_genesis(&epoch_public, [0xd5; 32]).await.unwrap();
        service.install_prepared_genesis(prepared, None, None).await.unwrap();
        let wallet = service.runtime.lock().await.as_ref().unwrap().deriver.wallet_id();

        let (advertisement, reference, bytes) = deposit_sync_cache_fixture(0xd6);
        let object = DepositSyncObject::new(reference, bytes).unwrap();
        let spool = DepositSyncSpoolStore::verified_for_materialization_test(
            state.path().join("materialization-spool"),
            PartyId(1),
            &identity_seed,
            &advertisement,
            std::slice::from_ref(&object),
        )
        .await
        .unwrap();
        let pause = spool.hold_mutation_for_test().await;
        let materialization = {
            let service = Arc::clone(&service);
            let spool = Arc::clone(&spool);
            tokio::spawn(async move { service.prepare_deposit_sync_import(&spool).await })
        };
        tokio::task::yield_now().await;
        assert!(
            !materialization.is_finished(),
            "the fixture must hold the materialization path at a spool storage await"
        );

        let epoch = tokio::time::timeout(Duration::from_millis(250), service.active_epoch())
            .await
            .expect("runtime reads must continue during deposit-sync materialization")
            .unwrap();
        assert_eq!(epoch, 0);
        let context =
            tokio::time::timeout(Duration::from_millis(250), service.deposit_sync_context())
                .await
                .expect("runtime status must continue during deposit-sync materialization")
                .unwrap();
        assert_eq!(context.wallet(), wallet);

        let binding = RequestBinding([0xd7; 32]);
        let request =
            DepositAddressRequest { request: deposit_request_id_for_binding(binding), binding };
        let _ = tokio::time::timeout(
            Duration::from_millis(250),
            service.address_status(request, 1_700_000_000),
        )
        .await
        .expect("allocation status must continue during deposit-sync materialization");

        drop(pause);
        let marker = tokio::time::timeout(Duration::from_secs(2), materialization)
            .await
            .expect("released materialization must finish")
            .unwrap()
            .unwrap();
        spool.abort_prepared_import(Some(&marker)).await.unwrap();
    }

    #[tokio::test]
    async fn deposit_sync_adoption_spool_wait_does_not_hold_the_deposit_runtime() {
        let source_fixture = compaction_service_fixture(false).await;
        let context = source_fixture.service.deposit_sync_context().await.unwrap();
        let advertisement =
            source_fixture.service.deposit_sync_advertisement(context).await.unwrap();
        assert!(advertisement.portable_index().through_sequence() > 0);
        assert!(!advertisement.certificate_archive().is_empty());

        let reference =
            DepositSyncObjectRef::Registry(advertisement.object_anchor().registry_root());
        let artifacts = WalletArtifactStore::new(
            source_fixture.service.deposit_index_directory.clone(),
            PartyId(1),
            &source_fixture.identity_seed,
        )
        .unwrap();
        let artifact =
            artifacts.load_artifact(reference.storage_reference().unwrap()).await.unwrap();
        let object = DepositSyncObject::new(reference, artifact.contents.into_bytes()).unwrap();

        let target_state = tempfile::tempdir().unwrap();
        let target_source = Arc::new(CompactionChain::default());
        let target = DepositService::new(
            PartyId(1),
            source_fixture.scenario.clone(),
            target_state.path(),
            &source_fixture.identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            target_source,
        )
        .unwrap();
        let prepared =
            target.prepare_genesis(&source_fixture.epoch_public, [0xb6; 32]).await.unwrap();
        target.install_prepared_genesis(prepared, None, None).await.unwrap();
        let active_target = target
            .verify_registry_handoff_target(None, &source_fixture.epoch_public, 0, [0xb6; 32])
            .await
            .unwrap();
        let spool = DepositSyncSpoolStore::verified_for_materialization_test(
            target_state.path(),
            PartyId(1),
            &source_fixture.identity_seed,
            &advertisement,
            std::slice::from_ref(&object),
        )
        .await
        .unwrap();
        let spools = DepositSyncSpoolManager::new(
            target_state.path(),
            PartyId(1),
            &source_fixture.identity_seed,
            source_fixture.scenario.quic_network_id().unwrap(),
        )
        .unwrap();

        let pause = spool.hold_mutation_for_test().await;
        // Queue adoption behind an already-held runtime guard. On the current-thread executor the
        // start signal is observed only after adoption polls the runtime lock and yields. Dropping
        // this guard therefore gives adoption the mutex first and makes the lock-scope assertion
        // deterministic rather than scheduler-dependent.
        let runtime_fence = target.runtime.lock().await;
        let (started_tx, started_rx) = tokio::sync::oneshot::channel();
        let adoption = {
            let target = Arc::clone(&target);
            let spool = Arc::clone(&spool);
            let advertisement = advertisement.clone();
            tokio::spawn(async move {
                let _ = started_tx.send(());
                target
                    .adopt_deposit_sync_candidate(advertisement, spool, &active_target, &spools)
                    .await
            })
        };
        started_rx.await.unwrap();
        drop(runtime_fence);
        tokio::task::yield_now().await;
        assert!(
            !adoption.is_finished(),
            "the fixture must hold adoption at an authenticated spool read"
        );

        let epoch = tokio::time::timeout(Duration::from_millis(250), target.active_epoch())
            .await
            .expect("runtime reads must continue while adoption waits on spool storage")
            .unwrap();
        assert_eq!(epoch, 0);
        tokio::time::timeout(Duration::from_millis(250), target.deposit_sync_context())
            .await
            .expect("runtime status must continue while adoption waits on spool storage")
            .unwrap();

        drop(pause);
        let result = tokio::time::timeout(Duration::from_secs(2), adoption)
            .await
            .expect("released adoption must finish")
            .unwrap();
        assert!(
            result.is_err(),
            "the synthetic one-object spool is intentionally not a complete candidate"
        );
    }

    #[test]
    fn blocked_existing_lane_validation_releases_runtime_and_cas_fails_stale() {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .unwrap();
        runtime.block_on(async {
            tokio::spawn(blocked_existing_lane_validation_body()).await.unwrap();
        });
    }

    async fn blocked_existing_lane_validation_body() {
        const NOW_MS: u64 = 1_700_000_000_000;
        let state = tempfile::tempdir().unwrap();
        let identity_seed = [0xe2; 32];
        let identity = compaction_identity();
        let scenario = compaction_scenario(&identity);
        let epoch_public = compaction_epoch_public(&identity);
        let source = Arc::new(PreparedSweepChain::new());
        let backend = Arc::new(BlockingValidationBackend::new());
        let service = DepositService::new_with_consolidation_backend(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source.clone(),
            backend.clone(),
        )
        .unwrap();
        let genesis = service.prepare_genesis(&epoch_public, [0xe3; 32]).await.unwrap();
        service.install_prepared_genesis(genesis, None, None).await.unwrap();
        source.set_tip(19);

        let prepared = {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            let mut worker = runtime.snapshot.worker().cloned().unwrap();
            let output_index = PreparedSweepOutputIndex {
                wallet: runtime.deriver.wallet_id(),
                portable_snapshot: worker.portable_index_head().unwrap(),
                subaddress: DepositSubaddressIndex::new(0, 1).unwrap(),
            };
            for _ in 0..16 {
                if worker.scan_state().tip().height >= 10 {
                    break;
                }
                let tick =
                    worker.tick(source.as_ref(), &runtime.deriver, &output_index).await.unwrap();
                assert!(tick.persistence.is_some());
                if let Some(events) = worker.replay_pending_events().unwrap() {
                    worker.acknowledge_events(events.id).unwrap();
                }
            }
            assert_eq!(worker.scan_state().tip().height, 19);
            let destination =
                root_consolidation_destination_binding(&runtime.deriver, worker.config());
            let plan = worker.plan_sweep(0, destination).unwrap().unwrap();
            let (input, amount) = compaction_transaction_input(&compaction_threshold_keys());
            assert_eq!(plan.total_input_atomic_units, amount);
            assert_eq!(plan.inputs, vec![prepared_sweep_wallet_output().id()]);
            let prepared = worker
                .prepare_sweep_from_components(
                    &runtime.deriver,
                    &plan,
                    [0xe4; 32],
                    vec![input],
                    FeeRate::new(1, 1).unwrap(),
                )
                .unwrap();
            let mut candidate = runtime.snapshot.clone();
            candidate.replace_worker(worker).unwrap();
            runtime.snapshot = service.repository.persist_and_read_back(&candidate).await.unwrap();
            prepared
        };
        backend.install_prepared(prepared);
        let transition = Arc::new(Mutex::new(()));

        let actions = service
            .progress_byzantine_consolidations(&identity, NOW_MS, 1_000, Arc::clone(&transition))
            .await
            .unwrap();
        let mut actions = actions.into_iter();
        let continuation = match actions.next().unwrap() {
            ByzantineConsolidationAction::BootstrapPrepared { continuation, .. } => continuation,
            _ => panic!("fresh threshold-one lane did not stop at its durable bootstrap gate"),
        };
        assert!(actions.next().is_none());
        service
            .continue_byzantine_bootstrap(&identity, continuation, NOW_MS, Arc::clone(&transition))
            .await
            .unwrap();

        let wallet = {
            let guard = service.runtime.lock().await;
            let runtime = guard.as_ref().unwrap();
            assert!(
                runtime
                    .snapshot
                    .byzantine_consensus_lane
                    .as_ref()
                    .unwrap()
                    .reducer
                    .commit()
                    .is_some()
            );
            assert_eq!(runtime.consolidation.records().count(), 0);
            runtime.deriver.wallet_id()
        };
        let durable_before = service.repository.load(wallet).await.unwrap();

        backend.block_validation.store(true, Ordering::Release);
        let progress = {
            let service = service.clone();
            let transition = Arc::clone(&transition);
            tokio::spawn(async move {
                let identity = compaction_identity();
                service
                    .progress_byzantine_consolidations(&identity, NOW_MS, 1_000, transition)
                    .await
            })
        };
        tokio::time::timeout(Duration::from_secs(1), backend.entered.acquire())
            .await
            .expect("existing-lane validation did not enter the backend")
            .unwrap()
            .forget();
        assert_eq!(
            tokio::time::timeout(Duration::from_millis(100), service.active_epoch())
                .await
                .expect("backend validation held the deposit runtime")
                .unwrap(),
            0
        );
        {
            let mut guard =
                tokio::time::timeout(Duration::from_millis(100), service.runtime.lock())
                    .await
                    .expect("backend validation held the exact-state CAS mutex");
            let runtime = guard.as_mut().unwrap();
            runtime.snapshot.revision = runtime.snapshot.revision.checked_add(1).unwrap();
        }
        backend.release.add_permits(1);
        let result = tokio::time::timeout(Duration::from_secs(1), progress)
            .await
            .expect("released validation did not finish")
            .unwrap();
        assert!(matches!(result, Err(DepositServiceError::StaleConsolidationCandidate)));

        let mut in_memory = service.runtime.lock().await.as_ref().unwrap().snapshot.clone();
        in_memory.revision = durable_before.revision;
        assert_eq!(in_memory, durable_before, "stale validation mutated the release snapshot");
        assert_eq!(service.repository.load(wallet).await.unwrap(), durable_before);
    }

    #[test]
    fn committed_successor_reconstructs_the_existing_sweep_reservation() {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .unwrap();
        runtime.block_on(async {
            tokio::spawn(committed_successor_reconstructs_the_existing_sweep_reservation_body())
                .await
                .unwrap();
        });
    }

    async fn committed_successor_reconstructs_the_existing_sweep_reservation_body() {
        const NOW_MS: u64 = 1_700_000_000_000;
        let state = tempfile::tempdir().unwrap();
        let identity_seed = [0xe5; 32];
        let identity = compaction_identity();
        let scenario = compaction_scenario(&identity);
        let epoch_public = compaction_epoch_public(&identity);
        let source = Arc::new(PreparedSweepChain::new());
        let backend = Arc::new(BlockingValidationBackend::new());
        let service = DepositService::new_with_consolidation_backend(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source.clone(),
            backend.clone(),
        )
        .unwrap();
        let genesis = service.prepare_genesis(&epoch_public, [0xe6; 32]).await.unwrap();
        service.install_prepared_genesis(genesis, None, None).await.unwrap();
        source.set_tip(19);

        let prepared = {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            let mut worker = runtime.snapshot.worker().cloned().unwrap();
            let output_index = PreparedSweepOutputIndex {
                wallet: runtime.deriver.wallet_id(),
                portable_snapshot: worker.portable_index_head().unwrap(),
                subaddress: DepositSubaddressIndex::new(0, 1).unwrap(),
            };
            for _ in 0..16 {
                if worker.scan_state().tip().height >= 10 {
                    break;
                }
                let tick =
                    worker.tick(source.as_ref(), &runtime.deriver, &output_index).await.unwrap();
                assert!(tick.persistence.is_some());
                if let Some(events) = worker.replay_pending_events().unwrap() {
                    worker.acknowledge_events(events.id).unwrap();
                }
            }
            assert_eq!(worker.scan_state().tip().height, 19);
            let destination =
                root_consolidation_destination_binding(&runtime.deriver, worker.config());
            let plan = worker.plan_sweep(0, destination).unwrap().unwrap();
            let (input, amount) = compaction_transaction_input(&compaction_threshold_keys());
            assert_eq!(plan.total_input_atomic_units, amount);
            assert_eq!(plan.inputs, vec![prepared_sweep_wallet_output().id()]);
            let prepared = worker
                .prepare_sweep_from_components(
                    &runtime.deriver,
                    &plan,
                    [0xe7; 32],
                    vec![input],
                    FeeRate::new(1, 1).unwrap(),
                )
                .unwrap();
            let mut candidate = runtime.snapshot.clone();
            candidate.replace_worker(worker).unwrap();
            runtime.snapshot = service.repository.persist_and_read_back(&candidate).await.unwrap();
            prepared
        };
        backend.install_prepared(prepared);
        let transition = Arc::new(Mutex::new(()));

        let mut bootstrap = service
            .progress_byzantine_consolidations(&identity, NOW_MS, 1_000, Arc::clone(&transition))
            .await
            .unwrap();
        let continuation = match bootstrap.pop().unwrap() {
            ByzantineConsolidationAction::BootstrapPrepared {
                outer_view: 0, continuation, ..
            } => continuation,
            action => panic!("unexpected view-zero bootstrap action: {action:?}"),
        };
        assert!(bootstrap.is_empty());
        service
            .continue_byzantine_bootstrap(&identity, continuation, NOW_MS, Arc::clone(&transition))
            .await
            .unwrap();

        let mut release = service
            .progress_byzantine_consolidations(&identity, NOW_MS, 1_000, Arc::clone(&transition))
            .await
            .unwrap();
        let (family, sweep, prepared_bytes) = match release.pop().unwrap() {
            ByzantineConsolidationAction::Release { family, view: 0, release, .. } => (
                family,
                release.authorization.sweep_id(),
                release.prepared.prepared_intent().encode().unwrap(),
            ),
            action => panic!("unexpected view-zero release action: {action:?}"),
        };
        assert!(release.is_empty());

        let (deadline, next_sweep_sequence, wallet) = {
            let guard = service.runtime.lock().await;
            let runtime = guard.as_ref().unwrap();
            assert!(runtime.snapshot.byzantine_consensus_lane.is_none());
            let roast = live_byzantine_roast(runtime).unwrap().unwrap();
            assert_eq!(roast.family_digest(), family);
            assert_eq!(roast.sweep_id(), sweep);
            assert_eq!(roast.next_view(), 1);
            let worker = runtime.snapshot.worker().unwrap();
            let retained = worker
                .scan_state()
                .sweep(sweep)
                .unwrap()
                .signing_intent
                .prepared_sweep_intent_bytes();
            assert_eq!(retained, prepared_bytes);
            (
                roast.outer_deadline_unix_ms(),
                worker.next_sweep_sequence(),
                runtime.deriver.wallet_id(),
            )
        };

        assert!(
            service
                .progress_byzantine_consolidations(
                    &identity,
                    deadline,
                    1_000,
                    Arc::clone(&transition),
                )
                .await
                .unwrap()
                .is_empty(),
            "threshold-one successor creation should commit without exposing a nonce"
        );
        {
            let guard = service.runtime.lock().await;
            let runtime = guard.as_ref().unwrap();
            let lane = runtime.snapshot.byzantine_consensus_lane.as_ref().unwrap();
            assert_eq!(lane.slot.roast_view(), 1);
            assert!(lane.reducer.commit().is_some());
            assert_eq!(live_byzantine_roast(runtime).unwrap().unwrap().next_view(), 1);
        }

        let mut successor_release = service
            .progress_byzantine_consolidations(&identity, deadline, 1_000, Arc::clone(&transition))
            .await
            .unwrap();
        match successor_release.pop().unwrap() {
            ByzantineConsolidationAction::Release {
                family: released_family,
                view: 1,
                release,
                ..
            } => {
                assert_eq!(released_family, family);
                assert_eq!(release.authorization.sweep_id(), sweep);
                assert_eq!(release.prepared.prepared_intent().encode().unwrap(), prepared_bytes);
            }
            action => panic!("unexpected successor release action: {action:?}"),
        }
        assert!(successor_release.is_empty());

        let durable = {
            let guard = service.runtime.lock().await;
            let runtime = guard.as_ref().unwrap();
            assert!(runtime.snapshot.byzantine_consensus_lane.is_none());
            let roast = live_byzantine_roast(runtime).unwrap().unwrap();
            assert_eq!(roast.family_digest(), family);
            assert_eq!(roast.next_view(), 2);
            assert_eq!(
                runtime.snapshot.worker().unwrap().next_sweep_sequence(),
                next_sweep_sequence
            );
            assert_eq!(
                runtime
                    .snapshot
                    .worker()
                    .unwrap()
                    .scan_state()
                    .sweep(sweep)
                    .unwrap()
                    .signing_intent
                    .prepared_sweep_intent_bytes(),
                prepared_bytes
            );
            runtime.snapshot.clone()
        };
        assert_eq!(service.repository.load(wallet).await.unwrap(), durable);
    }

    #[test]
    fn committed_successor_starts_for_realistic_byzantine_committee_after_outer_deadline() {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .unwrap();
        runtime.block_on(async {
            tokio::spawn(
                committed_successor_starts_for_realistic_byzantine_committee_after_outer_deadline_body(),
            )
            .await
            .unwrap();
        });
    }

    async fn committed_successor_starts_for_realistic_byzantine_committee_after_outer_deadline_body()
     {
        const NOW_MS: u64 = 1_700_000_000_000;
        const LOCAL_PARTY: PartyId = PartyId(5);

        #[derive(Serialize)]
        struct BoundPreprocessFixture {
            context: [u8; 32],
            sender: PartyId,
            message: Vec<u8>,
        }

        fn signed_preprocess_for_view(
            identity: &Identity,
            committee: &Committee,
            network: [u8; 32],
            binding: ConsolidationAttemptWireBinding,
            view: u64,
            input_count: u32,
        ) -> SignedPreprocessContribution {
            let input_count = usize::try_from(input_count).unwrap();
            let discriminator = view
                .checked_mul(16)
                .and_then(|offset| offset.checked_add(u64::from(identity.party().0)))
                .unwrap();
            let mut message = Vec::with_capacity(
                input_count * crate::signing::FROSTLASS_PREPROCESS_BYTES_PER_INPUT,
            );
            for input in 0..input_count {
                for field in 0..7 {
                    let scalar = Scalar::from(
                        discriminator
                            .saturating_add(u64::try_from(input).unwrap())
                            .saturating_add(u64::try_from(field).unwrap())
                            .saturating_add(1),
                    );
                    message.extend_from_slice(
                        &(ED25519_BASEPOINT_POINT * scalar).compress().to_bytes(),
                    );
                }
                message.extend_from_slice(
                    &Scalar::from(
                        discriminator
                            .saturating_add(u64::try_from(input).unwrap())
                            .saturating_add(1),
                    )
                    .to_bytes(),
                );
            }
            let encoded = postcard::to_allocvec(&BoundPreprocessFixture {
                context: binding.attempt().signing_context(),
                sender: identity.party(),
                message,
            })
            .unwrap();
            let preprocess: crate::signing::BoundPreprocessMessage =
                postcard::from_bytes(&encoded).unwrap();
            SignedPreprocessContribution::sign(identity, committee, network, binding, preprocess)
                .unwrap()
        }

        let state = tempfile::tempdir().unwrap();
        let identity_seed = [0xe8; 32];
        let (scenario, epoch_public, identities) = committed_tail_recovery_fixture();
        let identity = &identities[&LOCAL_PARTY];
        let source = Arc::new(PreparedSweepChain::new());
        let backend = Arc::new(BlockingValidationBackend::new());
        let service = DepositService::new_with_consolidation_backend(
            LOCAL_PARTY,
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source.clone(),
            backend.clone(),
        )
        .unwrap();
        let genesis = service.prepare_genesis(&epoch_public, [0xe9; 32]).await.unwrap();
        service.install_prepared_genesis(genesis, None, None).await.unwrap();
        source.set_tip(19);

        let prepared = {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            let mut worker = runtime.snapshot.worker().cloned().unwrap();
            let output_index = PreparedSweepOutputIndex {
                wallet: runtime.deriver.wallet_id(),
                portable_snapshot: worker.portable_index_head().unwrap(),
                subaddress: DepositSubaddressIndex::new(0, 1).unwrap(),
            };
            for _ in 0..16 {
                if worker.scan_state().tip().height >= 10 {
                    break;
                }
                let tick =
                    worker.tick(source.as_ref(), &runtime.deriver, &output_index).await.unwrap();
                assert!(tick.persistence.is_some());
                if let Some(events) = worker.replay_pending_events().unwrap() {
                    worker.acknowledge_events(events.id).unwrap();
                }
            }
            assert_eq!(worker.scan_state().tip().height, 19);
            let destination =
                root_consolidation_destination_binding(&runtime.deriver, worker.config());
            let plan = worker.plan_sweep(0, destination).unwrap().unwrap();
            let (input, amount) = compaction_transaction_input(&compaction_threshold_keys());
            assert_eq!(plan.total_input_atomic_units, amount);
            assert_eq!(plan.inputs, vec![prepared_sweep_wallet_output().id()]);
            let prepared = worker
                .prepare_sweep_from_components(
                    &runtime.deriver,
                    &plan,
                    [0xea; 32],
                    vec![input],
                    FeeRate::new(1, 1).unwrap(),
                )
                .unwrap();
            let mut candidate = runtime.snapshot.clone();
            candidate.replace_worker(worker).unwrap();
            runtime.snapshot = service.repository.persist_and_read_back(&candidate).await.unwrap();
            prepared
        };
        backend.install_prepared(prepared);
        let transition = Arc::new(Mutex::new(()));

        let mut bootstrap = service
            .progress_byzantine_consolidations(identity, NOW_MS, 1_000, Arc::clone(&transition))
            .await
            .unwrap();
        let continuation = match bootstrap.pop().unwrap() {
            ByzantineConsolidationAction::BootstrapPrepared {
                outer_view: 0, continuation, ..
            } => continuation,
            action => panic!("unexpected view-zero bootstrap action: {action:?}"),
        };
        assert!(bootstrap.is_empty());
        service
            .continue_byzantine_bootstrap(identity, continuation, NOW_MS, Arc::clone(&transition))
            .await
            .unwrap();

        // Model a remote proposal winning the n-f certificate. Every live party prepares private
        // outgoing-view randomness independently, so the certified transaction need not be the
        // local bootstrap candidate. Pick a valid alternate whose deterministic view-zero signer
        // set excludes party five, matching the first r004 deadline reporter.
        {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            let mut lane = runtime.snapshot.byzantine_consensus_lane.clone().unwrap();
            let context = lane.reducer.context().clone();
            assert_eq!(context.quorum(), 4);
            let worker = runtime.snapshot.worker().unwrap();
            let plan = worker
                .plan_sweep(
                    lane.slot.committee().epoch,
                    root_consolidation_destination_binding(&runtime.deriver, worker.config()),
                )
                .unwrap()
                .unwrap();
            let (remote_prepared, remote_plan) = (0xeb_u8..=0xff)
                .find_map(|seed| {
                    let (input, _) = compaction_transaction_input(&compaction_threshold_keys());
                    let prepared = worker
                        .prepare_sweep_from_components(
                            &runtime.deriver,
                            &plan,
                            [seed; 32],
                            vec![input],
                            FeeRate::new(1, 1).unwrap(),
                        )
                        .unwrap();
                    let authorization =
                        build_consolidation_authorization(worker, &prepared).unwrap();
                    let roast_plan = RoastViewPlan::derive(
                        &lane.slot,
                        lane.slot.committee(),
                        lane.slot.fault_bound(),
                        &authorization,
                    )
                    .unwrap();
                    roast_plan
                        .signers()
                        .binary_search(&LOCAL_PARTY)
                        .is_err()
                        .then_some((prepared, roast_plan))
                })
                .expect("at least one deterministic alternate excludes party five");
            let signers = CanonicalSignerSet::new(
                lane.slot.committee(),
                remote_plan.relay_seed(),
                remote_plan.signers().iter().copied(),
            )
            .unwrap();
            let (authorization, attempt) = build_consolidation_bindings(
                worker,
                &remote_prepared,
                lane.slot.committee(),
                &signers,
                lane.slot.binding().registry,
                lane.slot.binding().activation,
                remote_plan.signing_session(),
                remote_plan.attempt(),
            )
            .unwrap();
            let intent =
                ConsolidationIntent::new(&context, authorization, attempt.clone()).unwrap();
            let value = intent.to_consensus_value().unwrap();
            let binding = ConsolidationAttemptWireBinding::new(
                intent.authorization(),
                &attempt,
                remote_plan.relay_seed(),
            )
            .unwrap();
            let prepared_intent = remote_prepared.prepared_intent().encode().unwrap();
            ByzantineConsensusValueAttachment::new(
                &context,
                &lane.slot,
                &value,
                binding.clone(),
                prepared_intent.clone(),
            )
            .unwrap();
            lane.install_revalidated_admission(ValidatedByzantineConsensusValue {
                value: value.clone(),
                binding,
                prepared_intent,
                prepared_intent_digest: remote_prepared.prepared_intent().digest().unwrap(),
                slot_digest: lane.slot.digest(),
                validated_worker_revision: worker.revision(),
            })
            .unwrap();
            assert_ne!(value.digest(), lane.local_candidate);
            let witnesses = identities
                .values()
                .take(context.quorum())
                .map(|identity| {
                    sign_consensus_message(
                        &context,
                        identity,
                        ConsensusMessageBody::Precommit(Vote { view: 0, value: value.digest() }),
                    )
                    .unwrap()
                })
                .collect();
            let certificate =
                CommitCertificate::from_witnesses(&context, 0, value.clone(), witnesses).unwrap();
            let step = lane
                .reducer
                .handle_commit_certificate_with_validator(certificate, |candidate| {
                    candidate == &value
                })
                .unwrap();
            let messages = byzantine_consensus_step_messages(LOCAL_PARTY, &lane, &step).unwrap();
            let mut snapshot = runtime.snapshot.clone();
            snapshot.replace_byzantine_lane_and_enqueue(Some(lane), messages).unwrap();
            runtime.snapshot = service.repository.persist_and_read_back(&snapshot).await.unwrap();
        }

        let release = service
            .progress_byzantine_consolidations(identity, NOW_MS, 1_000, Arc::clone(&transition))
            .await
            .unwrap();
        assert!(release.is_empty(), "party five is outside the view-zero n-f signer set");
        let (family, sweep, deadline) = {
            let guard = service.runtime.lock().await;
            let roast = live_byzantine_roast(guard.as_ref().unwrap()).unwrap().unwrap();
            (roast.family_digest(), roast.sweep_id(), roast.outer_deadline_unix_ms())
        };

        // Retain the realistic non-signer state which existed on p5 at the deadline: valid peer
        // preprocesses for the certified view and their durable relay outbox entries. Older-view
        // contributions must remain compatible with installing the next BA lane.
        let (binding, signers, input_count, committee, network) = {
            let guard = service.runtime.lock().await;
            let roast = live_byzantine_roast(guard.as_ref().unwrap()).unwrap().unwrap();
            let plan = roast.plan(0).unwrap();
            (
                roast.wire_binding(0).unwrap(),
                plan.signers().to_vec(),
                roast.authorization().input_count(),
                roast.committee().clone(),
                roast.quic_network_id(),
            )
        };
        assert!(signers.binary_search(&LOCAL_PARTY).is_err());
        for sender in signers {
            let contribution = signed_preprocess_for_view(
                &identities[&sender],
                &committee,
                network,
                binding.clone(),
                0,
                input_count,
            );
            service.record_byzantine_preprocess(family, 0, contribution).await.unwrap();
        }

        let actions = service
            .progress_byzantine_consolidations(identity, deadline, 1_000, Arc::clone(&transition))
            .await
            .expect("the expired live ROAST must durably start its deterministic successor lane");
        assert!(actions.is_empty());
        let guard = service.runtime.lock().await;
        let runtime = guard.as_ref().unwrap();
        let lane = runtime.snapshot.byzantine_consensus_lane.as_ref().unwrap();
        assert_eq!(lane.slot.roast_view(), 1);
        assert!(lane.reducer.started());
        assert!(lane.reducer.commit().is_none());
        let roast = live_byzantine_roast(runtime).unwrap().unwrap();
        assert_eq!(roast.family_digest(), family);
        assert_eq!(roast.sweep_id(), sweep);
        assert_eq!(roast.next_view(), 1);

        // The r004 warning occurred one outer timeout later: view one had already been proposed
        // and certified while p2 was catching up. Commit and finalize that first successor, retain
        // its signing-round evidence, then exercise the view-one -> view-two deadline transition.
        drop(guard);
        {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            let mut lane = runtime.snapshot.byzantine_consensus_lane.clone().unwrap();
            assert_eq!(lane.slot.roast_view(), 1);
            let context = lane.reducer.context().clone();
            let value = lane.admitted_values[&lane.local_candidate].value.clone();
            let witnesses = identities
                .values()
                .take(context.quorum())
                .map(|identity| {
                    sign_consensus_message(
                        &context,
                        identity,
                        ConsensusMessageBody::Precommit(Vote { view: 0, value: value.digest() }),
                    )
                    .unwrap()
                })
                .collect();
            let certificate =
                CommitCertificate::from_witnesses(&context, 0, value.clone(), witnesses).unwrap();
            let step = lane
                .reducer
                .handle_commit_certificate_with_validator(certificate, |candidate| {
                    candidate == &value
                })
                .unwrap();
            let messages = byzantine_consensus_step_messages(LOCAL_PARTY, &lane, &step).unwrap();
            let mut snapshot = runtime.snapshot.clone();
            snapshot.replace_byzantine_lane_and_enqueue(Some(lane), messages).unwrap();
            runtime.snapshot = service.repository.persist_and_read_back(&snapshot).await.unwrap();
        }
        let view_one_release = service
            .progress_byzantine_consolidations(
                identity,
                deadline.checked_add(1).unwrap(),
                1_000,
                Arc::clone(&transition),
            )
            .await
            .expect("the committed first successor must become a durable ROAST attempt");
        assert!(view_one_release.len() <= 1);

        let (view_one_binding, view_one_signers, input_count, committee, network, next_deadline) = {
            let guard = service.runtime.lock().await;
            let roast = live_byzantine_roast(guard.as_ref().unwrap()).unwrap().unwrap();
            let plan = roast.plan(1).unwrap();
            assert_eq!(roast.next_view(), 2);
            (
                roast.wire_binding(1).unwrap(),
                plan.signers().to_vec(),
                roast.authorization().input_count(),
                roast.committee().clone(),
                roast.quic_network_id(),
                roast.outer_deadline_unix_ms(),
            )
        };
        for sender in view_one_signers {
            let contribution = signed_preprocess_for_view(
                &identities[&sender],
                &committee,
                network,
                view_one_binding.clone(),
                1,
                input_count,
            );
            service.record_byzantine_preprocess(family, 1, contribution).await.unwrap();
        }

        let actions = service
            .progress_byzantine_consolidations(
                identity,
                next_deadline,
                1_000,
                Arc::clone(&transition),
            )
            .await
            .expect("an expired certified view one must durably start view two");
        assert!(actions.is_empty());
        let guard = service.runtime.lock().await;
        let runtime = guard.as_ref().unwrap();
        let lane = runtime.snapshot.byzantine_consensus_lane.as_ref().unwrap();
        assert_eq!(lane.slot.roast_view(), 2);
        assert!(lane.reducer.started());
        assert!(lane.reducer.commit().is_none());
        let roast = live_byzantine_roast(runtime).unwrap().unwrap();
        assert_eq!(roast.family_digest(), family);
        assert_eq!(roast.sweep_id(), sweep);
        assert_eq!(roast.next_view(), 2);
    }

    fn compaction_identity() -> Identity {
        Identity::from_test_secrets(PartyId(1), 0, &[0xb0; 32], [0xb1; 32]).unwrap()
    }

    fn compaction_committee(identity: &Identity) -> Committee {
        Committee {
            epoch: 0,
            threshold: 1,
            members: vec![Member {
                id: identity.party(),
                signing_key: identity.signing_public_key(),
                encryption_key: identity.encryption_public_key(),
            }],
        }
        .canonicalized()
        .unwrap()
    }

    fn compaction_epoch_public(identity: &Identity) -> EpochPublic {
        let group = PointBytes::from(ED25519_BASEPOINT_POINT * Scalar::from(42_u64));
        EpochPublic {
            key_id: [0xb2; 32],
            committee: compaction_committee(identity),
            verification_shares: BTreeMap::from([(PartyId(1), group)]),
            group_key: group,
        }
    }

