    #[test]
    fn finalized_checkpoint_replays_are_semantic_fail_closed_and_restart_safe() {
        let test_runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .unwrap();
        test_runtime.block_on(async {
            tokio::spawn(finalized_checkpoint_replays_body()).await.unwrap();
        });
    }

    async fn finalized_checkpoint_replays_body() {
        let CompactionServiceFixture {
            _state: state,
            service,
            source,
            scenario,
            epoch_public,
            identity_seed,
            ..
        } = compaction_service_fixture(false).await;
        let identity = compaction_identity();
        let network = scenario.quic_network_id().unwrap();
        let (context, purpose, installed, installed_checkpoint, installed_operation, registry) = {
            let guard = service.runtime.lock().await;
            let runtime = guard.as_ref().unwrap();
            let checkpoint = runtime.snapshot.index_checkpoint_certificate().unwrap().clone();
            let context = deposit_index_checkpoint_consensus_context(
                network,
                &runtime.protocol.registry,
                checkpoint.statement().sequence(),
                checkpoint.statement().previous_head(),
            )
            .unwrap();
            checkpoint.selection().verify(&context).unwrap();
            (
                context,
                DepositConsensusPurpose::NextIndexCheckpoint {
                    sequence: checkpoint.statement().sequence(),
                },
                checkpoint.selection().clone(),
                checkpoint,
                runtime.snapshot.checkpoint_operation_certificate().unwrap(),
                runtime.protocol.registry.clone(),
            )
        };

        // A later valid view for the same decision is an interchangeable proof. Its witness bytes
        // and view differ, while the durable decision digest remains identical.
        let alternate_witness = sign_consensus_message(
            &context,
            &identity,
            ConsensusMessageBody::Precommit(Vote {
                view: installed.view().checked_add(1).unwrap(),
                value: installed.value().digest(),
            }),
        )
        .unwrap();
        let alternate = CommitCertificate::from_witnesses(
            &context,
            installed.view().checked_add(1).unwrap(),
            installed.value().clone(),
            vec![alternate_witness],
        )
        .unwrap();
        assert_ne!(alternate, installed);
        assert_eq!(alternate.digest(), installed.digest());
        let replay =
            DepositConsensusWire::commit_certificate(context.clone(), purpose, alternate.clone());

        let DepositIndexCheckpointCandidate::Ledger(entry) =
            installed_checkpoint.selected_candidate().unwrap()
        else {
            panic!("compaction fixture installed a non-ledger checkpoint");
        };
        let alternate_checkpoint = DepositIndexCheckpointCertificate::from_witnesses(
            network,
            &registry,
            None,
            None,
            &entry,
            installed_checkpoint.statement().clone(),
            alternate,
            installed_checkpoint.witnesses().to_vec(),
        )
        .unwrap();
        assert_ne!(alternate_checkpoint, installed_checkpoint);
        assert!(alternate_checkpoint.has_same_witness_independent_decision(&installed_checkpoint));
        let checkpoint_binding = DepositIndexCheckpointLedgerBinding::new(
            DepositSyncContext::new(network, registry.wallet()).unwrap(),
            alternate_checkpoint.statement().sequence(),
            installed_operation,
            &entry,
        )
        .unwrap();
        let checkpoint_replay =
            DepositIndexCheckpointCertificateWire::new(checkpoint_binding, alternate_checkpoint)
                .unwrap();

        let before = {
            let guard = service.runtime.lock().await;
            deposit_runtime_fingerprint(guard.as_ref().unwrap())
        };
        service
            .handle_consensus(
                PartyId(1),
                DepositOperation::ConsensusCertificate,
                replay.clone(),
                COMPACTION_SIGNING_NOW * 1_000,
                &identity,
            )
            .await
            .unwrap();
        let after = {
            let guard = service.runtime.lock().await;
            deposit_runtime_fingerprint(guard.as_ref().unwrap())
        };
        assert_eq!(after, before, "dominated replay performed a state transition");
        service
            .handle_index_checkpoint_certificate(
                PartyId(1),
                checkpoint_replay.clone(),
                COMPACTION_SIGNING_NOW,
            )
            .await
            .unwrap();
        let after_checkpoint_replay = {
            let guard = service.runtime.lock().await;
            deposit_runtime_fingerprint(guard.as_ref().unwrap())
        };
        assert_eq!(
            after_checkpoint_replay, before,
            "alternate checkpoint witness representation rewrote the settled archive",
        );

        // A valid certificate for another value in the same applied context is never a replay.
        // The advanced state rejects it without mutating the durable snapshot or reducer.
        let conflicting_value = ConsensusValue::new(vec![0xc7; 32]).unwrap();
        let conflicting_witness = sign_consensus_message(
            &context,
            &identity,
            ConsensusMessageBody::Precommit(Vote {
                view: installed.view().checked_add(2).unwrap(),
                value: conflicting_value.digest(),
            }),
        )
        .unwrap();
        let conflicting = CommitCertificate::from_witnesses(
            &context,
            installed.view().checked_add(2).unwrap(),
            conflicting_value,
            vec![conflicting_witness],
        )
        .unwrap();
        let conflicting_wire =
            DepositConsensusWire::commit_certificate(context, purpose, conflicting);
        assert!(matches!(
            service
                .handle_consensus(
                    PartyId(1),
                    DepositOperation::ConsensusCertificate,
                    conflicting_wire,
                    COMPACTION_SIGNING_NOW * 1_000,
                    &identity,
                )
                .await,
            Err(DepositServiceError::ConsensusUnavailable)
        ));
        let after_conflict = {
            let guard = service.runtime.lock().await;
            deposit_runtime_fingerprint(guard.as_ref().unwrap())
        };
        assert_eq!(after_conflict, before);

        drop(service);
        let mut worker_config = DepositWorkerConfig::default();
        worker_config.confirmation_depth = 1;
        worker_config.max_reorg_depth = 60;
        let restarted = DepositService::new(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            worker_config,
            source,
        )
        .unwrap();
        let prepared = restarted.prepare_genesis(&epoch_public, [0xb6; 32]).await.unwrap();
        restarted.install_prepared_genesis(prepared, None, None).await.unwrap();
        let restart_before = {
            let guard = restarted.runtime.lock().await;
            deposit_runtime_fingerprint(guard.as_ref().unwrap())
        };
        restarted
            .handle_consensus(
                PartyId(1),
                DepositOperation::ConsensusCertificate,
                replay,
                COMPACTION_SIGNING_NOW * 1_000,
                &identity,
            )
            .await
            .unwrap();
        restarted
            .handle_index_checkpoint_certificate(
                PartyId(1),
                checkpoint_replay,
                COMPACTION_SIGNING_NOW,
            )
            .await
            .unwrap();
        let restart_after = {
            let guard = restarted.runtime.lock().await;
            deposit_runtime_fingerprint(guard.as_ref().unwrap())
        };
        assert_eq!(restart_after, restart_before);
    }

    #[test]
    fn terminal_family_compaction_budget_is_shared_and_resumable_under_saturation() {
        let mut remaining = MAX_TERMINAL_FAMILY_COMPACTIONS_PER_TICK;
        let completions = take_terminal_family_compaction_batch(0..20, &mut remaining);
        let abandonments = take_terminal_family_compaction_batch(0..4_096, &mut remaining);
        let later_completions = take_terminal_family_compaction_batch(0..4_096, &mut remaining);
        assert_eq!(completions.len(), 20);
        assert_eq!(
            abandonments.len(),
            MAX_TERMINAL_FAMILY_COMPACTIONS_PER_TICK - completions.len()
        );
        assert!(later_completions.is_empty());
        assert_eq!(
            completions.len() + abandonments.len(),
            MAX_TERMINAL_FAMILY_COMPACTIONS_PER_TICK
        );
        assert_eq!(remaining, 0);

        let mut next_tick_remaining = MAX_TERMINAL_FAMILY_COMPACTIONS_PER_TICK;
        let resumed = take_terminal_family_compaction_batch(0..4_096, &mut next_tick_remaining);
        assert_eq!(resumed.len(), MAX_TERMINAL_FAMILY_COMPACTIONS_PER_TICK);
        assert_eq!(next_tick_remaining, 0);
    }

    #[test]
    fn idle_worker_tick_compacts_mature_publication_and_portable_status_survives_restart() {
        // This fixture constructs and revalidates a real Monero transaction while advancing the
        // scanner through its retained window. Run it on the same worker-stack size as the party
        // binary so the regression measures compaction behavior instead of libtest's small stack.
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .unwrap();
        runtime.block_on(async {
            tokio::spawn(
                idle_worker_tick_compacts_mature_publication_and_portable_status_survives_restart_body(),
            )
            .await
            .unwrap();
        });
    }

    async fn idle_worker_tick_compacts_mature_publication_and_portable_status_survives_restart_body()
     {
        let CompactionServiceFixture {
            _state: state,
            service,
            source,
            scenario,
            epoch_public,
            identity_seed,
            sweep,
            input,
            portable,
        } = compaction_service_fixture(true).await;
        let exact_current_certificate = portable.current_certificate.clone();
        assert!(
            !exact_current_certificate.attestations.is_empty(),
            "portable status omitted its authenticated ledger witnesses"
        );
        assert_eq!(portable.abandonment_certificate, None);

        service.tick_worker().await.unwrap();
        {
            let guard = service.runtime.lock().await;
            let worker = guard.as_ref().unwrap().snapshot.worker().unwrap();
            assert_eq!(worker.scan_state().tip(), compaction_chain_point(COMPACTION_CHAIN_TIP));
            assert!(
                worker.certified_sweep_publication(sweep).is_none(),
                "the no-op chain tick must still erase a mature confirmed publication"
            );
        }
        assert!(service.certified_sweeps_awaiting_publish().await.unwrap().is_empty());
        let compacted = service.public_consolidation_status(sweep).await.unwrap().unwrap();
        assert_eq!(compacted.portable, Some(portable.clone()));
        assert_eq!(
            compacted.portable.as_ref().unwrap().current_certificate,
            exact_current_certificate
        );
        assert_eq!(compacted.live, None);
        let by_output =
            service.public_consolidation_status_for_output(input).await.unwrap().unwrap();
        assert_eq!(by_output, compacted);

        drop(service);
        let restarted = DepositService::new(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            {
                let mut config = DepositWorkerConfig::default();
                config.confirmation_depth = 1;
                config.max_reorg_depth = 60;
                config
            },
            source,
        )
        .unwrap();
        let prepared = restarted.prepare_genesis(&epoch_public, [0xb6; 32]).await.unwrap();
        restarted.install_prepared_genesis(prepared, None, None).await.unwrap();
        let restored = restarted.public_consolidation_status(sweep).await.unwrap().unwrap();
        assert_eq!(
            restored.portable.as_ref().unwrap().current_certificate,
            exact_current_certificate
        );
        assert_eq!(restored.portable, Some(portable));
        assert_eq!(restored.live, None);
        assert_eq!(
            restarted.public_consolidation_status_for_output(input).await.unwrap(),
            Some(restored)
        );
    }

    #[test]
    fn adopted_public_terminal_without_local_sweep_never_enters_publish_driver() {
        // This fixture constructs and revalidates a real Monero transaction while driving the
        // deposit scanner through its full retained window. Those reducers intentionally run on
        // the party binary's 16 MiB Tokio worker stack; a bare `#[tokio::test]` uses the libtest
        // thread's much smaller stack and can abort before reporting an assertion. Spawn the body
        // on a production-sized worker so this remains a protocol regression rather than a test
        // harness stack-limit test.
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .unwrap();
        runtime.block_on(async {
            tokio::spawn(adopted_public_terminal_without_local_sweep_body()).await.unwrap();
        });
    }

    async fn adopted_public_terminal_without_local_sweep_body() {
        let fixture = compaction_service_fixture(false).await;
        {
            let guard = fixture.service.runtime.lock().await;
            let worker = guard.as_ref().unwrap().snapshot.worker().unwrap();
            assert!(
                worker.scan_state().sweep(fixture.sweep).is_none(),
                "a public-only terminal must not synthesize private scanner sweep state"
            );
            assert!(
                worker.certified_sweep_publication(fixture.sweep).is_some(),
                "the portable publication tombstone must remain available for chain recognition"
            );
        }
        assert!(fixture.service.certified_sweeps_awaiting_publish().await.unwrap().is_empty());

        fixture.service.tick_worker().await.unwrap();
        let guard = fixture.service.runtime.lock().await;
        let worker = guard.as_ref().unwrap().snapshot.worker().unwrap();
        let publication = worker.certified_sweep_publication(fixture.sweep).unwrap();
        assert_eq!(publication.confirmation(), None);
        assert!(worker.compactable_certified_sweep_publications().next().is_none());
        drop(guard);
        // This is the publication portion of the periodic consolidation driver. A lagging party
        // which adopted only certified public evidence must contribute no item that would make
        // `publish_certified_consolidation` fail for lack of locally revalidated inputs.
        for sweep in fixture.service.certified_sweeps_awaiting_publish().await.unwrap() {
            fixture.service.publish_certified_consolidation(sweep).await.unwrap();
        }
        let status =
            fixture.service.public_consolidation_status(fixture.sweep).await.unwrap().unwrap();
        assert_eq!(status.portable, Some(fixture.portable));
    }

    fn served_cache_object(tag: u8, length: usize) -> (DepositSyncObjectRef, Vec<u8>) {
        let bytes = vec![tag; length];
        let reference = WalletArtifactRef::for_contents(
            WalletId([0xc1; 32]),
            CERTIFIED_LEDGER_ENTRY_ARTIFACT,
            &bytes,
        )
        .unwrap();
        (DepositSyncObjectRef::CertificateArchive(reference), bytes)
    }

