    fn deposit_sync_verification_base(
        advertisement: &DepositSyncAdvertisement,
        snapshot_revision: u64,
    ) -> DepositSyncVerificationBase {
        DepositSyncVerificationBase::new(
            snapshot_revision,
            DepositArchiveHead::empty(advertisement.context().wallet()).unwrap(),
            advertisement.portable_index(),
            advertisement.portable_index().through_sequence() + 1,
        )
    }

    #[test]
    fn deposit_sync_verification_cursor_is_fixed_size_at_max_artifact_lengths() {
        let wallet = WalletId([0xc7; 32]);
        let event = WalletArtifactRef::for_contents(
            wallet,
            crate::deposit_archive::DEPOSIT_ARCHIVE_EVENT_ARTIFACT,
            &[0x41; crate::deposit_archive::MAX_DEPOSIT_ARCHIVE_EVENT_BYTES],
        )
        .unwrap();
        let segment = WalletArtifactRef::for_contents(
            wallet,
            crate::deposit_archive::DEPOSIT_ARCHIVE_SEGMENT_ARTIFACT,
            &[0x42; crate::deposit_archive::MAX_DEPOSIT_ARCHIVE_SEGMENT_BYTES],
        )
        .unwrap();
        // The referenced operation can contain the maximum witness-bearing certificate body, but
        // the restart cursor retains only its fixed content address.
        let operation = WalletArtifactRef::for_contents(
            wallet,
            CERTIFIED_LEDGER_ENTRY_ARTIFACT,
            &vec![0x43; crate::deposit_archive::MAX_CERTIFIED_ENTRY_ARTIFACT_BYTES],
        )
        .unwrap();
        let milestone = DepositSyncVerificationMilestone {
            ordinal: u64::MAX - 1,
            event,
            operation,
            checkpoint_decision: [0x44; 32],
            resulting_head: [0x45; 32],
        };
        let (base_advertisement, _, _) = deposit_sync_cache_fixture(0xc7);
        let cursor = DepositSyncVerificationCursor {
            version: DEPOSIT_SYNC_VERIFICATION_CURSOR_VERSION,
            advertisement: [0x46; 32],
            base: deposit_sync_verification_base(&base_advertisement, u64::MAX),
            complete_registry: None,
            visited: u64::MAX,
            unprocessed_end: 0,
            unprocessed_segment: None,
            newer_event: Some(event),
            tip: Some(milestone),
            local_prefix: Some(milestone),
            first_suffix: Some(milestone),
            imported_next: Some(milestone),
        };
        let bytes = cursor.to_bytes().unwrap();
        assert!(bytes.len() <= MAX_DEPOSIT_SYNC_VERIFICATION_CURSOR_BYTES);

        let boundary_cursor = DepositSyncVerificationCursor {
            visited: 128,
            unprocessed_end: u64::MAX - 128,
            unprocessed_segment: Some(segment),
            ..cursor.clone()
        };
        assert!(
            boundary_cursor.to_bytes().unwrap().len() <= MAX_DEPOSIT_SYNC_VERIFICATION_CURSOR_BYTES
        );
        let summary = DepositSyncVerifiedSummary {
            version: DEPOSIT_SYNC_VERIFIED_SUMMARY_VERSION,
            cursor,
            verification_digest: [0x47; 32],
        };
        assert!(summary.to_bytes().unwrap().len() <= MAX_DEPOSIT_SYNC_VERIFIED_SUMMARY_BYTES);
    }

    #[test]
    fn deposit_sync_verification_cursor_v4_roundtrips_canonically_and_rejects_v3() {
        let (advertisement, _, _) = deposit_sync_cache_fixture(0x27);
        let base = deposit_sync_verification_base(&advertisement, 7);
        let cursor = DepositSyncVerificationCursor::fresh(&advertisement, base.clone());
        let bytes = cursor.to_bytes().unwrap();
        assert_eq!(
            DepositSyncVerificationCursor::from_bytes(&advertisement, base.clone(), &bytes)
                .unwrap(),
            cursor
        );
        let newer_base = DepositSyncVerificationBase {
            snapshot_revision: base.snapshot_revision + 1,
            ..base.clone()
        };
        let stale =
            DepositSyncVerificationCursor::from_bytes(&advertisement, newer_base, &bytes).unwrap();
        assert_eq!(
            stale.base, base,
            "a persisted cursor must retain its authenticated base so adoption can rebase explicitly"
        );

        let legacy = DepositSyncVerificationCursor {
            version: DEPOSIT_SYNC_VERIFICATION_CURSOR_VERSION - 1,
            ..cursor
        };
        let legacy_bytes = postcard::to_allocvec(&legacy).unwrap();
        assert!(
            DepositSyncVerificationCursor::from_bytes(&advertisement, base, &legacy_bytes).is_err()
        );
    }

    #[test]
    fn deposit_sync_verified_summary_roundtrips_and_binds_frozen_object_count() {
        let (advertisement, _, _) = deposit_sync_cache_fixture(0x28);
        let base = deposit_sync_verification_base(&advertisement, 8);
        let cursor = DepositSyncVerificationCursor::fresh(&advertisement, base.clone());
        let summary =
            DepositSyncVerifiedSummary::from_cursor(&advertisement, 73, cursor.clone()).unwrap();
        let bytes = summary.to_bytes().unwrap();
        assert_eq!(
            DepositSyncVerifiedSummary::from_bytes(&advertisement, 73, &bytes).unwrap(),
            summary
        );
        assert!(DepositSyncVerifiedSummary::from_bytes(&advertisement, 74, &bytes).is_err());
        assert!(
            DepositSyncVerifiedSummary::from_bytes(&advertisement, 73, &cursor.to_bytes().unwrap())
                .is_err()
        );

        let rebased = DepositSyncVerifiedSummary::from_cursor(
            &advertisement,
            73,
            DepositSyncVerificationCursor::fresh(
                &advertisement,
                DepositSyncVerificationBase {
                    snapshot_revision: base.snapshot_revision + 1,
                    ..base
                },
            ),
        )
        .unwrap();
        assert_ne!(
            summary.verification_digest, rebased.verification_digest,
            "the verified summary must bind the exact local snapshot revision and base facts"
        );
    }

    #[test]
    fn deposit_sync_issuer_window_cache_is_lifetime_bounded() {
        let mut cache = FixedEpochCache::default();
        for epoch in 0..10_000 {
            cache.insert(epoch, epoch);
            assert!(cache.len() <= MAX_DEPOSIT_SYNC_CACHED_ISSUER_WINDOWS);
        }
        for epoch in (9_996..10_000).rev() {
            assert_eq!(cache.get(epoch), Some(epoch));
        }
        assert_eq!(cache.get(0), None);
        assert_eq!(cache.len(), MAX_DEPOSIT_SYNC_CACHED_ISSUER_WINDOWS);
    }

    #[test]
    fn deposit_sync_verification_cursor_roundtrips_every_segment_boundary() {
        const SEGMENTS: u64 = 4;
        let width =
            u64::try_from(crate::deposit_archive::MAX_DEPOSIT_ARCHIVE_SEGMENT_EVENTS).unwrap();
        let archive_len = SEGMENTS * width;
        let wallet = WalletId([0xd7; 32]);
        let event = WalletArtifactRef::for_contents(
            wallet,
            crate::deposit_archive::DEPOSIT_ARCHIVE_EVENT_ARTIFACT,
            &[0x51],
        )
        .unwrap();
        let segment = WalletArtifactRef::for_contents(
            wallet,
            crate::deposit_archive::DEPOSIT_ARCHIVE_SEGMENT_ARTIFACT,
            &[0x52],
        )
        .unwrap();
        let operation =
            WalletArtifactRef::for_contents(wallet, CERTIFIED_LEDGER_ENTRY_ARTIFACT, &[0x53])
                .unwrap();
        let archive = DepositArchiveHead::from_test_parts(
            DepositWalletId(wallet.0),
            archive_len,
            Some(event),
            Some(segment),
        )
        .unwrap();
        let index = DepositIndexStoreCheckpoint::empty(
            DepositWalletId(wallet.0),
            PartyId(1),
            DepositSubaddressIndex::new(0, 1).unwrap(),
        )
        .unwrap();
        let portable_index = PortableDepositIndexHead::from_head(index.portable_head()).unwrap();
        let base = DepositSyncVerificationBase::new(
            9,
            DepositArchiveHead::empty(DepositWalletId(wallet.0)).unwrap(),
            &portable_index,
            1,
        );
        let advertisement = [0x54; 32];
        let tip = DepositSyncVerificationMilestone {
            ordinal: archive_len - 1,
            event,
            operation,
            checkpoint_decision: [0x55; 32],
            resulting_head: [0x56; 32],
        };

        for completed_segments in 0..=SEGMENTS {
            let visited = completed_segments * width;
            let unprocessed_end = archive_len - visited;
            let cursor = DepositSyncVerificationCursor {
                version: DEPOSIT_SYNC_VERIFICATION_CURSOR_VERSION,
                advertisement,
                base: base.clone(),
                complete_registry: None,
                visited,
                unprocessed_end,
                unprocessed_segment: (unprocessed_end != 0).then_some(segment),
                newer_event: (visited != 0).then_some(event),
                tip: (visited != 0).then_some(tip),
                local_prefix: None,
                first_suffix: None,
                imported_next: None,
            };
            cursor.validate_archive(advertisement, archive).unwrap();
            let bytes = cursor.to_bytes().unwrap();
            let decoded: DepositSyncVerificationCursor = postcard::from_bytes(&bytes).unwrap();
            assert_eq!(decoded, cursor);
            decoded.validate_archive(advertisement, archive).unwrap();
        }
    }

    async fn concurrent_deposit_sync_advertisements(
        service: Arc<DepositService>,
        context: DepositSyncContext,
        callers: usize,
    ) -> Vec<DepositSyncAdvertisement> {
        let start = Arc::new(tokio::sync::Barrier::new(callers));
        let mut tasks = Vec::with_capacity(callers);
        for _ in 0..callers {
            let service = Arc::clone(&service);
            let start = Arc::clone(&start);
            tasks.push(tokio::spawn(async move {
                start.wait().await;
                service.deposit_sync_advertisement(context).await.unwrap()
            }));
        }
        let mut advertisements = Vec::with_capacity(callers);
        for task in tasks {
            advertisements.push(task.await.unwrap());
        }
        advertisements
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn deposit_sync_advertisement_is_single_flight_and_authority_keyed() {
        let state = tempfile::tempdir().unwrap();
        let identity_seed = [0xd0; 32];
        let identity = compaction_identity();
        let scenario = compaction_scenario(&identity);
        let public = compaction_epoch_public(&identity);
        let source = Arc::new(CompactionChain::default());
        let service = DepositService::new(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source,
        )
        .unwrap();
        let prepared = service.prepare_genesis(&public, [0xb6; 32]).await.unwrap();
        service.install_prepared_genesis(prepared, None, None).await.unwrap();
        let context = service.deposit_sync_context().await.unwrap();

        let first = concurrent_deposit_sync_advertisements(Arc::clone(&service), context, 24).await;
        assert!(first.iter().all(|advertisement| advertisement == &first[0]));
        assert_eq!(
            service
                .deposit_sync_advertisement_authentications
                .load(std::sync::atomic::Ordering::Relaxed),
            1,
            "concurrent cache misses must authenticate the revision exactly once",
        );

        {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            runtime.snapshot.revision = runtime.snapshot.revision.checked_add(1).unwrap();
        }
        let second =
            concurrent_deposit_sync_advertisements(Arc::clone(&service), context, 24).await;
        assert!(second.iter().all(|advertisement| advertisement == &second[0]));
        assert_eq!(second[0], first[0]);
        assert_eq!(
            service
                .deposit_sync_advertisement_authentications
                .load(std::sync::atomic::Ordering::Relaxed),
            1,
            "an unrelated snapshot revision must reuse the exact authenticated authority",
        );
        let cached = service.deposit_sync_advertisement_cache.completed.read().await;
        assert_eq!(cached.as_ref().unwrap().key.advertisement, first[0]);
        assert_eq!(
            cached.as_ref().unwrap().observed_revision,
            service.runtime.lock().await.as_ref().unwrap().snapshot.revision
        );
    }

    #[test]
    fn served_artifact_cache_enforces_byte_and_entry_budgets_with_fifo_eviction() {
        let mut cache = ServedArtifactCache::new(10, 3);
        let (first, first_bytes) = served_cache_object(1, 4);
        let (second, second_bytes) = served_cache_object(2, 4);
        let (third, third_bytes) = served_cache_object(3, 4);
        let (fourth, fourth_bytes) = served_cache_object(4, 2);
        let (fifth, fifth_bytes) = served_cache_object(5, 1);
        let (oversized, oversized_bytes) = served_cache_object(6, 11);

        cache.insert(first, first_bytes);
        cache.insert(second, second_bytes);
        assert_eq!(cache.plaintext_bytes, 8);
        cache.insert(third, third_bytes);
        assert_eq!(cache.plaintext_bytes, 8);
        assert!(!cache.objects.contains_key(&first));
        assert!(cache.objects.contains_key(&second));
        assert!(cache.objects.contains_key(&third));

        cache.insert(fourth, fourth_bytes);
        assert_eq!(cache.plaintext_bytes, 10);
        assert_eq!(cache.objects.len(), 3);
        cache.insert(fifth, fifth_bytes);
        assert_eq!(cache.plaintext_bytes, 7);
        assert_eq!(
            cache.insertion_order,
            VecDeque::from([third, fourth, fifth]),
            "the oldest surviving reference is evicted deterministically",
        );
        assert!(!cache.objects.contains_key(&second));

        cache.insert(oversized, oversized_bytes);
        assert_eq!(cache.plaintext_bytes, 7);
        assert_eq!(cache.objects.len(), 3);
        assert!(!cache.objects.contains_key(&oversized));

        let production = ServedArtifactCache::production();
        assert_eq!(production.maximum_plaintext_bytes, 32 * 1024 * 1024);
        assert_eq!(production.maximum_objects, SERVED_ARTIFACT_CACHE_MAX_OBJECTS);
    }

    #[test]
    fn only_an_authenticated_capability_page_can_mutate_served_cache() {
        let (advertisement, root, root_bytes) = deposit_sync_cache_fixture(0x75);
        let detached_bytes = b"valid content address, detached from the advertised root".to_vec();
        let detached = DepositSyncObjectRef::Registry(
            CompactRegistryObjectRef::for_contents(
                advertisement.context().wallet(),
                CompactRegistryObjectKind::Link,
                &detached_bytes,
            )
            .unwrap(),
        );
        let mut cache = ServedArtifactCache::new(1024 * 1024, 16);
        assert_eq!(cache.plaintext_bytes, 0);
        assert!(cache.objects.is_empty());
        assert!(cache.insertion_order.is_empty());

        let source = PartyId(1);
        let requester = PartyId(2);
        let mac_key = [0x76; 32];
        let head_request =
            DepositSyncHeadRequest::new(advertisement.context(), source, requester).unwrap();
        let head =
            DepositSyncHeadResponse::issue(head_request, advertisement.clone(), &mac_key).unwrap();
        let lease = head.lease();
        let root_target = lease
            .root_targets()
            .unwrap()
            .into_iter()
            .find(|target| target.reference() == root)
            .unwrap();
        assert!(
            lease.root_targets().unwrap().into_iter().all(|target| target.reference() != detached),
            "detached content addresses must not be admitted as roots",
        );
        let request = DepositSyncObjectPageRequest::new(
            lease,
            vec![DepositSyncObjectRequestEntry::advertised_root(lease, root_target).unwrap()],
        )
        .unwrap();
        let object = DepositSyncObject::new(root, root_bytes.clone()).unwrap();
        let capabilities = object
            .authenticated_semantic_children(root_target)
            .unwrap()
            .into_iter()
            .map(|child| {
                DepositSyncObjectCapability::issue(&mac_key, lease, root_target, child).unwrap()
            })
            .collect();
        let page = DepositSyncObjectPage::build(&request, vec![object], capabilities).unwrap();
        let mut loaded = BTreeMap::from([(root, root_bytes), (detached, detached_bytes)]);
        cache.retain_authenticated_page(&page, &mut loaded);
        assert!(cache.objects.contains_key(&root));
        assert!(
            !cache.objects.contains_key(&detached),
            "objects absent from the authenticated response must remain cold",
        );
        assert!(
            loaded.contains_key(&detached),
            "cache admission must not consume unrelated loader state",
        );
        if let Some(bytes) = cache.objects.get(&root) {
            DepositSyncObject::new(root, bytes.clone()).unwrap();
        }
    }

    fn consensus_fixture() -> (ConsensusContext, BTreeMap<PartyId, Identity>) {
        let (protocol, deriver, identities, _) = protocol_fixture();
        let context =
            deposit_consensus_context(&protocol, deriver.wallet_id(), [0x55; 32]).unwrap();
        (context, identities)
    }

    #[test]
    fn restricted_fence_churn_stays_bounded_and_restart_stable_past_the_old_cap() {
        let (context, identities) = consensus_fixture();
        let local_party =
            identities.keys().copied().find(|party| *party != context.leader(0)).unwrap();
        let local_identity = identities.get(&local_party).unwrap();
        let initial = ConsensusValue::new(vec![0xf0; 16]).unwrap();
        let mut reducer = DepositConsensus::new_recovery_and_fence_only(
            context.clone(),
            local_party,
            [0xf1; 32],
            [],
            [initial.digest()],
        )
        .unwrap();
        reducer.start(local_identity, initial.clone()).unwrap();
        let mut admissions = BTreeMap::from([(initial.digest(), 0_u64)]);

        // More than 128 distinct valid Fence candidates are selectively proposed over successive
        // pre-GST views. Old current-view proposals/votes must leave both the durable admissions
        // and restricted signer allowlist before the next authorization is attempted.
        let final_view = u64::try_from(MAX_ADMITTED_CONSENSUS_VALUES * 2).unwrap();
        let mut proposed = 0_usize;
        for target_view in 1..=final_view {
            let view_witnesses = identities
                .values()
                .take(3)
                .map(|identity| {
                    sign_consensus_message(
                        &context,
                        identity,
                        ConsensusMessageBody::ViewChange(ViewChange {
                            from_view: target_view - 1,
                            target_view,
                            highest_prepared: None,
                        }),
                    )
                    .unwrap()
                })
                .collect();
            let view_certificate =
                ViewChangeCertificate::from_witnesses(&context, target_view, view_witnesses)
                    .unwrap();
            reducer
                .handle_view_certificate_with_validator(
                    local_identity,
                    view_certificate.clone(),
                    |_| true,
                )
                .unwrap();
            prune_unreachable_consensus_admissions(&mut reducer, &mut admissions).unwrap();

            let leader = context.leader(target_view);
            if leader != local_party {
                let mut bytes = vec![0xf2; 16];
                bytes[..8].copy_from_slice(&target_view.to_le_bytes());
                let fence = ConsensusValue::new(bytes).unwrap();
                reducer.authorize_fence_value_digests([fence.digest()]).unwrap();
                let proposal = sign_consensus_message(
                    &context,
                    identities.get(&leader).unwrap(),
                    ConsensusMessageBody::Proposal(Proposal {
                        view: target_view,
                        value: fence.clone(),
                        proof_of_lock: None,
                        view_change: Some(view_certificate),
                    }),
                )
                .unwrap();
                reducer
                    .handle_with_value_validator(local_identity, proposal, |value| value == &fence)
                    .unwrap();
                admissions.insert(fence.digest(), target_view);
                proposed += 1;
                prune_unreachable_consensus_admissions(&mut reducer, &mut admissions).unwrap();
            }

            let authorized = reducer
                .recovery_authorized_value_digests()
                .unwrap()
                .union(reducer.fence_authorized_value_digests().unwrap())
                .copied()
                .collect::<BTreeSet<_>>();
            assert_eq!(
                authorized,
                admissions.keys().copied().collect(),
                "signing authority and durable admissions diverged in view {target_view}",
            );
            assert!(admissions.len() <= 3);
        }
        assert!(proposed > MAX_ADMITTED_CONSENSUS_VALUES);

        let bytes = postcard::to_allocvec(&(reducer.clone(), admissions.clone())).unwrap();
        let (mut restarted_reducer, mut restarted_admissions): (
            DepositConsensus,
            BTreeMap<ConsensusValueDigest, u64>,
        ) = postcard::from_bytes(&bytes).unwrap();
        prune_unreachable_consensus_admissions(&mut restarted_reducer, &mut restarted_admissions)
            .unwrap();
        assert_eq!(restarted_reducer, reducer);
        assert_eq!(restarted_admissions, admissions);
    }

    #[test]
    fn full_only_proposal_churn_stays_bounded_and_restart_stable_past_the_old_cap() {
        let (context, identities) = consensus_fixture();
        let local_party =
            identities.keys().copied().find(|party| *party != context.leader(0)).unwrap();
        let local_identity = identities.get(&local_party).unwrap();
        let initial = ConsensusValue::new(vec![0xe0; 16]).unwrap();
        let mut reducer = DepositConsensus::new(context.clone(), local_party).unwrap();
        reducer.start(local_identity, initial.clone()).unwrap();
        let mut admissions = BTreeMap::from([(initial.digest(), 0_u64)]);

        let final_view = u64::try_from(MAX_ADMITTED_CONSENSUS_VALUES * 2).unwrap();
        let mut proposed = 0_usize;
        for target_view in 1..=final_view {
            let view_witnesses = identities
                .values()
                .take(3)
                .map(|identity| {
                    sign_consensus_message(
                        &context,
                        identity,
                        ConsensusMessageBody::ViewChange(ViewChange {
                            from_view: target_view - 1,
                            target_view,
                            highest_prepared: None,
                        }),
                    )
                    .unwrap()
                })
                .collect();
            let view_certificate =
                ViewChangeCertificate::from_witnesses(&context, target_view, view_witnesses)
                    .unwrap();
            reducer
                .handle_view_certificate_with_validator(
                    local_identity,
                    view_certificate.clone(),
                    |_| true,
                )
                .unwrap();
            prune_unreachable_consensus_admissions(&mut reducer, &mut admissions).unwrap();

            let leader = context.leader(target_view);
            if leader != local_party {
                let mut bytes = vec![0xe1; 16];
                bytes[..8].copy_from_slice(&target_view.to_le_bytes());
                let proposal_value = ConsensusValue::new(bytes).unwrap();
                let proposal = sign_consensus_message(
                    &context,
                    identities.get(&leader).unwrap(),
                    ConsensusMessageBody::Proposal(Proposal {
                        view: target_view,
                        value: proposal_value.clone(),
                        proof_of_lock: None,
                        view_change: Some(view_certificate),
                    }),
                )
                .unwrap();
                reducer
                    .handle_with_value_validator(local_identity, proposal, |value| {
                        value == &proposal_value
                    })
                    .unwrap();
                admissions.insert(proposal_value.digest(), target_view);
                proposed += 1;
                prune_unreachable_consensus_admissions(&mut reducer, &mut admissions).unwrap();
            }

            let mut reachable = BTreeSet::new();
            reducer
                .validate_application_values(|value| {
                    reachable.insert(value.digest());
                    true
                })
                .unwrap();
            assert_eq!(
                reachable,
                admissions.keys().copied().collect(),
                "ordinary reducer and durable admissions diverged in view {target_view}",
            );
            assert!(admissions.len() <= 3);
        }
        assert!(proposed > MAX_ADMITTED_CONSENSUS_VALUES);

        let bytes = postcard::to_allocvec(&(reducer.clone(), admissions.clone())).unwrap();
        let (mut restarted_reducer, mut restarted_admissions): (
            DepositConsensus,
            BTreeMap<ConsensusValueDigest, u64>,
        ) = postcard::from_bytes(&bytes).unwrap();
        prune_unreachable_consensus_admissions(&mut restarted_reducer, &mut restarted_admissions)
            .unwrap();
        assert_eq!(restarted_reducer, reducer);
        assert_eq!(restarted_admissions, admissions);
    }

    #[test]
    fn client_request_quota_is_origin_isolated_and_selection_is_restart_deterministic() {
        let network = [0x55; 32];
        let (mut protocol, deriver, identities, _) = protocol_fixture();
        let quota = pending_client_request_quota(protocol.registry.active().committee()).unwrap();
        let make_request = |nonce: u64| {
            let mut binding = [0x90; 32];
            binding[..8].copy_from_slice(&nonce.to_le_bytes());
            let binding = RequestBinding(binding);
            DepositAddressRequest { request: deposit_request_id_for_binding(binding), binding }
        };
        for nonce in 1..=u64::try_from(quota).unwrap() {
            let request = make_request(nonce);
            let wire = client_request_authority(&protocol, &identities, PartyId(1), request);
            assert!(protocol.retain_client_request(&wire).unwrap());
        }
        let overflow_request = make_request(u64::try_from(quota).unwrap() + 1);
        let overflow =
            client_request_authority(&protocol, &identities, PartyId(1), overflow_request);
        assert!(matches!(
            protocol.retain_client_request(&overflow),
            Err(DepositServiceError::ConsensusRequestPoolFull)
        ));

        // Saturating one authenticated origin is advisory and cannot consume another member's
        // independently bounded request capacity.
        let isolated_request = make_request(u64::try_from(quota).unwrap() + 2);
        let isolated =
            client_request_authority(&protocol, &identities, PartyId(2), isolated_request);
        assert!(protocol.retain_client_request(&isolated).unwrap());
        assert_eq!(protocol.client_requests.len(), quota + 1);

        // Validation precedes the advisory capacity check: malformed or binding-equivocating
        // traffic never acquires the accepted-drop behavior used for a valid full origin.
        let mut malformed = overflow;
        malformed.request.binding.0[0] ^= 1;
        assert!(matches!(
            protocol.retain_client_request(&malformed),
            Err(DepositServiceError::InvalidPeerMessage)
        ));

        let selected = protocol.next_client_request().unwrap().unwrap();
        assert_eq!(selected.1.origin(), PartyId(1));
        assert_eq!(selected.0, selected.1.request);
        let expected = protocol
            .client_requests
            .values()
            .find_map(|pending| {
                pending
                    .authorities
                    .get(&PartyId(1))
                    .map(|authority| (pending.request, authority.clone()))
            })
            .unwrap();
        assert_eq!(selected, expected);

        let encoded = protocol.encode_local(&deriver).unwrap();
        let restarted = DepositLocalState::decode(
            &encoded,
            protocol.registry.clone(),
            protocol.ledger.clone(),
            &deriver,
            protocol.local_party,
            network,
        )
        .unwrap();
        assert_eq!(restarted.next_client_request().unwrap(), Some(selected));
    }

    #[test]
    fn handoff_clears_old_context_client_requests_and_retry_survives_restart() {
        let (mut protocol, deriver, identities, _) = protocol_fixture();
        let binding = RequestBinding([0x91; 32]);
        let request =
            DepositAddressRequest { request: deposit_request_id_for_binding(binding), binding };
        let authority_4 = client_request_authority(&protocol, &identities, PartyId(4), request);
        assert!(protocol.retain_client_request(&authority_4).unwrap());
        assert_eq!(protocol.clear_client_requests_for_handoff(), 1);
        assert!(protocol.client_requests.is_empty());

        let encoded = DepositLocalState::from_protocol(&protocol).encode().unwrap();
        let mut restarted = DepositLocalState::decode(
            &encoded,
            protocol.registry.clone(),
            protocol.ledger.clone(),
            &deriver,
            protocol.local_party,
            [0x55; 32],
        )
        .unwrap();
        assert!(restarted.client_requests.is_empty());
        let authority_1 = client_request_authority(&restarted, &identities, PartyId(1), request);
        assert!(restarted.retain_client_request(&authority_1).unwrap());
        assert!(!restarted.retain_client_request(&authority_1).unwrap());
    }

    #[test]
    fn handoff_request_cut_prunes_every_recipient_and_body_but_retains_origin_proofs() {
        let (mut runtime, _, _) = byzantine_authority_fixture();
        let (_, _, identities, _) = protocol_fixture();
        let request_a = DepositAddressRequest {
            request: deposit_request_id_for_binding(RequestBinding([0x92; 32])),
            binding: RequestBinding([0x92; 32]),
        };
        let request_b = DepositAddressRequest {
            request: deposit_request_id_for_binding(RequestBinding([0x93; 32])),
            binding: RequestBinding([0x93; 32]),
        };
        let wire_a = DepositClientRequestWire::new(
            &runtime.protocol.registry,
            request_a,
            &identities[&PartyId(1)],
        )
        .unwrap();
        let wire_b = DepositClientRequestWire::new(
            &runtime.protocol.registry,
            request_b,
            &identities[&PartyId(2)],
        )
        .unwrap();
        assert!(runtime.protocol.retain_client_request(&wire_a).unwrap());
        assert!(runtime.protocol.retain_client_request(&wire_b).unwrap());
        let body_a = postcard::to_allocvec(&wire_a).unwrap();
        let body_b = postcard::to_allocvec(&wire_b).unwrap();
        let ids = runtime
            .snapshot
            .enqueue_many([
                (1, PartyId(1), DepositOperation::ClientRequest, body_a.clone()),
                (1, PartyId(2), DepositOperation::ClientRequest, body_a),
                (9, PartyId(3), DepositOperation::ClientRequest, body_b.clone()),
                (11, PartyId(4), DepositOperation::ClientRequest, body_b),
            ])
            .unwrap();
        assert_eq!(runtime.snapshot.outbox_bodies.len(), 2);
        let revision = runtime.snapshot.revision;

        assert_eq!(
            runtime
                .snapshot
                .replace_reducer_and_prune_client_request_outbox(
                    runtime.protocol.encode_local(&runtime.deriver).unwrap(),
                )
                .unwrap(),
            ids.len(),
        );
        assert_eq!(runtime.snapshot.revision, revision + 1);
        assert!(runtime.snapshot.outbox.is_empty());
        assert!(runtime.snapshot.outbox_bodies.is_empty());

        let restarted_snapshot =
            DepositServiceSnapshot::from_bytes(&runtime.snapshot.to_bytes().unwrap()).unwrap();
        let restarted = DepositLocalState::decode(
            &restarted_snapshot.reducer,
            runtime.protocol.registry.clone(),
            runtime.protocol.ledger.clone(),
            &runtime.deriver,
            runtime.protocol.local_party,
            [0x55; 32],
        )
        .unwrap();
        assert_eq!(restarted.client_requests, runtime.protocol.client_requests);
        assert_eq!(restarted.client_requests.len(), 2);
    }

    #[tokio::test]
    async fn pinned_handoff_acks_only_fully_validated_client_request_relays() {
        let state = tempfile::tempdir().unwrap();
        let identity_seed = [0x94; 32];
        let identity = compaction_identity();
        let scenario = compaction_scenario(&identity);
        let epoch_public = compaction_epoch_public(&identity);
        let source = Arc::new(CompactionChain::default());
        source.set_tip(COMPACTION_CHAIN_TIP);
        let service = DepositService::new(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source,
        )
        .unwrap();
        let prepared = service.prepare_genesis(&epoch_public, [0x95; 32]).await.unwrap();
        service.install_prepared_genesis(prepared, None, None).await.unwrap();

        let request = DepositAddressRequest {
            request: deposit_request_id_for_binding(RequestBinding([0x96; 32])),
            binding: RequestBinding([0x96; 32]),
        };
        let (valid, before_protocol, before_snapshot) = {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            let wire =
                DepositClientRequestWire::new(&runtime.protocol.registry, request, &identity)
                    .unwrap();
            // The handler needs only the durable ingress fact. Transition-shape validation belongs
            // to `begin_handoff`; keeping this fixture local isolates late-relay behavior.
            runtime.protocol.pending_handoff = Some(epoch_public);
            (wire, runtime.protocol.clone(), runtime.snapshot.clone())
        };

        let mut malformed = valid.clone();
        malformed.origin.signature[0] ^= 0x80;
        let error = service
            .handle_client_request(PartyId(1), malformed, 1_700_000_000_000, &identity)
            .await
            .unwrap_err();
        assert!(matches!(error, DepositServiceError::Identity(IdentityError::InvalidSignature)));
        {
            let guard = service.runtime.lock().await;
            let runtime = guard.as_ref().unwrap();
            assert_eq!(runtime.protocol, before_protocol);
            assert_eq!(runtime.snapshot, before_snapshot);
        }

        service
            .handle_client_request(PartyId(1), valid, 1_700_000_000_000, &identity)
            .await
            .unwrap();
        let guard = service.runtime.lock().await;
        let runtime = guard.as_ref().unwrap();
        assert_eq!(runtime.protocol, before_protocol);
        assert_eq!(runtime.snapshot, before_snapshot);
        assert!(runtime.protocol.client_requests.is_empty());
        drop(guard);

        let local_request = DepositAddressRequest {
            request: deposit_request_id_for_binding(RequestBinding([0x9a; 32])),
            binding: RequestBinding([0x9a; 32]),
        };
        let error = service
            .submit_allocation_request(local_request, 1_700_000_000_000, &identity)
            .await
            .unwrap_err();
        assert!(matches!(error, DepositServiceError::HandoffPending));
        let guard = service.runtime.lock().await;
        let runtime = guard.as_ref().unwrap();
        assert_eq!(runtime.protocol, before_protocol);
        assert_eq!(runtime.snapshot, before_snapshot);
    }

    #[tokio::test]
    async fn first_fence_effect_persists_protocol_and_transport_request_cut_together() {
        let state = tempfile::tempdir().unwrap();
        let identity_seed = [0x97; 32];
        let identity = compaction_identity();
        let scenario = compaction_scenario(&identity);
        let epoch_public = compaction_epoch_public(&identity);
        let source = Arc::new(CompactionChain::default());
        let service = DepositService::new(
            PartyId(1),
            scenario,
            state.path(),
            &identity_seed,
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            source,
        )
        .unwrap();
        let prepared = service.prepare_genesis(&epoch_public, [0x98; 32]).await.unwrap();
        let wallet = service.install_prepared_genesis(prepared, None, None).await.unwrap();
        let request = DepositAddressRequest {
            request: deposit_request_id_for_binding(RequestBinding([0x99; 32])),
            binding: RequestBinding([0x99; 32]),
        };

        {
            let mut guard = service.runtime.lock().await;
            let runtime = guard.as_mut().unwrap();
            let wire =
                DepositClientRequestWire::new(&runtime.protocol.registry, request, &identity)
                    .unwrap();
            let mut candidate = runtime.protocol.clone();
            assert!(candidate.retain_client_request(&wire).unwrap());
            let mut effects = DepositConsensusHostEffects::default();
            effects.messages.push((
                candidate.ledger.next_sequence(),
                PartyId(1),
                DepositOperation::ClientRequest,
                postcard::to_allocvec(&wire).unwrap(),
            ));
            service
                .commit_consensus_protocol(runtime, candidate, effects, &identity)
                .await
                .unwrap();
            assert_eq!(runtime.protocol.client_requests.len(), 1);
            assert_eq!(
                runtime
                    .snapshot
                    .outbox
                    .keys()
                    .filter(|id| id.operation == DepositOperation::ClientRequest)
                    .count(),
                1,
            );

            let candidate = runtime.protocol.clone();
            let effects = DepositConsensusHostEffects {
                close_client_request_ingress: true,
                ..DepositConsensusHostEffects::default()
            };
            service
                .commit_consensus_protocol(runtime, candidate, effects, &identity)
                .await
                .unwrap();
            assert!(runtime.protocol.client_requests.is_empty());
            assert!(
                runtime
                    .snapshot
                    .outbox
                    .keys()
                    .all(|id| id.operation != DepositOperation::ClientRequest),
            );
            assert!(runtime.snapshot.outbox_bodies.is_empty());
        }

        let durable = service.repository.load(wallet).await.unwrap();
        assert!(durable.outbox.keys().all(|id| id.operation != DepositOperation::ClientRequest));
        assert!(durable.outbox_bodies.is_empty());
        let guard = service.runtime.lock().await;
        let runtime = guard.as_ref().unwrap();
        let restarted = DepositLocalState::decode(
            &durable.reducer,
            runtime.protocol.registry.clone(),
            runtime.protocol.ledger.clone(),
            &runtime.deriver,
            runtime.protocol.local_party,
            service.scenario.quic_network_id().unwrap(),
        )
        .unwrap();
        assert!(restarted.client_requests.is_empty());
    }

