    #[test]
    fn fence_checkpoint_unknown_bare_vote_is_retryable_until_alternate_certificate_is_admitted() {
        let network = [0x55; 32];
        let admitted_at = 1_700_000_000;
        let (mut protocol, _, identities, _) = protocol_fixture();
        let (target_committee, _) = test_committee(1, 0x91);
        let target = VerifiedRegistryHandoffTarget::for_test(
            target_committee,
            protocol.registry.active().fault_bound(),
            [0x92; 32],
            [0x93; 32],
            protocol.registry.wallet(),
            protocol.registry.active().key_id(),
            protocol.registry.active().group_key(),
        )
        .unwrap();
        let fence = LedgerStatement::handoff_fence(
            &protocol.registry,
            protocol.ledger.next_sequence(),
            protocol.ledger.head(),
            &target,
            ChainPoint::new(22, [0x94; 32]).unwrap(),
        )
        .unwrap();
        let payload = fence.attestation_payload().unwrap();
        let certify_with_subset = |skip: usize| {
            let attestations = identities
                .values()
                .skip(skip)
                .take(3)
                .map(|identity| {
                    identity
                        .sign_envelope(
                            protocol.registry.active().committee(),
                            fence.slot_session(),
                            None,
                            fence.sequence,
                            payload.clone(),
                        )
                        .unwrap()
                })
                .collect();
            let entry = CertifiedLedgerEntry { statement: fence.clone(), attestations };
            entry.verify_active(&protocol.registry, None).unwrap();
            entry
        };
        let first_entry = certify_with_subset(0);
        let alternate_entry = certify_with_subset(1);
        assert_ne!(first_entry.attestations, alternate_entry.attestations);
        protocol.retain_certified_pending(&first_entry, None).unwrap();
        protocol.retain_certified_pending(&alternate_entry, None).unwrap();

        let first_candidate = DepositIndexCheckpointCandidate::Ledger(first_entry);
        let alternate_candidate = DepositIndexCheckpointCandidate::Ledger(alternate_entry);
        validate_checkpoint_candidate_for_protocol(&protocol, &first_candidate).unwrap();
        validate_checkpoint_candidate_for_protocol(&protocol, &alternate_candidate).unwrap();
        let first_value = first_candidate.to_consensus_value().unwrap();
        let alternate_value = alternate_candidate.to_consensus_value().unwrap();
        assert_ne!(
            first_value.digest(),
            alternate_value.digest(),
            "different valid n-f certificate subsets must remain distinct BA values"
        );

        let context = deposit_index_checkpoint_consensus_context_from_digest(
            network,
            &protocol.registry,
            1,
            protocol.ledger.portable_index_digest(),
        )
        .unwrap();
        let leader = context.leader(0);
        let local_party = identities.keys().copied().find(|party| *party != leader).unwrap();
        let voter = identities
            .keys()
            .copied()
            .find(|party| *party != leader && *party != local_party)
            .unwrap();
        let local_identity = identities.get(&local_party).unwrap();
        let mut reducer = DepositConsensus::new(context.clone(), local_party).unwrap();
        let initial = reducer.start(local_identity, first_value.clone()).unwrap();
        assert!(initial.broadcast.is_empty(), "the non-leader must not propose");
        let purpose = DepositConsensusPurpose::NextIndexCheckpoint { sequence: 1 };
        let mut lane = DurableDepositCheckpointConsensusLane::new(
            purpose,
            reducer,
            admitted_at,
            admitted_at * 1_000 + 60_000,
        )
        .unwrap();
        install_checkpoint_consensus_admission(&mut lane, admitted_at, first_candidate.clone())
            .unwrap();

        let overtaking_vote = sign_consensus_message(
            &context,
            identities.get(&voter).unwrap(),
            ConsensusMessageBody::Prevote(Vote {
                view: lane.reducer.view(),
                value: alternate_value.digest(),
            }),
        )
        .unwrap();
        let overtaking_wire =
            DepositConsensusWire::envelope(context.clone(), purpose, overtaking_vote.clone());
        assert!(referenced_digests(&overtaking_wire).is_empty());
        let before_deferral = lane.clone();
        assert!(matches!(
            defer_unknown_bare_vote(&overtaking_wire, &lane.reducer, &lane.admitted_values,),
            Err(DepositServiceError::ConsensusUnavailable)
        ));
        assert_eq!(
            lane, before_deferral,
            "causal deferral must not mutate the reducer, admissions, timers, or durable outbox state"
        );

        let proposal = sign_consensus_message(
            &context,
            identities.get(&leader).unwrap(),
            ConsensusMessageBody::Proposal(Proposal {
                view: lane.reducer.view(),
                value: alternate_value.clone(),
                proof_of_lock: None,
                view_change: None,
            }),
        )
        .unwrap();
        let proposal_wire =
            DepositConsensusWire::envelope(context.clone(), purpose, proposal.clone());
        defer_unknown_bare_vote(&proposal_wire, &lane.reducer, &lane.admitted_values).unwrap();
        let proposal_step = lane
            .reducer
            .handle_with_value_validator(local_identity, proposal, |value| {
                value == &alternate_value
            })
            .unwrap();
        assert!(proposal_step.changed);
        install_checkpoint_consensus_admission(&mut lane, admitted_at, alternate_candidate)
            .unwrap();

        defer_unknown_bare_vote(&overtaking_wire, &lane.reducer, &lane.admitted_values).unwrap();
        let before_retry = lane.clone();
        let retry = lane
            .reducer
            .handle_with_value_validator(local_identity, overtaking_vote.clone(), |_| false)
            .unwrap();
        assert!(retry.changed, "the retained sender retry must now be reduced");
        assert_ne!(lane, before_retry);
        let duplicate = lane
            .reducer
            .handle_with_value_validator(local_identity, overtaking_vote, |_| false)
            .unwrap();
        assert!(duplicate.duplicate);
        assert_eq!(lane.admitted_values.len(), 2);
    }

    #[test]
    fn handoff_bare_vote_deferral_is_authenticated_and_view_bounded() {
        let (context, identities) = consensus_fixture();
        let leader = context.leader(0);
        let local_party = identities.keys().copied().find(|party| *party != leader).unwrap();
        let voter = identities
            .keys()
            .copied()
            .find(|party| *party != local_party && *party != leader)
            .unwrap();
        let local_identity = identities.get(&local_party).unwrap();
        let known = opaque_consensus_value(0xb1);
        let unknown = opaque_consensus_value(0xb2);
        let admitted = BTreeMap::from([(known.digest(), ())]);
        let mut reducer =
            DepositConsensus::new_handoff_only(context.clone(), local_party, [known.digest()])
                .unwrap();
        reducer.start(local_identity, known.clone()).unwrap();
        let purpose = DepositConsensusPurpose::NextLedgerSlot { sequence: context.sequence() };

        let current_unknown_envelope = sign_consensus_message(
            &context,
            identities.get(&voter).unwrap(),
            ConsensusMessageBody::Prevote(Vote { view: 0, value: unknown.digest() }),
        )
        .unwrap();
        let current_unknown = DepositConsensusWire::envelope(
            context.clone(),
            purpose,
            current_unknown_envelope.clone(),
        );
        assert!(matches!(
            defer_unknown_bare_vote(&current_unknown, &reducer, &admitted),
            Err(DepositServiceError::ConsensusUnavailable)
        ));

        let future_unknown = DepositConsensusWire::envelope(
            context.clone(),
            purpose,
            sign_consensus_message(
                &context,
                identities.get(&voter).unwrap(),
                ConsensusMessageBody::Precommit(Vote { view: 1, value: unknown.digest() }),
            )
            .unwrap(),
        );
        assert!(matches!(
            defer_unknown_bare_vote(&future_unknown, &reducer, &admitted),
            Err(DepositServiceError::ConsensusUnavailable)
        ));

        let known_vote = DepositConsensusWire::envelope(
            context.clone(),
            purpose,
            sign_consensus_message(
                &context,
                identities.get(&voter).unwrap(),
                ConsensusMessageBody::Prevote(Vote { view: 0, value: known.digest() }),
            )
            .unwrap(),
        );
        defer_unknown_bare_vote(&known_vote, &reducer, &admitted).unwrap();

        let proposal = DepositConsensusWire::envelope(
            context.clone(),
            purpose,
            sign_consensus_message(
                &context,
                identities.get(&leader).unwrap(),
                ConsensusMessageBody::Proposal(Proposal {
                    view: 0,
                    value: unknown.clone(),
                    proof_of_lock: None,
                    view_change: None,
                }),
            )
            .unwrap(),
        );
        defer_unknown_bare_vote(&proposal, &reducer, &admitted).unwrap();

        let view_change_witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                sign_consensus_message(
                    &context,
                    identity,
                    ConsensusMessageBody::ViewChange(ViewChange {
                        from_view: 0,
                        target_view: 1,
                        highest_prepared: None,
                    }),
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        let view_change = DepositConsensusWire::envelope(
            context.clone(),
            purpose,
            view_change_witnesses[0].clone(),
        );
        defer_unknown_bare_vote(&view_change, &reducer, &admitted).unwrap();
        let view_certificate =
            ViewChangeCertificate::from_witnesses(&context, 1, view_change_witnesses).unwrap();
        let view_certificate_wire = DepositConsensusWire::view_certificate(
            context.clone(),
            purpose,
            view_certificate.clone(),
        );
        defer_unknown_bare_vote(&view_certificate_wire, &reducer, &admitted).unwrap();

        let commit_witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                sign_consensus_message(
                    &context,
                    identity,
                    ConsensusMessageBody::Precommit(Vote { view: 0, value: unknown.digest() }),
                )
                .unwrap()
            })
            .collect();
        let commit =
            CommitCertificate::from_witnesses(&context, 0, unknown, commit_witnesses).unwrap();
        let commit_wire =
            DepositConsensusWire::commit_certificate(context.clone(), purpose, commit);
        defer_unknown_bare_vote(&commit_wire, &reducer, &admitted).unwrap();

        let mut malformed_envelope = current_unknown_envelope.clone();
        malformed_envelope.payload[0] ^= 1;
        let malformed =
            DepositConsensusWire::envelope(context.clone(), purpose, malformed_envelope);
        let malformed_error = defer_unknown_bare_vote(&malformed, &reducer, &admitted).unwrap_err();
        assert!(
            !matches!(malformed_error, DepositServiceError::ConsensusUnavailable),
            "failed authentication must remain terminal rather than enter the retry queue"
        );

        reducer
            .handle_view_certificate_with_validator(local_identity, view_certificate, |_| true)
            .unwrap();
        assert_eq!(reducer.view(), 1);
        defer_unknown_bare_vote(&current_unknown, &reducer, &admitted).unwrap();
        assert!(matches!(
            reducer.handle_with_value_validator(local_identity, current_unknown_envelope, |_| true),
            Err(ConsensusError::UnauthorizedHandoffValue | ConsensusError::StaleView { .. })
        ));
    }

    #[test]
    fn certified_gossip_markers_change_only_at_threshold_and_ignore_duplicates() {
        let (mut protocol, _, identities, statement) = protocol_fixture();
        let required = usize::from(
            protocol.registry.active().committee().n() - protocol.registry.active().fault_bound(),
        );
        protocol.pending.insert(
            statement.sequence,
            PendingLedgerSlot { statement: statement.clone(), attestations: BTreeMap::new() },
        );
        let payload = statement.attestation_payload().unwrap();
        let ledger_witnesses = identities
            .values()
            .take(required)
            .map(|identity| {
                identity
                    .sign_envelope(
                        protocol.registry.active().committee(),
                        statement.slot_session(),
                        None,
                        statement.sequence,
                        payload.clone(),
                    )
                    .unwrap()
            })
            .collect::<Vec<_>>();
        for (index, witness) in ledger_witnesses.iter().cloned().enumerate() {
            let certificate = protocol.accept_attestation(&statement, witness, None).unwrap();
            assert_eq!(certificate.is_some(), index + 1 == required);
            assert_eq!(
                protocol.has_certified_ledger_slot(statement.sequence),
                index + 1 == required
            );
        }
        let certified_ledger = protocol.clone();
        assert!(
            protocol
                .accept_attestation(&statement, ledger_witnesses.last().unwrap().clone(), None)
                .unwrap()
                .is_some()
        );
        assert_eq!(
            protocol, certified_ledger,
            "a duplicate ledger witness must not reopen certificate gossip"
        );

        let observation = observation_statement(&protocol.registry, &statement, 0x91);
        assert!(protocol.retain_deposit_observation(observation.clone()).unwrap());
        let observation_witnesses = identities
            .values()
            .take(required)
            .map(|identity| {
                sign_deposit_observation_attestation(identity, &protocol.registry, &observation)
                    .unwrap()
            })
            .collect::<Vec<_>>();
        for (index, witness) in observation_witnesses.iter().cloned().enumerate() {
            let certificate =
                protocol.accept_deposit_observation_attestation(&observation, witness).unwrap();
            assert_eq!(certificate.is_some(), index + 1 == required);
            assert_eq!(
                protocol.has_certified_deposit_observation(observation.output()),
                index + 1 == required
            );
        }
        let certified_observation = protocol.clone();
        assert!(
            protocol
                .accept_deposit_observation_attestation(
                    &observation,
                    observation_witnesses.last().unwrap().clone(),
                )
                .unwrap()
                .is_some()
        );
        assert_eq!(
            protocol, certified_observation,
            "a duplicate observation witness must not reopen certificate gossip"
        );
    }

    #[test]
    fn committed_checkpoint_selection_restores_without_reopening_the_slot() {
        let (mut protocol, deriver, identities, statement) = protocol_fixture();
        let payload = statement.attestation_payload().unwrap();
        let attestations = identities
            .values()
            .take(3)
            .map(|identity| {
                identity
                    .sign_envelope(
                        protocol.registry.active().committee(),
                        statement.slot_session(),
                        None,
                        statement.sequence,
                        payload.clone(),
                    )
                    .unwrap()
            })
            .collect();
        let entry = CertifiedLedgerEntry { statement, attestations };
        entry.verify_active(&protocol.registry, None).unwrap();
        protocol.retain_certified_pending(&entry, None).unwrap();
        let previous = PortableDepositIndexHead::from_head(
            &DepositIndexHead::empty_portable(deriver.wallet_id(), protocol.ledger.next_index())
                .unwrap(),
        )
        .unwrap();
        let context = deposit_index_checkpoint_consensus_context(
            [0x55; 32],
            &protocol.registry,
            1,
            &previous,
        )
        .unwrap();
        let operation = DepositIndexCheckpointCandidate::Ledger(entry);
        let value = operation.to_consensus_value().unwrap();
        let witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                sign_consensus_message(
                    &context,
                    identity,
                    ConsensusMessageBody::Precommit(Vote { view: 0, value: value.digest() }),
                )
                .unwrap()
            })
            .collect();
        let commit =
            CommitCertificate::from_witnesses(&context, 0, value.clone(), witnesses).unwrap();
        let mut reducer = DepositConsensus::new(context.clone(), PartyId(1)).unwrap();
        reducer
            .handle_commit_certificate_with_validator(commit.clone(), |candidate| {
                candidate == &value
            })
            .unwrap();
        let mut lane = DurableDepositCheckpointConsensusLane::new(
            DepositConsensusPurpose::NextIndexCheckpoint { sequence: 1 },
            reducer,
            1_699_999_999,
            1_700_000_999_000,
        )
        .unwrap();
        install_checkpoint_consensus_admission(&mut lane, 1_699_999_999, operation.clone())
            .unwrap();
        // Redispatch after the client-visible deadline reuses the first durable reservation; it
        // must not replace that reservation with the retry clock.
        install_checkpoint_consensus_admission(&mut lane, 1_700_000_123, operation.clone())
            .unwrap();
        assert_eq!(lane.admitted_values.get(&value.digest()).unwrap().admitted_at, 1_699_999_999,);

        let mut late_lane = DurableDepositCheckpointConsensusLane::new(
            DepositConsensusPurpose::NextIndexCheckpoint { sequence: 1 },
            DepositConsensus::new(context, PartyId(1)).unwrap(),
            1_700_000_123,
            1_700_000_999_000,
        )
        .unwrap();
        assert!(matches!(
            install_checkpoint_consensus_admission(&mut late_lane, 1_700_000_123, operation),
            Err(DepositServiceError::AllocationExpired)
        ));
        protocol.checkpoint_consensus_lane = Some(lane);
        protocol.validate(&deriver).unwrap();

        let mut corrupted = protocol.clone();
        corrupted
            .checkpoint_consensus_lane
            .as_mut()
            .unwrap()
            .admitted_values
            .get_mut(&value.digest())
            .unwrap()
            .admitted_at = 1_700_000_000;
        assert!(matches!(
            corrupted.validate(&deriver),
            Err(DepositServiceError::InvalidProtocolState)
        ));

        let registry = protocol.registry.clone();
        let ledger = protocol.ledger.clone();
        let encoded = protocol.encode_local(&deriver).unwrap();
        let restored =
            DepositLocalState::decode(&encoded, registry, ledger, &deriver, PartyId(1), [0x55; 32])
                .unwrap();
        let restored_lane = restored.checkpoint_consensus_lane.unwrap();
        assert_eq!(restored_lane.reducer.commit(), Some(&commit));
        assert_eq!(
            DepositIndexCheckpointCandidate::from_consensus_value(
                restored_lane.reducer.commit().unwrap().value()
            )
            .unwrap()
            .operation(),
            DepositIndexCheckpointOperation::Ledger {
                statement: restored_lane
                    .admitted_values
                    .values()
                    .next()
                    .and_then(|admitted| match &admitted.candidate {
                        DepositIndexCheckpointCandidate::Ledger(entry) => {
                            Some(entry.statement.digest())
                        }
                        DepositIndexCheckpointCandidate::DepositObservation(_) => None,
                    })
                    .unwrap(),
            }
        );
    }

    #[test]
    fn commit_certificate_recovery_uses_a_valid_predeadline_reservation() {
        let (protocol, deriver, identities, _) = protocol_fixture();
        let binding = RequestBinding([0x82; 32]);
        let created_at = 1_700_000_000;
        let statement = LedgerStatement::allocation(
            &protocol.registry,
            protocol.ledger.next_sequence(),
            protocol.ledger.head(),
            deposit_request_id_for_binding(binding),
            binding,
            deriver.derive(protocol.ledger.next_index()),
            ChainPoint::new(10, [0x83; 32]).unwrap(),
            created_at,
        )
        .unwrap();
        let late_now = created_at + 123;
        let request =
            DepositAddressRequest { request: deposit_request_id_for_binding(binding), binding };
        let authority = client_request_authority(&protocol, &identities, PartyId(1), request);
        let value = DepositConsensusValue::allocation(statement.clone(), authority).unwrap();
        let admitted_at = certified_consensus_recovery_admitted_at(&value, late_now).unwrap();
        assert_eq!(admitted_at, created_at - MIN_ALLOCATION_CERTIFICATION_LEAD_SECONDS);
        validate_allocation_created_at(created_at, admitted_at).unwrap();
        assert!(matches!(
            validate_deposit_consensus_value(
                &protocol,
                &deriver,
                None,
                &value,
                late_now,
                DepositConsensusPurpose::NextLedgerSlot { sequence: statement.sequence },
                DepositConsensusAdmissionProvenance::Fresh,
                Some([0x55; 32]),
            ),
            Err(DepositServiceError::AllocationExpired)
        ));
        validate_deposit_consensus_value(
            &protocol,
            &deriver,
            None,
            &value,
            admitted_at,
            DepositConsensusPurpose::NextLedgerSlot { sequence: statement.sequence },
            DepositConsensusAdmissionProvenance::QuorumBackedRecovery,
            Some([0x55; 32]),
        )
        .unwrap();

        let payload = statement.attestation_payload().unwrap();
        let attestations = identities
            .values()
            .take(3)
            .map(|identity| {
                identity
                    .sign_envelope(
                        protocol.registry.active().committee(),
                        statement.slot_session(),
                        None,
                        statement.sequence,
                        payload.clone(),
                    )
                    .unwrap()
            })
            .collect();
        let checkpoint_candidate = DepositIndexCheckpointCandidate::Ledger(CertifiedLedgerEntry {
            statement,
            attestations,
        });
        let reserved_at =
            certified_checkpoint_candidate_reserved_at(&checkpoint_candidate, late_now).unwrap();
        assert_eq!(reserved_at, created_at - 1);
        assert!(checkpoint_candidate_reservation_is_timely(&checkpoint_candidate, reserved_at));
        let checkpoint_context = deposit_index_checkpoint_consensus_context_from_digest(
            [0x55; 32],
            &protocol.registry,
            1,
            protocol.ledger.portable_index_digest(),
        )
        .unwrap();
        let mut recovered_lane = DurableDepositCheckpointConsensusLane::new(
            DepositConsensusPurpose::NextIndexCheckpoint { sequence: 1 },
            DepositConsensus::new(checkpoint_context.clone(), PartyId(1)).unwrap(),
            late_now,
            late_now * 1_000 + 60_000,
        )
        .unwrap();
        install_checkpoint_consensus_admission(
            &mut recovered_lane,
            reserved_at,
            checkpoint_candidate.clone(),
        )
        .unwrap();
        assert_eq!(
            recovered_lane
                .admitted_values
                .get(&checkpoint_candidate.to_consensus_value().unwrap().digest())
                .unwrap()
                .admitted_at,
            created_at - 1
        );
        assert!(matches!(
            install_checkpoint_consensus_admission(
                &mut DurableDepositCheckpointConsensusLane::new(
                    DepositConsensusPurpose::NextIndexCheckpoint { sequence: 1 },
                    DepositConsensus::new(checkpoint_context, PartyId(1)).unwrap(),
                    late_now,
                    late_now * 1_000 + 60_000,
                )
                .unwrap(),
                late_now,
                checkpoint_candidate,
            ),
            Err(DepositServiceError::AllocationExpired)
        ));
    }

    #[test]
    fn verified_ledger_commit_replaces_saturated_lane_and_rejects_mismatch_or_conflict() {
        let network = [0x55; 32];
        let admitted_at = 1_700_000_000;
        let (protocol, deriver, identities, _) = protocol_fixture();
        let identity = identities.get(&PartyId(1)).unwrap();
        let service_state = tempfile::tempdir().unwrap();
        let service_identity = compaction_identity();
        let service = DepositService::new(
            PartyId(1),
            compaction_scenario(&service_identity),
            service_state.path(),
            &[0xcc; 32],
            Zeroizing::new(Scalar::from(17_u64).to_bytes()),
            DepositWorkerConfig::default(),
            Arc::new(CompactionChain::default()),
        )
        .unwrap();
        let purpose =
            DepositConsensusPurpose::NextLedgerSlot { sequence: protocol.ledger.next_sequence() };
        let context = deposit_consensus_context(&protocol, deriver.wallet_id(), network).unwrap();
        let make_admission = |nonce: u64| {
            let mut binding = [0xd1; 32];
            binding[..8].copy_from_slice(&nonce.to_le_bytes());
            let binding = RequestBinding(binding);
            let request =
                DepositAddressRequest { request: deposit_request_id_for_binding(binding), binding };
            let authority =
                DepositClientRequestWire::new(&protocol.registry, request, identity).unwrap();
            let statement = LedgerStatement::allocation(
                &protocol.registry,
                protocol.ledger.next_sequence(),
                protocol.ledger.head(),
                request.request,
                request.binding,
                deriver.derive(protocol.ledger.next_index()),
                ChainPoint::new(10, [0xd2; 32]).unwrap(),
                admitted_at + ALLOCATION_ISSUANCE_LEAD_SECONDS,
            )
            .unwrap();
            let value = DepositConsensusValue::allocation(statement, authority).unwrap();
            let admission = validate_deposit_consensus_value(
                &protocol,
                &deriver,
                None,
                &value,
                admitted_at,
                purpose,
                DepositConsensusAdmissionProvenance::Fresh,
                Some(network),
            )
            .unwrap();
            (value, admission)
        };

        let mut values = (1..=u64::try_from(MAX_ADMITTED_CONSENSUS_VALUES + 2).unwrap())
            .map(make_admission)
            .collect::<Vec<_>>();
        let first_value = values.first().unwrap().0.clone();
        let mut reducer = DepositConsensus::new(context.clone(), PartyId(1)).unwrap();
        reducer.start(identity, first_value.clone()).unwrap();
        let mut saturated = DurableDepositConsensusLane::new(
            purpose,
            reducer,
            admitted_at,
            admitted_at * 1_000 + 60_000,
        )
        .unwrap();
        for (_, admission) in values.drain(..MAX_ADMITTED_CONSENSUS_VALUES) {
            assert!(
                saturated.admitted_values.insert(admission.digest, admission.admitted).is_none()
            );
        }
        assert_eq!(saturated.admitted_values.len(), MAX_ADMITTED_CONSENSUS_VALUES);
        let (winner, winner_admission) = values.remove(0);
        let winner_witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                sign_consensus_message(
                    &context,
                    identity,
                    ConsensusMessageBody::Precommit(Vote { view: 0, value: winner.digest() }),
                )
                .unwrap()
            })
            .collect();
        let winner_certificate =
            CommitCertificate::from_witnesses(&context, 0, winner.clone(), winner_witnesses)
                .unwrap();

        let mismatched_admission = values.remove(0).1;
        assert!(matches!(
            service.replace_saturated_ledger_lane_with_verified_commit(
                &protocol,
                &saturated,
                context.clone(),
                purpose,
                winner_certificate.clone(),
                mismatched_admission,
                identity,
                admitted_at * 1_000,
            ),
            Err(DepositServiceError::InvalidProtocolState)
        ));

        let first_certificate = CommitCertificate::from_witnesses(
            &context,
            0,
            first_value.clone(),
            identities
                .values()
                .take(3)
                .map(|identity| {
                    sign_consensus_message(
                        &context,
                        identity,
                        ConsensusMessageBody::Precommit(Vote {
                            view: 0,
                            value: first_value.digest(),
                        }),
                    )
                    .unwrap()
                })
                .collect(),
        )
        .unwrap();
        let mut conflicting = saturated.clone();
        conflicting
            .reducer
            .handle_commit_certificate_with_validator(first_certificate, |value| {
                value == &first_value
            })
            .unwrap();
        assert!(matches!(
            service.replace_saturated_ledger_lane_with_verified_commit(
                &protocol,
                &conflicting,
                context.clone(),
                purpose,
                winner_certificate.clone(),
                winner_admission.clone(),
                identity,
                admitted_at * 1_000,
            ),
            Err(DepositServiceError::InvalidConsensusValue)
        ));

        let (replacement, step) = service
            .replace_saturated_ledger_lane_with_verified_commit(
                &protocol,
                &saturated,
                context,
                purpose,
                winner_certificate.clone(),
                winner_admission,
                identity,
                admitted_at * 1_000,
            )
            .unwrap();
        assert_eq!(step.commit.as_ref(), Some(&winner_certificate));
        assert_eq!(replacement.reducer.commit(), Some(&winner_certificate));
        assert_eq!(
            replacement.admitted_values.keys().copied().collect::<BTreeSet<_>>(),
            BTreeSet::from([winner.digest()]),
        );

        let encoded = postcard::to_allocvec(&replacement).unwrap();
        let restarted: DurableDepositConsensusLane = postcard::from_bytes(&encoded).unwrap();
        assert_eq!(restarted, replacement);
        let admitted = restarted.admitted_values.get(&winner.digest()).unwrap();
        let restored_value = DepositConsensusValue::from_admitted(admitted).unwrap();
        assert_eq!(restored_value, winner);
        validate_deposit_consensus_value(
            &protocol,
            &deriver,
            None,
            &restored_value,
            admitted.admitted_at,
            purpose,
            DepositConsensusAdmissionProvenance::DurableRevalidation,
            Some(network),
        )
        .unwrap();
    }

    #[test]
    fn verified_checkpoint_selection_replaces_exactly_saturated_losers_and_survives_restart() {
        let network = [0x55; 32];
        let admitted_at = 1_699_999_999;
        let deadline_unix_ms = 1_700_000_999_000;
        let (mut protocol, deriver, identities, allocation) = protocol_fixture();
        let previous = PortableDepositIndexHead::from_head(
            &DepositIndexHead::empty_portable(deriver.wallet_id(), protocol.ledger.next_index())
                .unwrap(),
        )
        .unwrap();
        let context =
            deposit_index_checkpoint_consensus_context(network, &protocol.registry, 1, &previous)
                .unwrap();
        let purpose = DepositConsensusPurpose::NextIndexCheckpoint { sequence: 1 };
        let mut saturated = DurableDepositCheckpointConsensusLane::new(
            purpose,
            DepositConsensus::new(context.clone(), protocol.local_party).unwrap(),
            admitted_at,
            deadline_unix_ms,
        )
        .unwrap();
        let registry = protocol.registry.clone();
        let certify = |statement: DepositObservationStatement| {
            let attestations = identities
                .values()
                .take(3)
                .map(|identity| {
                    sign_deposit_observation_attestation(identity, &registry, &statement).unwrap()
                })
                .collect();
            CertifiedDepositObservation { statement, attestations }
        };

        let mut first_loser = None;
        for nonce in 1..=u64::try_from(MAX_ADMITTED_CONSENSUS_VALUES).unwrap() {
            let observation =
                certify(observation_statement(&protocol.registry, &allocation, nonce));
            protocol.retain_certified_deposit_observation(&observation).unwrap();
            let candidate = DepositIndexCheckpointCandidate::DepositObservation(observation);
            first_loser.get_or_insert_with(|| candidate.clone());
            install_checkpoint_consensus_admission(&mut saturated, admitted_at, candidate).unwrap();
        }
        assert_eq!(saturated.admitted_values.len(), MAX_ADMITTED_CONSENSUS_VALUES);

        let winner_observation = certify(observation_statement(
            &protocol.registry,
            &allocation,
            u64::try_from(MAX_ADMITTED_CONSENSUS_VALUES + 1).unwrap(),
        ));
        protocol.retain_certified_deposit_observation(&winner_observation).unwrap();
        let winner =
            DepositIndexCheckpointCandidate::DepositObservation(winner_observation.clone());
        assert!(matches!(
            install_checkpoint_consensus_admission(&mut saturated, admitted_at, winner.clone(),),
            Err(DepositServiceError::ConsensusRequestPoolFull)
        ));
        assert_eq!(saturated.admitted_values.len(), MAX_ADMITTED_CONSENSUS_VALUES);

        // Restart at the exact ordinary admission cap before the terminal certificate arrives.
        protocol.checkpoint_consensus_lane = Some(saturated.clone());
        let encoded = protocol.encode_local(&deriver).unwrap();
        let mut restarted = DepositLocalState::decode(
            &encoded,
            protocol.registry.clone(),
            protocol.ledger.clone(),
            &deriver,
            protocol.local_party,
            network,
        )
        .unwrap();
        let restarted_saturated = restarted.checkpoint_consensus_lane.take().unwrap();
        assert_eq!(restarted_saturated.admitted_values.len(), MAX_ADMITTED_CONSENSUS_VALUES);

        let winner_value = winner.to_consensus_value().unwrap();
        let winner_witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                sign_consensus_message(
                    &context,
                    identity,
                    ConsensusMessageBody::Precommit(Vote { view: 0, value: winner_value.digest() }),
                )
                .unwrap()
            })
            .collect();
        let winner_selection =
            CommitCertificate::from_witnesses(&context, 0, winner_value.clone(), winner_witnesses)
                .unwrap();

        // A valid certificate for another value is not authority to evict this lane for `winner`.
        let loser = first_loser.unwrap();
        let loser_value = loser.to_consensus_value().unwrap();
        let loser_witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                sign_consensus_message(
                    &context,
                    identity,
                    ConsensusMessageBody::Precommit(Vote { view: 0, value: loser_value.digest() }),
                )
                .unwrap()
            })
            .collect();
        let wrong_selection =
            CommitCertificate::from_witnesses(&context, 0, loser_value, loser_witnesses).unwrap();
        assert!(
            install_verified_checkpoint_consensus_selection(
                Some(restarted_saturated.clone()),
                purpose,
                context.clone(),
                restarted.local_party,
                wrong_selection,
                winner.clone(),
                admitted_at,
                deadline_unix_ms,
            )
            .is_err()
        );
        assert_eq!(
            restarted_saturated.admitted_values.len(),
            MAX_ADMITTED_CONSENSUS_VALUES,
            "failed terminal verification must not mutate the saturated lane"
        );

        let corrected = install_verified_checkpoint_consensus_selection(
            Some(restarted_saturated),
            purpose,
            context,
            restarted.local_party,
            winner_selection.clone(),
            winner.clone(),
            admitted_at,
            deadline_unix_ms,
        )
        .unwrap();
        assert_eq!(corrected.admitted_values.len(), 1);
        assert_eq!(
            corrected.admitted_values.values().next().map(|admitted| &admitted.candidate),
            Some(&winner)
        );
        assert_eq!(corrected.reducer.commit().map(CommitCertificate::value), Some(&winner_value));
        restarted.checkpoint_consensus_lane = Some(corrected);

        // The selected-only correction is the current durable representation and remains valid
        // after another authenticated local-state restart.
        let corrected_bytes = restarted.encode_local(&deriver).unwrap();
        let corrected_restart = DepositLocalState::decode(
            &corrected_bytes,
            restarted.registry.clone(),
            restarted.ledger.clone(),
            &deriver,
            restarted.local_party,
            network,
        )
        .unwrap();
        assert_eq!(
            corrected_restart
                .checkpoint_consensus_lane
                .as_ref()
                .and_then(|lane| lane.reducer.commit()),
            Some(&winner_selection)
        );
        assert!(
            corrected_restart.committed_checkpoint_selection(&winner).is_ok(),
            "restart must retain the terminal winner without reopening ordinary admission"
        );
    }

    /// Regression guard for the checkpoint-commit livelock (Byzantine liveness).
    ///
    /// A certified ledger entry `L` and a certified observation `O` compete for the same portable
    /// checkpoint sequence `s`. The checkpoint BA lane commits `O` while `L` stays certified. The
    /// fixed behavior is that the *committed BA lane* — not the `next_certified_ledger_entry`
    /// fallback — decides which operation the durable checkpoint round signs:
    ///
    /// * the observation checkpoint stages and completes even though a certified ledger entry
    ///   exists (the losing `L` must not veto `O`'s staging), advancing `checkpoint_sequence`;
    /// * a restart resumes the committed `O`, never the certified-but-losing `L`;
    /// * once `O` is adopted, `L` becomes the winning candidate for the next sequence `s + 1`.
    ///
    /// This fails if the observation staging guard is reverted to key on
    /// `next_certified_ledger_entry`, or if progress/recovery consult
    /// `next_certified_ledger_entry` before the committed checkpoint lane, because both regressions
    /// resurrect the permanent redispatch of the losing lane.
    #[test]
    fn committed_observation_checkpoint_wins_over_losing_certified_ledger_and_ledger_follows_at_next_sequence()
     {
        struct EmptyReader;
        impl DepositIndexReader for EmptyReader {
            fn load_index_object(
                &self,
                _id: DepositIndexObjectId,
            ) -> Result<Option<Vec<u8>>, DepositIndexError> {
                Ok(None)
            }
        }

        #[derive(Default)]
        struct MemReader {
            objects: BTreeMap<DepositIndexObjectId, Vec<u8>>,
        }
        impl MemReader {
            fn apply(&mut self, update: &DepositIndexUpdate) {
                for id in update.obsolete_objects() {
                    self.objects.remove(&id);
                }
                self.objects
                    .extend(update.staged_objects().map(|(id, bytes)| (id, bytes.to_vec())));
            }
        }
        impl DepositIndexReader for MemReader {
            fn load_index_object(
                &self,
                id: DepositIndexObjectId,
            ) -> Result<Option<Vec<u8>>, DepositIndexError> {
                Ok(self.objects.get(&id).cloned())
            }
        }

        let network = [0x55; 32];
        let (mut protocol, deriver, identities, allocation) = protocol_fixture();
        let registry = protocol.registry.clone();
        let committee = registry.active().committee().clone();

        let certify_ledger = |statement: LedgerStatement| -> CertifiedLedgerEntry {
            let payload = statement.attestation_payload().unwrap();
            let attestations = identities
                .values()
                .take(3)
                .map(|identity| {
                    identity
                        .sign_envelope(
                            &committee,
                            statement.slot_session(),
                            None,
                            statement.sequence,
                            payload.clone(),
                        )
                        .unwrap()
                })
                .collect();
            let entry = CertifiedLedgerEntry { statement, attestations };
            entry.verify_active(&registry, None).unwrap();
            entry
        };

        // ----- Advance the portable index + compact ledger by one certified allocation so an
        // observation of the committed allocation is a legitimate checkpoint candidate. -----
        let head0 =
            DepositIndexHead::empty_portable(deriver.wallet_id(), protocol.ledger.next_index())
                .unwrap();
        let ledger_one = certify_ledger(allocation.clone());
        let reader = EmptyReader;
        let preflight = DepositIndexBuilder::new(&reader, head0.clone())
            .unwrap()
            .preflight_ledger_statement(&ledger_one.statement)
            .unwrap();
        let mut builder = DepositIndexBuilder::new(&reader, head0.clone()).unwrap();
        assert!(builder.apply_verified_active_entry(&ledger_one, &registry, None).unwrap());
        let allocation_update = builder.finish().unwrap().unwrap();
        let allocation_checkpoint_statement = DepositIndexCheckpointStatement::for_transition(
            1_699_999_000,
            network,
            &registry,
            None,
            None,
            &ledger_one,
            &preflight,
            &allocation_update,
            &reader,
        )
        .unwrap();
        let allocation_selection =
            crate::deposit_index_checkpoint::certify_checkpoint_candidate_for_test(
                network,
                &registry,
                allocation_checkpoint_statement.sequence(),
                allocation_checkpoint_statement.previous_head(),
                DepositIndexCheckpointCandidate::Ledger(ledger_one.clone()),
                &identities,
            );
        let allocation_witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                identity
                    .sign_envelope(
                        &committee,
                        allocation_checkpoint_statement.slot_session(),
                        None,
                        allocation_checkpoint_statement.sequence(),
                        allocation_checkpoint_statement.to_bytes().unwrap(),
                    )
                    .unwrap()
            })
            .collect();
        let allocation_certificate = DepositIndexCheckpointCertificate::from_witnesses(
            network,
            &registry,
            None,
            None,
            &ledger_one,
            allocation_checkpoint_statement,
            allocation_selection,
            allocation_witnesses,
        )
        .unwrap();
        let previous = allocation_certificate
            .verify_active(network, &registry, None, None, &ledger_one)
            .unwrap();
        protocol.ledger = previous.compact_cursor(&registry, Some(&allocation)).unwrap();
        protocol.checkpoint_sequence = previous.sequence();
        assert_eq!(protocol.checkpoint_sequence, 1);
        assert_eq!(protocol.ledger.next_sequence(), 2);
        assert_eq!(protocol.ledger.head(), allocation.digest());

        // ----- Candidate O: certified observation of the now-committed allocation. -----
        let observation_statement = observation_statement(&registry, &allocation, 1);
        let observation = CertifiedDepositObservation {
            statement: observation_statement.clone(),
            attestations: identities
                .values()
                .skip(1)
                .take(3)
                .map(|identity| {
                    sign_deposit_observation_attestation(
                        identity,
                        &registry,
                        &observation_statement,
                    )
                    .unwrap()
                })
                .collect(),
        };
        observation.verify_active(&registry).unwrap();
        protocol.retain_certified_deposit_observation(&observation).unwrap();

        // ----- Candidate L: certified next ledger slot (sequence s at the ledger level). It stays
        // certified while O wins the checkpoint BA lane. -----
        let losing_ledger_statement = LedgerStatement::allocation(
            &registry,
            protocol.ledger.next_sequence(),
            protocol.ledger.head(),
            LedgerRequestId([0x51; 32]),
            RequestBinding([0x52; 32]),
            deriver.derive(protocol.ledger.next_index()),
            ChainPoint::new(10, [0x34; 32]).unwrap(),
            1_700_000_000,
        )
        .unwrap();
        let losing_ledger = certify_ledger(losing_ledger_statement);
        protocol.retain_certified_pending(&losing_ledger, None).unwrap();
        // The losing ledger candidate really is a certified competitor for this checkpoint slot: a
        // regression that consulted this fallback first would redispatch the wrong lane.
        assert_eq!(
            protocol.next_certified_ledger_entry().map(|entry| entry.statement.digest()),
            Some(losing_ledger.statement.digest())
        );

        // ----- Observation-only checkpoint transition/material for O at sequence s = 2. -----
        let mut mem = MemReader::default();
        mem.apply(&allocation_update);
        let mut observation_builder =
            DepositIndexBuilder::new(&mem, allocation_update.next_head().clone()).unwrap();
        assert!(
            observation_builder
                .apply_verified_active_deposit_observation(&observation, &registry)
                .unwrap()
        );
        let observation_update = observation_builder.finish().unwrap().unwrap();
        let observation_transition = observation_update
            .verify_deposit_observation_transition(&mem, &observation.statement)
            .unwrap();
        let observation_checkpoint_statement =
            DepositIndexCheckpointStatement::for_deposit_observation_transition(
                1_699_999_500,
                network,
                &registry,
                Some(&previous),
                &observation,
                &observation_transition,
            )
            .unwrap();
        assert_eq!(observation_checkpoint_statement.sequence(), 2);

        // ----- Drive the checkpoint BA lane to commit O at sequence s = 2. -----
        let observation_candidate =
            DepositIndexCheckpointCandidate::DepositObservation(observation.clone());
        let ledger_candidate = DepositIndexCheckpointCandidate::Ledger(losing_ledger.clone());
        let observation_value = observation_candidate.to_consensus_value().unwrap();
        let context = deposit_index_checkpoint_consensus_context(
            network,
            &registry,
            2,
            observation_checkpoint_statement.previous_head(),
        )
        .unwrap();
        let commit_witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                sign_consensus_message(
                    &context,
                    identity,
                    ConsensusMessageBody::Precommit(Vote {
                        view: 0,
                        value: observation_value.digest(),
                    }),
                )
                .unwrap()
            })
            .collect();
        let commit = CommitCertificate::from_witnesses(
            &context,
            0,
            observation_value.clone(),
            commit_witnesses,
        )
        .unwrap();
        let mut reducer = DepositConsensus::new(context, PartyId(1)).unwrap();
        reducer
            .handle_commit_certificate_with_validator(commit.clone(), |candidate| {
                candidate == &observation_value
            })
            .unwrap();
        let mut lane = DurableDepositCheckpointConsensusLane::new(
            DepositConsensusPurpose::NextIndexCheckpoint { sequence: 2 },
            reducer,
            1_699_999_800,
            1_700_000_999_000,
        )
        .unwrap();
        install_checkpoint_consensus_admission(
            &mut lane,
            1_699_999_700,
            observation_candidate.clone(),
        )
        .unwrap();
        protocol.checkpoint_consensus_lane = Some(lane);

        // The committed lane, not the fallback, selects O; the certified-but-losing L is blocked
        // from opening its own checkpoint at this sequence.
        assert!(protocol.committed_checkpoint_selection(&observation_candidate).is_ok());
        assert!(matches!(
            protocol.committed_checkpoint_selection(&ledger_candidate),
            Err(DepositServiceError::InvalidDepositIndexCheckpoint)
        ));

        // ----- The observation checkpoint STAGES (despite the certified ledger entry existing)
        // and COMPLETES an n-f witness round. -----
        let observation_artifact = WalletArtifactRef::for_contents(
            WalletId(protocol.ledger.wallet_id().0),
            CERTIFIED_DEPOSIT_OBSERVATION_ARTIFACT,
            &postcard::to_allocvec(&observation).unwrap(),
        )
        .unwrap();
        protocol
            .begin_deposit_observation_checkpoint(
                observation.clone(),
                observation_artifact,
                observation_checkpoint_statement.clone(),
                1_699_999_600,
            )
            .unwrap();
        // Another honest collector can freeze a different n-f subset for the same statement.
        // Retaining it must not delete the witnesses backing the already-committed BA value, and
        // adding the lower-numbered signer must not rewrite the frozen observation checkpoint to
        // the newly canonical first-n-f subset.
        let alternate_observation = CertifiedDepositObservation {
            statement: observation_statement,
            attestations: identities
                .values()
                .take(3)
                .map(|identity| {
                    sign_deposit_observation_attestation(
                        identity,
                        &registry,
                        &observation.statement,
                    )
                    .unwrap()
                })
                .collect(),
        };
        assert_ne!(observation.attestations, alternate_observation.attestations);
        protocol.retain_certified_deposit_observation(&alternate_observation).unwrap();
        let retained = &protocol.pending_observations[&observation.statement.output()];
        assert_eq!(
            retained.attestations.keys().copied().collect::<Vec<_>>(),
            vec![PartyId(1), PartyId(2), PartyId(3), PartyId(4)]
        );
        validate_checkpoint_candidate_for_protocol(
            &protocol,
            &DepositIndexCheckpointCandidate::DepositObservation(observation.clone()),
        )
        .unwrap();
        validate_checkpoint_candidate_for_protocol(
            &protocol,
            &DepositIndexCheckpointCandidate::DepositObservation(alternate_observation.clone()),
        )
        .unwrap();
        // A horizon reorganization can also yield a different fully certified statement for the
        // same immutable output fact. It is valid evidence, but it must not replace the exact
        // statement backing the already-committed checkpoint value.
        let mut replacement_horizon_hash = observation.statement.confirmation_horizon().hash;
        replacement_horizon_hash[0] ^= 0xff;
        let replacement_horizon = ChainPoint::new(
            observation.statement.confirmation_horizon().height,
            replacement_horizon_hash,
        )
        .unwrap();
        let replacement_statement = DepositObservationStatement::new(
            &registry,
            &allocation,
            observation.statement.output(),
            observation.statement.output_key(),
            observation.statement.index_on_blockchain(),
            observation.statement.amount_atomic_units(),
            observation.statement.observed_block(),
            observation.statement.block_timestamp(),
            replacement_horizon,
            observation.statement.confirmation_depth(),
        )
        .unwrap();
        assert_eq!(replacement_statement.fact_digest(), observation.statement.fact_digest());
        assert_ne!(replacement_statement.digest(), observation.statement.digest());
        let replacement_observation = CertifiedDepositObservation {
            statement: replacement_statement.clone(),
            attestations: identities
                .values()
                .take(3)
                .map(|identity| {
                    sign_deposit_observation_attestation(
                        identity,
                        &registry,
                        &replacement_statement,
                    )
                    .unwrap()
                })
                .collect(),
        };
        protocol.retain_certified_deposit_observation(&replacement_observation).unwrap();
        assert_eq!(
            protocol.pending_observations[&observation.statement.output()].statement,
            observation.statement,
            "a dominated same-fact certificate must not invalidate the committed checkpoint value",
        );
        validate_checkpoint_candidate_for_protocol(
            &protocol,
            &DepositIndexCheckpointCandidate::DepositObservation(observation.clone()),
        )
        .unwrap();
        protocol.validate(&deriver).unwrap();
        for identity in identities.values().take(3) {
            let witness = identity
                .sign_envelope(
                    &committee,
                    observation_checkpoint_statement.slot_session(),
                    None,
                    observation_checkpoint_statement.sequence(),
                    observation_checkpoint_statement.to_bytes().unwrap(),
                )
                .unwrap();
            protocol.accept_deposit_observation_checkpoint_witness(witness).unwrap();
        }
        let observation_checkpoint_certificate = protocol
            .completed_deposit_observation_checkpoint(network, Some(&previous))
            .unwrap()
            .expect("n-f observation checkpoint witnesses complete");
        protocol.validate(&deriver).unwrap();

        // ----- Restart: recovery resumes the committed O, not the certified-but-losing L. -----
        let encoded = protocol.encode_local(&deriver).unwrap();
        let mut restored = DepositLocalState::decode(
            &encoded,
            registry.clone(),
            protocol.ledger.clone(),
            &deriver,
            PartyId(1),
            network,
        )
        .unwrap();
        validate_checkpoint_candidate_for_protocol(
            &restored,
            &DepositIndexCheckpointCandidate::DepositObservation(observation.clone()),
        )
        .unwrap();
        validate_checkpoint_candidate_for_protocol(
            &restored,
            &DepositIndexCheckpointCandidate::DepositObservation(alternate_observation),
        )
        .unwrap();
        let restored_commit = restored
            .checkpoint_consensus_lane
            .as_ref()
            .and_then(|lane| lane.reducer.commit())
            .expect("committed checkpoint lane survives restart");
        assert_eq!(
            DepositIndexCheckpointCandidate::from_consensus_value(restored_commit.value()).unwrap(),
            observation_candidate,
            "restart must resume the committed observation, never the losing certified ledger"
        );
        assert!(restored.observation_checkpoint.is_some());
        assert!(restored.index_checkpoint.is_none());

        // ----- Adopt O: `checkpoint_sequence` advances (not a silent no-op) and the lane clears. -----
        restored.adopt_deposit_observation_checkpoint(&observation).unwrap();
        assert_eq!(restored.checkpoint_sequence, 2);
        assert!(restored.observation_checkpoint.is_none());
        assert!(restored.checkpoint_consensus_lane.is_none());
        assert!(!restored.pending_observations.contains_key(&observation.statement.output()));

        // ----- L now wins the following checkpoint sequence s + 1 = 3. -----
        let ledger_value = ledger_candidate.to_consensus_value().unwrap();
        let next_context = deposit_index_checkpoint_consensus_context(
            network,
            &registry,
            3,
            observation_checkpoint_statement.resulting_head(),
        )
        .unwrap();
        let next_commit_witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                sign_consensus_message(
                    &next_context,
                    identity,
                    ConsensusMessageBody::Precommit(Vote { view: 0, value: ledger_value.digest() }),
                )
                .unwrap()
            })
            .collect();
        let next_commit = CommitCertificate::from_witnesses(
            &next_context,
            0,
            ledger_value.clone(),
            next_commit_witnesses,
        )
        .unwrap();
        let mut next_reducer = DepositConsensus::new(next_context, PartyId(1)).unwrap();
        next_reducer
            .handle_commit_certificate_with_validator(next_commit, |candidate| {
                candidate == &ledger_value
            })
            .unwrap();
        let mut next_lane = DurableDepositCheckpointConsensusLane::new(
            DepositConsensusPurpose::NextIndexCheckpoint { sequence: 3 },
            next_reducer,
            1_699_999_900,
            1_700_000_999_000,
        )
        .unwrap();
        install_checkpoint_consensus_admission(
            &mut next_lane,
            1_699_999_950,
            ledger_candidate.clone(),
        )
        .unwrap();
        restored.checkpoint_consensus_lane = Some(next_lane);
        assert!(restored.committed_checkpoint_selection(&ledger_candidate).is_ok());
        assert!(matches!(
            restored.committed_checkpoint_selection(&observation_candidate),
            Err(DepositServiceError::InvalidDepositIndexCheckpoint)
        ));

        // Materialize the following ledger checkpoint as a third valid terminal pair. This models
        // an older offline catch-up pair followed by the two adjacent terminal decisions at a
        // registry boundary.
        let verified_observation_checkpoint = observation_checkpoint_certificate
            .verify_active_deposit_observation(network, &registry, Some(&previous), &observation)
            .unwrap();
        mem.apply(&observation_update);
        let losing_preflight =
            DepositIndexBuilder::new(&mem, observation_update.next_head().clone())
                .unwrap()
                .preflight_ledger_statement(&losing_ledger.statement)
                .unwrap();
        let mut losing_builder =
            DepositIndexBuilder::new(&mem, observation_update.next_head().clone()).unwrap();
        assert!(
            losing_builder.apply_verified_active_entry(&losing_ledger, &registry, None).unwrap()
        );
        let losing_update = losing_builder.finish().unwrap().unwrap();
        let losing_checkpoint_statement = DepositIndexCheckpointStatement::for_transition(
            1_699_999_950,
            network,
            &registry,
            None,
            Some(&verified_observation_checkpoint),
            &losing_ledger,
            &losing_preflight,
            &losing_update,
            &mem,
        )
        .unwrap();
        assert_eq!(losing_checkpoint_statement.sequence(), 3);
        let losing_selection =
            crate::deposit_index_checkpoint::certify_checkpoint_candidate_for_test(
                network,
                &registry,
                losing_checkpoint_statement.sequence(),
                losing_checkpoint_statement.previous_head(),
                ledger_candidate.clone(),
                &identities,
            );
        let losing_witnesses = identities
            .values()
            .take(3)
            .map(|identity| {
                identity
                    .sign_envelope(
                        &committee,
                        losing_checkpoint_statement.slot_session(),
                        None,
                        losing_checkpoint_statement.sequence(),
                        losing_checkpoint_statement.to_bytes().unwrap(),
                    )
                    .unwrap()
            })
            .collect();
        let losing_checkpoint_certificate = DepositIndexCheckpointCertificate::from_witnesses(
            network,
            &registry,
            None,
            Some(&verified_observation_checkpoint),
            &losing_ledger,
            losing_checkpoint_statement,
            losing_selection,
            losing_witnesses,
        )
        .unwrap();

        // ----- Offline peer catch-up: retain the earliest and two causal-latest terminal pairs. -----
        let ledger_artifact = WalletArtifactRef::for_contents(
            WalletId(protocol.ledger.wallet_id().0),
            CERTIFIED_LEDGER_ENTRY_ARTIFACT,
            &ledger_one.to_bytes().unwrap(),
        )
        .unwrap();
        let sync_context = DepositSyncContext::new(network, deriver.wallet_id()).unwrap();
        let ledger_binding = DepositIndexCheckpointLedgerBinding::new(
            sync_context,
            allocation_certificate.statement().sequence(),
            ledger_artifact,
            &ledger_one,
        )
        .unwrap();
        let observation_binding = DepositIndexCheckpointObservationBinding::new(
            sync_context,
            observation_checkpoint_certificate.statement().sequence(),
            observation_artifact,
            &observation,
        )
        .unwrap();
        let losing_ledger_artifact = WalletArtifactRef::for_contents(
            WalletId(protocol.ledger.wallet_id().0),
            CERTIFIED_LEDGER_ENTRY_ARTIFACT,
            &losing_ledger.to_bytes().unwrap(),
        )
        .unwrap();
        let losing_binding = DepositIndexCheckpointLedgerBinding::new(
            sync_context,
            losing_checkpoint_certificate.statement().sequence(),
            losing_ledger_artifact,
            &losing_ledger,
        )
        .unwrap();
        let ledger_body =
            postcard::to_allocvec(&DepositCertificateWire::new(ledger_one.clone())).unwrap();
        let ledger_checkpoint_body =
            DepositIndexCheckpointCertificateWire::new(ledger_binding, allocation_certificate)
                .unwrap()
                .to_bytes()
                .unwrap();
        let observation_body =
            postcard::to_allocvec(&DepositObservationCertificateWire::new(observation.clone()))
                .unwrap();
        let observation_checkpoint_body = DepositObservationIndexCheckpointCertificateWire::new(
            observation_binding,
            observation_checkpoint_certificate,
        )
        .unwrap()
        .to_bytes()
        .unwrap();
        let losing_ledger_body =
            postcard::to_allocvec(&DepositCertificateWire::new(losing_ledger)).unwrap();
        let losing_checkpoint_body = DepositIndexCheckpointCertificateWire::new(
            losing_binding,
            losing_checkpoint_certificate,
        )
        .unwrap()
        .to_bytes()
        .unwrap();
        let (mut runtime, _, _) = byzantine_authority_fixture();
        let recipient = PartyId(2);
        let oldest_ids = runtime
            .snapshot
            .enqueue_many([
                (
                    ledger_one.statement.sequence,
                    recipient,
                    DepositOperation::Certificate,
                    ledger_body,
                ),
                (
                    ledger_binding.checkpoint_sequence(),
                    recipient,
                    DepositOperation::IndexCheckpointCertificate,
                    ledger_checkpoint_body,
                ),
            ])
            .unwrap();
        let boundary_fence_ids = runtime
            .snapshot
            .enqueue_many([
                (
                    observation.statement.allocation_sequence(),
                    recipient,
                    DepositOperation::DepositObservationCertificate,
                    observation_body,
                ),
                (
                    observation_binding.checkpoint_sequence(),
                    recipient,
                    DepositOperation::DepositObservationIndexCheckpointCertificate,
                    observation_checkpoint_body,
                ),
            ])
            .unwrap();
        let boundary_handoff_ids = runtime
            .snapshot
            .enqueue_many([
                (
                    losing_binding.ledger_sequence(),
                    recipient,
                    DepositOperation::Certificate,
                    losing_ledger_body,
                ),
                (
                    losing_binding.checkpoint_sequence(),
                    recipient,
                    DepositOperation::IndexCheckpointCertificate,
                    losing_checkpoint_body,
                ),
            ])
            .unwrap();
        assert_eq!(runtime.snapshot.compact_terminal_catchup_outbox_in_place().unwrap(), 0);
        let all_retained = oldest_ids
            .iter()
            .chain(&boundary_fence_ids)
            .chain(&boundary_handoff_ids)
            .copied()
            .collect::<BTreeSet<_>>();
        assert_eq!(
            runtime.snapshot.outbox.keys().copied().collect::<BTreeSet<_>>(),
            all_retained,
            "an older offline pair must not evict either adjacent registry-boundary pair"
        );

        let bytes = runtime.snapshot.to_bytes().unwrap();
        let mut restarted_snapshot = DepositServiceSnapshot::from_bytes(&bytes).unwrap();
        assert_eq!(
            restarted_snapshot.outbox.keys().copied().collect::<BTreeSet<_>>(),
            all_retained
        );
        assert_eq!(restarted_snapshot.acknowledge(&[oldest_ids[0]]).unwrap(), 1);
        let checkpoint_only =
            DepositServiceSnapshot::from_bytes(&restarted_snapshot.to_bytes().unwrap()).unwrap();
        let after_operation_ack = std::iter::once(oldest_ids[1])
            .chain(boundary_fence_ids.iter().copied())
            .chain(boundary_handoff_ids.iter().copied())
            .collect::<BTreeSet<_>>();
        assert_eq!(
            checkpoint_only.outbox.keys().copied().collect::<BTreeSet<_>>(),
            after_operation_ack,
            "independently ACKing the oldest operation must preserve both boundary pairs"
        );

        restarted_snapshot = checkpoint_only;
        assert_eq!(restarted_snapshot.acknowledge(&[oldest_ids[1]]).unwrap(), 1);
        assert_eq!(restarted_snapshot.compact_terminal_catchup_outbox_in_place().unwrap(), 0);
        let boundary_restart =
            DepositServiceSnapshot::from_bytes(&restarted_snapshot.to_bytes().unwrap()).unwrap();
        let boundary_pairs = boundary_fence_ids
            .iter()
            .chain(&boundary_handoff_ids)
            .copied()
            .collect::<BTreeSet<_>>();
        assert_eq!(
            boundary_restart.outbox.keys().copied().collect::<BTreeSet<_>>(),
            boundary_pairs,
            "ACKing the older pair must leave both registry-boundary pairs restart-stable"
        );
        let mut final_restart = boundary_restart;
        assert_eq!(
            final_restart.acknowledge(&boundary_fence_ids).unwrap(),
            boundary_fence_ids.len()
        );
        let final_restart =
            DepositServiceSnapshot::from_bytes(&final_restart.to_bytes().unwrap()).unwrap();
        assert_eq!(
            final_restart.outbox.keys().copied().collect::<BTreeSet<_>>(),
            boundary_handoff_ids.into_iter().collect(),
            "the final boundary certificate pair must remain recoverable after its predecessor ACK"
        );
    }

    #[test]
    fn deposit_consensus_value_v5_rejects_old_versions_and_trailing_bytes() {
        let (protocol, _, identities, allocation) = protocol_fixture();
        let request = match &allocation.payload {
            LedgerPayload::Allocation(allocation) => {
                DepositAddressRequest { request: allocation.request, binding: allocation.binding }
            }
            _ => unreachable!("fixture is an allocation"),
        };
        let authority = client_request_authority(&protocol, &identities, PartyId(1), request);
        let current =
            DepositConsensusValue::allocation(allocation.clone(), authority.clone()).unwrap();
        let decoded = DepositConsensusValue::decode(&current).unwrap();
        assert_eq!(decoded.version, DEPOSIT_CONSENSUS_VALUE_VERSION);

        let stale = DepositConsensusValue {
            version: DEPOSIT_CONSENSUS_VALUE_VERSION - 1,
            statement: allocation,
            request_authority: Some(authority),
            terminal_evidence: None,
        };
        let stale = ConsensusValue::new(postcard::to_allocvec(&stale).unwrap()).unwrap();
        assert!(matches!(
            DepositConsensusValue::decode(&stale),
            Err(DepositServiceError::InvalidConsensusValue)
        ));

        let mut trailing = postcard::to_allocvec(&decoded).unwrap();
        trailing.push(0);
        let trailing = ConsensusValue::new(trailing).unwrap();
        assert!(matches!(
            DepositConsensusValue::decode(&trailing),
            Err(DepositServiceError::InvalidConsensusValue)
        ));
    }

    #[test]
    fn allocation_value_is_self_contained_and_rejects_mismatched_or_forged_authority() {
        let network = [0x55; 32];
        let (protocol, deriver, identities, allocation) = protocol_fixture();
        let allocation_payload = match &allocation.payload {
            LedgerPayload::Allocation(allocation) => allocation,
            _ => unreachable!("fixture is an allocation"),
        };
        let request = DepositAddressRequest {
            request: allocation_payload.request,
            binding: allocation_payload.binding,
        };
        let authority = client_request_authority(&protocol, &identities, PartyId(2), request);
        assert!(protocol.client_requests.is_empty());
        let value =
            DepositConsensusValue::allocation(allocation.clone(), authority.clone()).unwrap();
        let admitted_at =
            allocation_payload.created_at.checked_sub(ALLOCATION_ISSUANCE_LEAD_SECONDS).unwrap();
        let purpose = DepositConsensusPurpose::NextLedgerSlot { sequence: allocation.sequence };
        validate_deposit_consensus_value(
            &protocol,
            &deriver,
            None,
            &value,
            admitted_at,
            purpose,
            DepositConsensusAdmissionProvenance::Fresh,
            Some(network),
        )
        .unwrap();
        assert_eq!(
            DepositConsensusValue::decode(&value).unwrap().request_authority,
            Some(authority.clone()),
        );

        let other_binding = RequestBinding([0x61; 32]);
        let other_request = DepositAddressRequest {
            request: deposit_request_id_for_binding(other_binding),
            binding: other_binding,
        };
        let mismatched =
            client_request_authority(&protocol, &identities, PartyId(2), other_request);
        assert!(matches!(
            DepositConsensusValue::allocation(allocation.clone(), mismatched),
            Err(DepositServiceError::InvalidConsensusValue)
        ));

        let mut forged = authority;
        forged.registry[0] ^= 1;
        let forged_value = DepositConsensusValue::allocation(allocation, forged).unwrap();
        assert!(matches!(
            validate_deposit_consensus_value(
                &protocol,
                &deriver,
                None,
                &forged_value,
                admitted_at,
                purpose,
                DepositConsensusAdmissionProvenance::Fresh,
                Some(network),
            ),
            Err(DepositServiceError::InvalidConsensusValue)
        ));
    }

    #[test]
    fn initial_handoff_pin_rejects_fresh_allocation_but_preserves_certified_recovery() {
        let network = [0x55; 32];
        let (mut protocol, deriver, identities, allocation) = protocol_fixture();
        let allocation_payload = match &allocation.payload {
            LedgerPayload::Allocation(allocation) => allocation,
            _ => unreachable!("fixture is an allocation"),
        };
        let request = DepositAddressRequest {
            request: allocation_payload.request,
            binding: allocation_payload.binding,
        };
        let authority = client_request_authority(&protocol, &identities, PartyId(1), request);
        let value = DepositConsensusValue::allocation(allocation.clone(), authority).unwrap();
        let admitted_at =
            allocation_payload.created_at.checked_sub(ALLOCATION_ISSUANCE_LEAD_SECONDS).unwrap();
        let purpose = DepositConsensusPurpose::NextLedgerSlot { sequence: allocation.sequence };

        // Only marker presence matters to this admission boundary. The fully validated target is
        // installed by `begin_handoff`; the export root deliberately remains unavailable during
        // its first durable pin.
        protocol.pending_handoff = Some(compaction_epoch_public(&compaction_identity()));
        assert!(protocol.pending_handoff_root.is_none());
        assert!(matches!(
            validate_deposit_consensus_value(
                &protocol,
                &deriver,
                None,
                &value,
                admitted_at,
                purpose,
                DepositConsensusAdmissionProvenance::Fresh,
                Some(network),
            ),
            Err(DepositServiceError::InvalidConsensusValue)
        ));
        validate_deposit_consensus_value(
            &protocol,
            &deriver,
            None,
            &value,
            admitted_at,
            purpose,
            DepositConsensusAdmissionProvenance::QuorumBackedRecovery,
            Some(network),
        )
        .unwrap();
    }

    fn observation_statement(
        registry: &CompactEpochRegistry,
        allocation: &LedgerStatement,
        nonce: u64,
    ) -> DepositObservationStatement {
        observation_statement_at(registry, allocation, nonce, 20)
    }

    fn observation_statement_at(
        registry: &CompactEpochRegistry,
        allocation: &LedgerStatement,
        nonce: u64,
        observed_height: u64,
    ) -> DepositObservationStatement {
        let mut transaction = [0x41; 32];
        transaction[..8].copy_from_slice(&nonce.to_le_bytes());
        let mut output_key = [0x42; 32];
        output_key[..8].copy_from_slice(&nonce.to_le_bytes());
        let mut observed_hash = [0x43; 32];
        observed_hash[..8].copy_from_slice(&observed_height.to_le_bytes());
        DepositObservationStatement::new(
            registry,
            allocation,
            WalletOutputId { transaction, index_in_transaction: nonce },
            output_key,
            nonce.checked_add(100).unwrap(),
            10_000,
            ChainPoint::new(observed_height, observed_hash).unwrap(),
            1_700_000_020,
            ChainPoint::new(observed_height.checked_add(9).unwrap(), [0x44; 32]).unwrap(),
            10,
        )
        .unwrap()
    }

    #[tokio::test]
    async fn observation_checkpoint_preloads_allocation_aliases_and_replays_cold() {
        let (protocol, deriver, identities, _) = protocol_fixture();
        let registry = &protocol.registry;
        let parties = [PartyId(1), PartyId(2), PartyId(3)];
        let directory = tempfile::tempdir().unwrap();
        let seed = [0x59; 32];
        let checkpoint = DepositIndexStoreCheckpoint::empty(
            deriver.wallet_id(),
            PartyId(1),
            protocol.ledger.next_index(),
        )
        .unwrap();
        let mut store =
            DepositIndexStore::open(directory.path(), PartyId(1), &seed, checkpoint).await.unwrap();
        let mut builder = DepositIndexBuilder::new(&store, store.portable_head().clone()).unwrap();
        let mut first = None;
        // Split the HAMT so incidental cache warmth cannot supply every allocation alias.
        for marker in 1..=16_u8 {
            let anchor = builder.candidate_head().portable_anchor().unwrap();
            let binding = RequestBinding([marker; 32]);
            let statement = LedgerStatement::allocation(
                registry,
                anchor.through_sequence() + 1,
                anchor.ledger_head(),
                deposit_request_id_for_binding(binding),
                binding,
                deriver.derive(anchor.next_index()),
                ChainPoint::new(10, [0x33; 32]).unwrap(),
                1_700_000_000,
            )
            .unwrap();
            first.get_or_insert_with(|| statement.clone());
            let entry = certified_ledger_entry_for(statement, registry, &identities, &parties);
            assert!(builder.apply_verified_active_entry(&entry, registry, None).unwrap());
        }
        let update = builder.finish().unwrap().unwrap();
        let prepared = store.prepare_snapshot(vec![update]).await.unwrap();
        store.commit_prepared(&prepared, prepared.checkpoint()).await.unwrap();
        let checkpoint = store.checkpoint().clone();
        drop(store);

        let mut store =
            DepositIndexStore::open(directory.path(), PartyId(1), &seed, checkpoint.clone())
                .await
                .unwrap();
        let observation = certified_observation_for(
            observation_statement(registry, &first.unwrap(), 1),
            registry,
            &identities,
            &parties,
        );
        DepositService::preload_deposit_observation_paths(&mut store, &observation.statement)
            .await
            .unwrap();
        let mut builder = DepositIndexBuilder::new(&store, store.portable_head().clone()).unwrap();
        assert!(builder.apply_verified_active_deposit_observation(&observation, registry).unwrap());
        let update = builder.finish().unwrap().unwrap();
        update.verify_deposit_observation_transition(&store, &observation.statement).unwrap();
        let update = DepositIndexUpdate::from_bytes(&update.to_bytes().unwrap()).unwrap();
        drop(store);

        // Only the journal's recorded dependencies may warm this restarted verifier.
        let mut store =
            DepositIndexStore::open(directory.path(), PartyId(1), &seed, checkpoint).await.unwrap();
        let prepared = store.prepare_snapshot(vec![update]).await.unwrap();
        store.commit_prepared(&prepared, prepared.checkpoint()).await.unwrap();
        assert!(matches!(
            store
                .lookup_portable_state(PortableStateQuery::FirstUsed(observation.statement.index()))
                .await
                .unwrap(),
            Some(PortableStateRecord::FirstUse(_))
        ));
    }

    #[test]
    fn observation_readiness_retries_only_unsettled_local_allocation_state() {
        assert!(matches!(
            DepositService::require_deposit_observation_local_readiness(7, 8, false),
            Err(DepositServiceError::DepositObservationAheadOfPortableIndex {
                local_sequence: 7,
                required_sequence: 8,
            })
        ));
        assert!(matches!(
            DepositService::require_deposit_observation_local_readiness(8, 8, true),
            Err(DepositServiceError::Worker(DepositWorkerError::AllocationBackfillRequired))
        ));
        assert!(DepositService::require_deposit_observation_local_readiness(8, 8, false).is_ok());
        assert!(DepositService::require_deposit_observation_local_readiness(9, 8, false).is_ok());
    }

    fn byzantine_authority_fixture_for_network(
        network: [u8; 32],
    ) -> (DepositRuntime, ConsolidationConsensusSlot, [u8; 32]) {
        let (protocol, deriver, _, _) = protocol_fixture();
        let wallet = deriver.wallet_id();
        let anchor = ChainPoint::new(0, [0x91; 32]).unwrap();
        let worker =
            DepositWorkerState::new(&deriver, anchor, DepositWorkerConfig::default()).unwrap();
        let first_index = DepositSubaddressIndex::new(0, 1).unwrap();
        let deposit_index_checkpoint =
            DepositIndexStoreCheckpoint::empty(wallet, PartyId(1), first_index).unwrap();
        let active = protocol.registry.active();
        let target = VerifiedRegistryHandoffTarget::for_test(
            active.committee().clone(),
            active.fault_bound(),
            active.activation(),
            active.certified_activation_root(),
            wallet,
            active.key_id(),
            active.group_key(),
        )
        .unwrap();
        let pending_registry = prepare_compact_registry_genesis(
            &target,
            first_index,
            deposit_index_checkpoint.portable_head().digest(),
        )
        .unwrap();
        assert_eq!(pending_registry.proposed_head().registry(), &protocol.registry);
        let compact_registry_checkpoint = CompactRegistryStoreCheckpoint::settled(
            wallet,
            pending_registry.proposed_head().clone(),
        )
        .unwrap();
        let mut snapshot = DepositServiceSnapshot::new_archived(
            wallet,
            network,
            vec![1],
            anchor,
            DepositArchiveHead::empty(wallet).unwrap(),
            compact_registry_checkpoint,
            deposit_index_checkpoint,
        )
        .unwrap();
        snapshot.worker = Some(worker);
        let previous = protocol.ledger.head();
        let sequence = protocol.ledger.next_sequence();
        let height = if previous == [0; 32] { 0 } else { sequence };
        let slot = ConsolidationConsensusSlot::new(
            ConsensusBinding {
                domain: consolidation_intent_consensus_domain(),
                application: CONSOLIDATION_INTENT_APPLICATION.to_vec(),
                wallet: wallet.0,
                network,
                registry: active.registry_id().digest(),
                activation: active.activation_binding(),
            },
            active.committee(),
            active.fault_bound(),
            0,
            height,
            sequence,
            previous,
        )
        .unwrap();
        let consolidation = ConsolidationCoordinator::new(wallet).unwrap();
        (DepositRuntime { deriver, snapshot, protocol, consolidation }, slot, network)
    }

