    fn durable_byzantine_lane_fixture_for_network_and_tag(
        network: [u8; 32],
        tag: u8,
    ) -> (
        DepositRuntime,
        DurableByzantineConsensusLane,
        ConsensusValue,
        ByzantineConsensusValueAttachment,
        Vec<u8>,
        BTreeMap<PartyId, Identity>,
    ) {
        let (runtime, slot, _) = byzantine_authority_fixture_for_network(network);
        let (_, _, identities, _) = protocol_fixture();
        let context = slot.consensus_context().unwrap();
        let input = WalletOutputId { transaction: [tag; 32], index_in_transaction: 0 };
        let mut sweep = SweepPlan {
            id: SweepId([0; 32]),
            wallet: runtime.deriver.wallet_id(),
            sequence: 1,
            epoch: context.epoch(),
            destination_binding: [tag.wrapping_add(1); 32],
            at_tip: ChainPoint::new(1, [tag.wrapping_add(2); 32]).unwrap(),
            inputs: vec![input],
            total_input_atomic_units: 1_000,
        };
        sweep.id = SweepId(compaction_sweep_plan_commitment(&sweep));
        let prepared_intent = postcard::to_allocvec(&PreparedSweepIntentFixture {
            version: 1,
            plan: sweep.clone(),
            outgoing_view_key: [tag.wrapping_add(3); 32],
            decoy_inputs: vec![vec![tag.wrapping_add(4)]],
            fee_rate: FeeRate::new(1, 1).unwrap().serialize(),
            transaction_commitment: [tag.wrapping_add(5); 32],
            fee_atomic_units: 10,
        })
        .unwrap();
        let prepared = PreparedSweepIntent::decode(&prepared_intent).unwrap();
        let authorization = TransactionAuthorization::new(
            sweep.wallet,
            sweep.id,
            OpaqueIntentBinding::from_prepared_sweep_bytes(&prepared_intent),
            consolidation_input_set_binding(&sweep.inputs),
            sweep.destination_binding,
            runtime.deriver.root_spend_key(),
            1,
            sweep.total_input_atomic_units,
            prepared.fee_atomic_units(),
            100,
        )
        .unwrap();
        let plan =
            RoastViewPlan::derive(&slot, slot.committee(), slot.fault_bound(), &authorization)
                .unwrap();
        let attempt = AttemptBinding::new(
            plan.attempt(),
            context.epoch(),
            context.binding().registry,
            context.committee().digest(),
            context.binding().activation,
            authorization.root_group_key(),
            context.committee().threshold,
            plan.signers().to_vec(),
            [tag.wrapping_add(6); 32],
            plan.signing_session(),
            [tag.wrapping_add(7); 32],
        )
        .unwrap();
        let intent = ConsolidationIntent::new(&context, authorization, attempt.clone()).unwrap();
        let value = intent.to_consensus_value().unwrap();
        let binding = ConsolidationAttemptWireBinding::new(
            intent.authorization(),
            &attempt,
            plan.relay_seed(),
        )
        .unwrap();
        let attachment = ByzantineConsensusValueAttachment::new(
            &context,
            &slot,
            &value,
            binding.clone(),
            prepared_intent.clone(),
        )
        .unwrap();
        let admitted = ValidatedByzantineConsensusValue {
            value: value.clone(),
            binding,
            prepared_intent: prepared_intent.clone(),
            prepared_intent_digest: prepared.digest().unwrap(),
            slot_digest: slot.digest(),
            validated_worker_revision: runtime.snapshot.worker().unwrap().revision(),
        };
        let lane = DurableByzantineConsensusLane::new(
            slot,
            DepositConsensus::new(context, PartyId(1)).unwrap(),
            admitted,
            1_700_000_000_000,
            1_000,
        )
        .unwrap();
        (runtime, lane, value, attachment, prepared_intent, identities)
    }

