    #[test]
    fn revalidated_relay_and_certificate_replays_ignore_only_worker_revision() {
        let (_, mut lane, _, _, _, _) = durable_byzantine_lane_fixture();
        let durable = lane.clone();
        let original = durable.admitted_values.get(&durable.local_candidate).unwrap().clone();

        // Ordinary BA relays and the later commit-certificate catch-up reconstruct this same
        // admission after independently validating it at the worker's current revision.
        for revision_delta in [1_u64, 3] {
            let mut replay = original.clone();
            replay.validated_worker_revision =
                replay.validated_worker_revision.checked_add(revision_delta).unwrap();
            lane.install_revalidated_admission(replay).unwrap();
            assert_eq!(
                lane, durable,
                "an exact revalidated replay must retain the first durable local receipt"
            );
        }

        let (_, alternate_lane, _, _, _, _) =
            durable_byzantine_lane_fixture_for_network_and_tag([0x55; 32], 0xa7);
        let alternate =
            alternate_lane.admitted_values.get(&alternate_lane.local_candidate).unwrap();
        let mut mismatches = Vec::new();

        let mut changed_binding = original.clone();
        changed_binding.binding = alternate.binding.clone();
        mismatches.push(changed_binding);

        let mut changed_prepared_intent = original.clone();
        changed_prepared_intent.prepared_intent.push(0);
        mismatches.push(changed_prepared_intent);

        let mut changed_prepared_digest = original.clone();
        changed_prepared_digest.prepared_intent_digest[0] ^= 1;
        mismatches.push(changed_prepared_digest);

        let mut changed_slot = original;
        changed_slot.slot_digest[0] ^= 1;
        mismatches.push(changed_slot);

        for mismatch in mismatches {
            assert!(matches!(
                lane.install_revalidated_admission(mismatch),
                Err(DepositServiceError::InvalidByzantineConsolidationState)
            ));
            assert_eq!(
                lane, durable,
                "consensus-bound replay differences must not mutate the durable lane"
            );
        }
    }

    #[test]
    fn revalidated_admission_bound_preserves_exact_replay() {
        let (_, mut lane, _, _, _, _) = durable_byzantine_lane_fixture();
        let original = lane.admitted_values.get(&lane.local_candidate).unwrap().clone();
        for tag in 0..u8::try_from(MAX_ADMITTED_BYZANTINE_VALUES - 1).unwrap() {
            let (_, candidate, _, _, _, _) =
                durable_byzantine_lane_fixture_for_network_and_tag([0x55; 32], tag);
            let admitted =
                candidate.admitted_values.get(&candidate.local_candidate).unwrap().clone();
            lane.install_revalidated_admission(admitted).unwrap();
        }
        assert_eq!(lane.admitted_values.len(), MAX_ADMITTED_BYZANTINE_VALUES);
        let saturated = lane.clone();

        let mut exact_replay = original;
        exact_replay.validated_worker_revision =
            exact_replay.validated_worker_revision.checked_add(1).unwrap();
        lane.install_revalidated_admission(exact_replay).unwrap();
        assert_eq!(lane, saturated);

        let (_, candidate, _, _, _, _) =
            durable_byzantine_lane_fixture_for_network_and_tag([0x55; 32], 0xa7);
        let novel = candidate.admitted_values.get(&candidate.local_candidate).unwrap().clone();
        assert!(matches!(
            lane.install_revalidated_admission(novel),
            Err(DepositServiceError::ConsensusRequestPoolFull)
        ));
        assert_eq!(lane, saturated);
    }

